with source_rows as (
  select *
  from jsonb_to_recordset($catalog$[{"id":"e4e3090e-19cb-4d83-99e3-ec8aea17304a","content_key":"penntrain.course.pa-dhs-standalone-abuse-reporting","title":"Abuse, Neglect, and Exploitation Reporting: Annual Mandatory Reporter Training","summary":"The required annual deep-dive on Pennsylvania's Older Adult Protective Services Act (OAPSA) mandatory reporting duties for staff at personal care homes (PCH) and assisted living facilities (ALF): legal definitions, the reporting process, reporter protections, and recognizing financial exploitation. Grounded in 55 Pa. Code Sections 2600.65(g)(4) and 2800.65(j)(4).","category":"Abuse, Neglect, and Exploitation","duration_minutes":60,"video_count":0,"current_version_id":"29c80fca-dfb6-440e-af91-632fab380423","version_number":1,"published_at":"2026-07-24 05:16:09.770474+00","updated_at":"2026-07-24 05:16:09.770474+00","launch_path":"/app/courses/e4e3090e-19cb-4d83-99e3-ec8aea17304a"},{"id":"7de58ed3-64ec-4f21-b198-5287df705791","content_key":"penntrain.course.pa-nh-aide-abuse-prevention-reporting","title":"Abuse, Neglect, Exploitation, and Reporting for Nursing Home Aides","summary":"Develops recognition, immediate protection, reporting, evidence-preservation, and nonretaliation practices for suspected abuse, neglect, exploitation, mistreatment, and misappropriation. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":90,"video_count":0,"current_version_id":"8ea84f6a-7d4a-4a82-af41-c0b20d0cc5e9","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/7de58ed3-64ec-4f21-b198-5287df705791"},{"id":"4dae1327-5ffd-4dbf-ac36-8f44204d2a91","content_key":"penntrain.course.pa-nh-aide-accident-fall-transfer-safety","title":"Accident Prevention, Falls, and Transfer Safety for Nursing Home Aides","summary":"Builds resident-specific hazard recognition, safe transfer and mobility habits, fall response, equipment checks, and timely reporting without creating avoidable restraint. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":75,"video_count":0,"current_version_id":"e1dc2e01-1c15-4be1-b6ae-7c02a5ccf9b0","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/4dae1327-5ffd-4dbf-ac36-8f44204d2a91"},{"id":"4f1c1981-84e9-40c8-82c6-7092b88aeae7","content_key":"penntrain.course.pa-hos-aide-active-dying-symptom-escalation","title":"Active Dying, Comfort Observation, and Symptom Escalation for Hospice Aides","summary":"Prepares aides to recognize and report common end-of-life changes, provide assigned comfort measures, support families, and distinguish expected-plan guidance from urgent or unexpected concerns. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":90,"video_count":0,"current_version_id":"d572eb18-bd90-4178-996d-8f575616a07b","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/4f1c1981-84e9-40c8-82c6-7092b88aeae7"},{"id":"9f21a2e0-a945-4f43-8bb5-7f46b80c775f","content_key":"penntrain.course.pa-hha-aide-agency-policies-new-procedures","title":"Agency Policies, New Procedures, and Competency Remediation for Home Health Aides","summary":"Provides an employer-tailored annual module for policy updates, new technology, recurring quality risks, competency gaps, and safe implementation in varied home environments. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"f239c159-38a1-4334-b8f9-8ffec19e7bf2","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/9f21a2e0-a945-4f43-8bb5-7f46b80c775f"},{"id":"2e8769e5-eed6-4aa9-8884-9e208b99a948","content_key":"penntrain.course.pa-alr-2800-69-dementia-part-1","title":"ALF Dementia Annual Training Part 1: Foundations and Communication","summary":"One complete hour of the separate two-hour annual ALF dementia-specific requirement in 55 Pa. Code Section 2800.69. Part 1 covers disease foundations, personhood, communication, distress, acute change, rights, and practical application for all covered staff and volunteers. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"ALF Dementia-Specific Annual Training","duration_minutes":60,"video_count":0,"current_version_id":"171b4c1e-c1f2-41ee-887e-1d2810fb60a9","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/2e8769e5-eed6-4aa9-8884-9e208b99a948"},{"id":"76b5e141-02db-4741-a120-c24bd4b48a7f","content_key":"penntrain.course.pa-alr-2800-69-dementia-part-2","title":"ALF Dementia Annual Training Part 2: Applied Support, Safety, and Rights","summary":"The second complete hour of the separate two-hour annual ALF dementia-specific requirement in 55 Pa. Code Section 2800.69. Part 2 applies individualized support to daily living, environment, mobility, nutrition, meaningful activity, safety, team review, and resident rights. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"ALF Dementia-Specific Annual Training","duration_minutes":60,"video_count":0,"current_version_id":"b765a920-1cf1-421a-8bd5-586a401e2fad","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/76b5e141-02db-4741-a120-c24bd4b48a7f"},{"id":"cadfbe15-9bb9-4d8a-b58d-0fc4c7dfc802","content_key":"penntrain.course.pa-alr-2800-236-dementia-scu-starter","title":"ALF Dementia Special Care Unit: Annual Eight-Hour Curriculum","summary":"A structured eight-hour annual curriculum for direct care staff working in an ALF special care unit for residents with Alzheimer's disease or related disorders under 55 Pa. Code Section 2800.236. It is additional to other Chapter 2800 training. Credit is verified-only; all hours are structured instruction and application, not on-the-job training. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability an","category":"ALF Dementia Special Care Unit Annual Training","duration_minutes":480,"video_count":0,"current_version_id":"79068173-b123-4df2-93df-dbfb6986c5fe","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/cadfbe15-9bb9-4d8a-b58d-0fc4c7dfc802"},{"id":"6b64d798-91c3-4220-a7fc-694ae5bc7ff3","content_key":"penntrain.course.pa-alr-2800-236-inrbi-starter","title":"ALF INRBI Special Care Unit: Annual Eight-Hour Curriculum","summary":"A structured eight-hour annual curriculum for direct care staff working in an ALF special care unit for individuals with neurocognitive impairments from a brain injury under 55 Pa. Code Section 2800.236. It covers required dementia-unit topics plus brain-injury-specific coaching, cueing, problem solving, self-soothing, and fading of supports. Credit is verified-only and is not on-the-job training. Course completion is learning evidence, not automatic regulatory approval; the employing facility m","category":"ALF INRBI Special Care Unit Annual Training","duration_minutes":480,"video_count":0,"current_version_id":"0a0f174d-720a-4fbb-b6d6-177e616fe1fb","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/6b64d798-91c3-4220-a7fc-694ae5bc7ff3"},{"id":"f236bd74-37d3-48b2-b1a6-7d1d341ab8be","content_key":"penntrain.course.pa-alr-annual-assisted-living-services","title":"ALF: Assisted Living Services and Aging in Place","summary":"A complete ALF annual course on resident-directed assisted living services, service coordination, independence, aging in place, risk review, and transitions. Verified-only credit requires residence-specific application and skills validation. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"ALF Annual Required Topics","duration_minutes":150,"video_count":0,"current_version_id":"890e7890-7620-459e-a18d-1a4ea805b895","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/f236bd74-37d3-48b2-b1a6-7d1d341ab8be"},{"id":"112cc1ae-6c5e-4ed4-b15f-1af5b052aff6","content_key":"penntrain.course.pa-alr-annual-assessed-needs","title":"ALF: Meeting Assessed Resident Needs","summary":"A complete ALF annual course on using the assessment tool, medical evaluation, support plan, service coordination, and aging-in-place decision process. Credit is verified-only because the residence must validate use of its records, policies, service partners, and escalation workflow. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"ALF Annual Required Topics","duration_minutes":120,"video_count":0,"current_version_id":"78054c93-f6b4-4e95-82a4-1a8bafa1e7a8","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/112cc1ae-6c5e-4ed4-b15f-1af5b052aff6"},{"id":"e92bbc28-81f7-5de2-884c-c526465647d7","content_key":"penntrain.course.pa-pch-diabetes-annual","title":"Annual Diabetes Patient Education for Pennsylvania Personal Care Homes","summary":"Annual Diabetes Patient Education designed to address the training requirements of 55 Pa. Code Section 2600.190(b), for Pennsylvania personal care home (PCH) staff who administer insulin or provide diabetes-related care. Twelve modules cover diabetes and the role of PCH staff, blood glucose monitoring, hypoglycemia, hyperglycemia and diabetic emergencies, insulin types, insulin storage and handling, reading the order and the MAR, drawing up insulin, insulin pens, subcutaneous administration, med","category":"Diabetes and Insulin Safety","duration_minutes":240,"video_count":12,"current_version_id":"e4bac606-1e4d-502d-ad34-017266b664cb","version_number":2,"published_at":"2026-08-30 15:23:41.873644+00","updated_at":"2026-08-30 15:23:41.873644+00","launch_path":"/app/courses/e92bbc28-81f7-5de2-884c-c526465647d7"},{"id":"76a23b41-e3bd-4e5c-af3c-d44c01e003fc","content_key":"penntrain.course.pa-nh-aide-behavioral-health-person-centered","title":"Behavioral Health and Person-Centered Support for Nursing Home Aides","summary":"Builds respectful observation and response skills for behavioral health needs, trauma histories, substance-use concerns, distress, and crisis warning signs. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":45,"video_count":0,"current_version_id":"5404149f-d8ff-4353-ba95-99c69ca46645","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/76a23b41-e3bd-4e5c-af3c-d44c01e003fc"},{"id":"03b17550-20d4-4a4c-8804-baa191f39f20","content_key":"penntrain.course.pa-gh-6400-rights-foundations","title":"Chapter 6400 Individual Rights","summary":"Comprehensive annual training on dignity, privacy, choice, access, property, communication, food, healthcare decisions, and freedom from abuse and unnecessary restriction.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"3734654a-40a9-4ba9-9416-c1273dece254","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/03b17550-20d4-4a4c-8804-baa191f39f20"},{"id":"67d330e9-00fa-41e4-860d-691404fe8921","content_key":"penntrain.course.pa-hos-aide-comfort-hygiene-oral-continence","title":"Comfort-Focused Hygiene, Oral Care, and Continence Support for Hospice Aides","summary":"Builds gentle, goal-concordant personal care that balances cleanliness, comfort, energy, privacy, skin protection, oral moisture, continence, and patient choice. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":90,"video_count":0,"current_version_id":"53fa757a-bea5-425b-a714-18ad1e99f6ff","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/67d330e9-00fa-41e4-860d-691404fe8921"},{"id":"5538f680-ac53-4a29-92ed-b78c2e753c25","content_key":"penntrain.course.pa-hos-aide-communication-privacy-grief","title":"Communication, Privacy, and Grief Support for Hospice Aides","summary":"Builds presence, listening, accessible communication, privacy, cultural humility, anticipatory-grief awareness, and appropriate referral without counseling beyond role. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"585f03a2-a686-4ba0-b5f7-ae33908921de","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/5538f680-ac53-4a29-92ed-b78c2e753c25"},{"id":"e55424d9-71b7-4afe-9724-150d897dd80a","content_key":"penntrain.course.pa-gh-6400-community-relationships","title":"Community Integration and Supporting Relationships","summary":"A comprehensive Chapter 6400 course on belonging, ordinary community participation, relationship support, transportation planning, and removing program-created barriers. After the home verifies audience, applicability, and evidence, the course may contribute two designed annual-training hours.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"eaf11bf8-3870-414f-b764-99795db3a742","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/e55424d9-71b7-4afe-9724-150d897dd80a"},{"id":"e8f4b578-7817-4397-a3ee-9133dd406191","content_key":"penntrain.course.pa-nh-aide-dementia-cognitive-care","title":"Dementia and Cognitive-Impairment Care for Nursing Home Aides","summary":"Builds practical skills for recognizing cognitive change, communicating respectfully, preventing avoidable distress, and supporting person-centered routines for residents with dementia or other cognitive impairment. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":90,"video_count":0,"current_version_id":"7e2b6e23-49f3-4510-8229-c1e0b1e7124a","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/e8f4b578-7817-4397-a3ee-9133dd406191"},{"id":"7cc868fe-0686-4826-9dc6-5d42336b9a47","content_key":"penntrain.course.pa-dhs-annual-dementia-cognitive-neuro","title":"Dementia, Cognitive, and Neurological Support","summary":"A complete person-centered annual course for the PCH dementia and cognitive-impairment topic and the broader ALF dementia, cognitive, and neurological-impairment topic. The 90-minute curriculum supports a 1.00-hour PCH allocation and a 1.50-hour ALF allocation. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"PCH and ALF Annual Required Topics","duration_minutes":90,"video_count":0,"current_version_id":"7d674ce2-153b-4273-bc9c-860fcae6b2af","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/7cc868fe-0686-4826-9dc6-5d42336b9a47"},{"id":"0928952d-f315-4dc5-a0ff-11e3c05561dc","content_key":"penntrain.course.pa-hha-aide-documentation-care-coordination","title":"Documentation and Care Coordination for Home Health Aides","summary":"Builds timely, objective home-visit records and reliable communication with the supervising nurse and interdisciplinary team. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"9fd3824b-24f1-42b7-b093-46263af6d77e","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/0928952d-f315-4dc5-a0ff-11e3c05561dc"},{"id":"c88ff230-e280-4e8f-b844-17bc82d9d024","content_key":"penntrain.course.pa-nh-aide-emergency-fire-preparedness","title":"Emergency and Fire Preparedness for Nursing Home Aides","summary":"Prepares aides to carry out assigned emergency roles for fire, evacuation, sheltering, severe weather, utility failure, missing residents, and acute medical events. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"d263c351-9707-47a7-bc71-7260392f2d27","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/c88ff230-e280-4e8f-b844-17bc82d9d024"},{"id":"ff5cfdb7-3765-445b-8b29-46fc840f2ddb","content_key":"penntrain.course.pa-hos-aide-emergency-vs-expected-decline","title":"Emergency Events Versus Expected Decline for Hospice Aides","summary":"Provides a concise decision framework for following patient-specific hospice instructions when a change may reflect expected decline, urgent symptom need, injury, or emergency. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":30,"video_count":0,"current_version_id":"4ea4432e-ee34-4c0b-bb2d-54d3666e7388","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/ff5cfdb7-3765-445b-8b29-46fc840f2ddb"},{"id":"b1ad4cb0-e9eb-489f-9a38-b65bd752dfdb","content_key":"penntrain.course.pa-dhs-annual-emergency-prep","title":"Emergency Preparedness and Resident Protection","summary":"A complete annual emergency-preparedness course on all-hazards planning, resident needs, communication, shelter or evacuation, continuity, accountability, documentation, and recovery. Credit is verified-only because facility plans, contacts, resources, roles, and drills must be validated. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"PCH and ALF Annual Required Topics","duration_minutes":90,"video_count":0,"current_version_id":"77cad196-64a8-44c3-a950-2c5d04877f30","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/b1ad4cb0-e9eb-489f-9a38-b65bd752dfdb"},{"id":"29c5d1d2-dc44-56d4-8511-a274750db906","content_key":"penntrain.course.pa-dhs-standalone-emergency-prep","title":"Emergency Preparedness Beyond Fire: Annual Training for PCH and ALF Staff","summary":"The required annual refresher on the emergencies that do not sound an alarm, including power and utility loss, severe weather, a missing resident, medical emergencies, and security events, for staff at Pennsylvania personal care homes (PCH) and assisted living facilities (ALF). Grounded in 55 Pa. Code Sections 2600.65(g)(2) and 2800.65(j)(2).","category":"Emergency Preparedness","duration_minutes":60,"video_count":10,"current_version_id":"0515864b-7d3b-5990-b991-48a472ecd057","version_number":2,"published_at":"2026-07-25 17:44:49.084641+00","updated_at":"2026-07-25 17:44:49.084641+00","launch_path":"/app/courses/29c5d1d2-dc44-56d4-8511-a274750db906"},{"id":"ecb3a79a-b428-5d92-99ec-73f190ad60c1","content_key":"penntrain.course.pa-dhs-standalone-falls-prevention","title":"Falls and Accident Prevention: Annual Training for PCH and ALF Staff","summary":"The required annual refresher on why residents fall, the environmental and medication risks staff can remove, safe assistance and transfers within your trained scope, and what to do in the minutes after a fall, for staff at Pennsylvania personal care homes (PCH) and assisted living facilities (ALF). Grounded in 55 Pa. Code Sections 2600.65(g)(5) and 2800.65(j)(5).","category":"Falls and Accident Prevention","duration_minutes":60,"video_count":10,"current_version_id":"edc5dd31-ec5c-5879-a532-8fda7d8dedd4","version_number":2,"published_at":"2026-07-25 15:07:53.894761+00","updated_at":"2026-07-25 15:07:53.894761+00","launch_path":"/app/courses/ecb3a79a-b428-5d92-99ec-73f190ad60c1"},{"id":"395123a9-9dc4-424a-aaec-0a74ff766098","content_key":"penntrain.course.pa-dhs-annual-falls-prevention","title":"Falls Prevention and Post-Fall Response","summary":"A complete annual course on multifactorial fall risk, environment, mobility, transfers, footwear, toileting, medication and health observations, resident choice, immediate post-fall response, documentation, and team prevention. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"PCH and ALF Annual Required Topics","duration_minutes":120,"video_count":0,"current_version_id":"d8b3ccb7-3df2-4d5f-aa0f-a59d4722fcd1","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/395123a9-9dc4-424a-aaec-0a74ff766098"},{"id":"52454d2d-41bd-4077-a0ed-90445373af2e","content_key":"penntrain.course.pa-hos-aide-family-support-boundaries","title":"Family Support, Caregiver Teaching Boundaries, and Professional Conduct for Hospice Aides","summary":"Builds supportive caregiver interaction, observation of caregiver strain, approved reinforcement of teaching, conflict referral, privacy, safety, and professional boundaries. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"05b9e06f-7cfe-4648-a552-a19ba636da55","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/52454d2d-41bd-4077-a0ed-90445373af2e"},{"id":"221245ad-fcb2-431f-b929-e745014a51c2","content_key":"penntrain.course.pa-dhs-standalone-fire-safety","title":"Fire Safety and Emergency Preparedness: Annual Refresher for PCH and ALF Staff","summary":"The required annual refresher on fire prevention, initial emergency response, and evacuating residents who need help, for staff at Pennsylvania personal care homes (PCH) and assisted living facilities (ALF). Grounded in 55 Pa. Code Sections 2600.65(g)(1) and 2800.65(j)(1).","category":"Fire Safety and Emergency Preparedness","duration_minutes":60,"video_count":0,"current_version_id":"e9a093ff-3487-446a-bd88-df1c23f590c5","version_number":1,"published_at":"2026-07-24 05:16:09.770474+00","updated_at":"2026-07-24 05:16:09.770474+00","launch_path":"/app/courses/221245ad-fcb2-431f-b929-e745014a51c2"},{"id":"6e1c1e1e-ef1f-41cb-8df8-a435e9b9b6bb","content_key":"penntrain.course.pa-dhs-annual-fire-safety-prep","title":"Fire Safety Preparedness and Facility Procedures","summary":"A complete annual fire-safety course covering prevention, alarm and notification, resident protection, evacuation or relocation concepts, smoke and door control, accountability, and post-event duties. Credit is verified-only because facility-specific drills, routes, systems, assignments, and resident needs must be validated onsite. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the ev","category":"PCH and ALF Annual Required Topics","duration_minutes":45,"video_count":0,"current_version_id":"dea1b237-c0d8-4835-a238-899049a32b47","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/6e1c1e1e-ef1f-41cb-8df8-a435e9b9b6bb"},{"id":"b5486343-a186-43da-99c9-02eefe655029","content_key":"penntrain.course.pa-gh-6400-emergency-readiness","title":"General Emergency Readiness and Continuity","summary":"Job-skills annual training on hazard recognition, emergency roles, evacuation support, accountability, continuity, and after-action learning. It does not replace verified annual fire-safety or first-aid/CPR training.","category":"Pennsylvania Chapter 6400","duration_minutes":60,"video_count":0,"current_version_id":"5ff9d298-8f8c-4166-a884-5f8d3802efb2","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/b5486343-a186-43da-99c9-02eefe655029"},{"id":"a4843eda-0c5a-42f5-a895-14c87be34d64","content_key":"penntrain.course.pa-gh-6400-health-safety","title":"Health Observation, Infection Prevention, and Individual Emergencies","summary":"Job-skills annual training on recognizing health change, infection prevention, safe support, and individual emergency plans; not clinical licensure or skills certification.","category":"Pennsylvania Chapter 6400","duration_minutes":60,"video_count":0,"current_version_id":"7f4c6dd8-9ae0-4e31-8b65-632e6f9c420a","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/a4843eda-0c5a-42f5-a895-14c87be34d64"},{"id":"14241e55-ddcd-47e7-9eee-f4b938c396fc","content_key":"penntrain.course.pa-hha-aide-home-safety-emergencies","title":"Home Safety and Emergency Response for Home Health Aides","summary":"Prepares aides to recognize environmental risk, follow individualized emergency plans, respond to acute events, and manage unsafe home or visit conditions. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"eb81dbb4-e694-49c5-9359-6c5cd408595f","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/14241e55-ddcd-47e7-9eee-f4b938c396fc"},{"id":"deccf03a-6acf-4152-a326-b69c6e9b0508","content_key":"penntrain.course.pa-hos-aide-hospice-philosophy-idg-plan","title":"Hospice Philosophy, Interdisciplinary Care, and the Aide Plan","summary":"Introduces goal-concordant hospice care, the interdisciplinary group, the aide's plan-directed role, and reliable reporting that supports comfort and continuity. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"16db15ed-f580-41de-ab92-98436b9dec87","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/deccf03a-6acf-4152-a326-b69c6e9b0508"},{"id":"3160d132-fc97-41ca-9e45-0a4f2db9c632","content_key":"penntrain.course.pa-hos-aide-agency-specific-new-skill","title":"Hospice Policy Updates and New-Skill Competency","summary":"Provides an employer-tailored annual module for policy changes, new devices and procedures, performance remediation, quality priorities, and competency evidence. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":30,"video_count":0,"current_version_id":"0cfd95c3-d6a9-4893-a95f-0f636fc0fd72","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/3160d132-fc97-41ca-9e45-0a4f2db9c632"},{"id":"4d22aecb-e892-41b5-ac4f-c2f8d4a119e8","content_key":"penntrain.course.pa-gh-6400-incident-documentation","title":"Incident Documentation, Investigation, and Prevention","summary":"Applied annual training on objective records, certified-investigation boundaries, corrective action, trend analysis, and prevention.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"cb9cbb24-66d5-4999-a94a-4ce74d6c99f0","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/4d22aecb-e892-41b5-ac4f-c2f8d4a119e8"},{"id":"ed263d6a-3d9a-453b-8340-3ead4c86dc4f","content_key":"penntrain.course.pa-dhs-annual-infection-immobility","title":"Infection Control, Universal Precautions, and Immobility","summary":"A complete annual course on infection prevention, standard and transmission-based precautions, exposure response, mobility-related complications, and safe resident support. The 135-minute curriculum carries 1.75 PCH hours and 2.25 ALF hours. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"PCH and ALF Annual Required Topics","duration_minutes":135,"video_count":0,"current_version_id":"713a8be8-63a9-45fb-8b45-51196348dc7d","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/ed263d6a-3d9a-453b-8340-3ead4c86dc4f"},{"id":"971c3cc0-e53e-4d42-bfff-3300454ed242","content_key":"penntrain.course.pa-nh-aide-infection-prevention","title":"Infection Prevention and Control for Nursing Home Aides","summary":"Applies standard precautions, transmission-based directions, hand hygiene, personal protective equipment, cleaning boundaries, and early reporting to routine nursing-home care. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"f19e0cb2-93b2-4a3d-8a80-ccad3011d3b1","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/971c3cc0-e53e-4d42-bfff-3300454ed242"},{"id":"52fd1194-e9a4-54b5-9003-44f0f282000f","content_key":"penntrain.course.pa-dhs-standalone-infection-control","title":"Infection Prevention and Control: Annual Training for PCH and ALF Staff","summary":"The required annual refresher on hand hygiene, standard precautions, personal protective equipment, environmental cleaning, and the immobility risks that travel with infection, for staff at Pennsylvania personal care homes (PCH) and assisted living facilities (ALF). Grounded in 55 Pa. Code Sections 2600.65(f)(4) and 2800.65(i)(4).","category":"Infection Control","duration_minutes":60,"video_count":10,"current_version_id":"0afc5905-d644-5ab1-aad4-b3ec5bd0c52d","version_number":2,"published_at":"2026-07-25 15:35:58.03246+00","updated_at":"2026-07-25 15:35:58.03246+00","launch_path":"/app/courses/52fd1194-e9a4-54b5-9003-44f0f282000f"},{"id":"7f3fbb32-b9d9-4d5c-a67c-1adb289cf293","content_key":"penntrain.course.pa-hos-aide-infection-prevention","title":"Infection Prevention for Hospice Aides","summary":"Applies standard precautions, hand hygiene, PPE, clean-bag technique, equipment handling, exposure response, and compassionate precaution practices across hospice settings. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"4c2051cc-79c6-46a1-9d50-41ced0c54e87","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/7f3fbb32-b9d9-4d5c-a67c-1adb289cf293"},{"id":"7ad00f01-f113-484c-998a-70ca914905d9","content_key":"penntrain.course.pa-hha-aide-infection-prevention","title":"Infection Prevention in the Home for Home Health Aides","summary":"Adapts standard precautions, hand hygiene, PPE, clean-bag technique, equipment handling, exposure response, and symptom reporting to varied home environments. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"e4e58ae6-4ac2-4a16-9858-c277b1700c5b","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/7ad00f01-f113-484c-998a-70ca914905d9"},{"id":"eab610ad-9bde-4fb9-91c6-200f25b2d6f1","content_key":"penntrain.course.pa-hha-aide-medication-assistance-scope","title":"Medication Assistance and Scope Boundaries for Home Health Aides","summary":"Clarifies safe assistance with ordinarily self-administered medications, observation and reporting, refusal response, storage concerns, and firm boundaries against unauthorized administration or changes. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":30,"video_count":0,"current_version_id":"27a278dd-2e3d-498a-8cd1-453ead4564a3","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/eab610ad-9bde-4fb9-91c6-200f25b2d6f1"},{"id":"3a89ebb4-d89d-41f2-8cc0-9440e1417f57","content_key":"penntrain.course.pa-gh-6400-med-safety-awareness","title":"Medication Safety Awareness for Chapter 6400 Staff","summary":"Awareness training on medication rights, observation, errors, refusals, adverse reactions, and records. It does not authorize medication administration or replace Department-approved training, renewal, practicum, diabetes education, or epinephrine training.","category":"Pennsylvania Chapter 6400","duration_minutes":60,"video_count":0,"current_version_id":"37c713b3-8acd-4f2c-b649-960f02974df3","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/3a89ebb4-d89d-41f2-8cc0-9440e1417f57"},{"id":"f41795c1-eafe-492f-b4e5-f046b71cbf2a","content_key":"penntrain.course.pa-dhs-annual-med-self-admin","title":"Medication Self-Administration Support for PCH and ALF","summary":"A complete annual course on supporting resident medication self-administration in Pennsylvania personal care homes and assisted living facilities. The course teaches assessment-based assistance, observation, documentation, refusal response, and escalation. It does not authorize medication administration, satisfy medication-administration training or a practicum, or provide administrator continuing-education credit. Course completion is learning evidence, not automatic regulatory approval; the em","category":"PCH and ALF Annual Required Topics","duration_minutes":45,"video_count":0,"current_version_id":"7d8dd796-8c88-4228-a432-bebf33db758a","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/f41795c1-eafe-492f-b4e5-f046b71cbf2a"},{"id":"704324fe-a160-5397-9157-7c6d1e1d1e6f","content_key":"penntrain.course.pa-dhs-standalone-med-self-admin","title":"Medication Self-Administration Support: Annual Training for PCH and ALF Staff","summary":"The required annual refresher on supporting residents who self-administer their medications, the boundary between assistance and administration, safe storage and documentation, and the observations staff must report, for staff at Pennsylvania personal care homes (PCH) and assisted living facilities (ALF). Grounded in 55 Pa. Code Sections 2600.65(f)(1) and 2800.65(i)(1). This course never authorizes medication administration.","category":"Medication Self-Administration Support","duration_minutes":60,"video_count":10,"current_version_id":"3c06e92e-153b-5fee-96db-a5212f23286b","version_number":2,"published_at":"2026-07-25 18:02:11.285676+00","updated_at":"2026-07-25 18:02:11.285676+00","launch_path":"/app/courses/704324fe-a160-5397-9157-7c6d1e1d1e6f"},{"id":"65229cef-7042-4358-a93a-89176e7ff26f","content_key":"penntrain.course.pa-dhs-annual-mental-illness-id","title":"Mental Illness and Intellectual Disability Support","summary":"A conditional annual course for homes or residences serving residents with mental illness or intellectual disability. It addresses person-centered support, communication, crisis warning signs, rights, health differentials, and coordination. Applicability and credit require facility verification. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory cre","category":"Conditional PCH and ALF Annual Topics","duration_minutes":60,"video_count":0,"current_version_id":"42a3cdcc-6d47-4ae6-ba69-97d293d41a7e","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/65229cef-7042-4358-a93a-89176e7ff26f"},{"id":"e2c03f97-74e5-4fb7-b4f1-ced867d37950","content_key":"penntrain.course.pa-orient-new-employee-pch-alf","title":"New Employee Orientation for Personal Care Home and Assisted Living Facility Staff","summary":"Every new hire's first required training at a Pennsylvania personal care home (PCH) or assisted living facility (ALF): general fire safety and emergency orientation, resident rights, mandatory abuse and neglect reporting, emergency medical plans and incident reporting, safe management and role boundaries, two realistic first-shift scenarios, and a facility-specific verification checklist. Taught personally, on video, by Kevin Deyarmin, founder of CareMetric CareBase and a career senior-care admi","category":"New Employee Orientation","duration_minutes":180,"video_count":3,"current_version_id":"23ca08d4-afef-4b88-9db6-2f693d58588f","version_number":1,"published_at":"2026-07-24 04:22:43.927651+00","updated_at":"2026-07-24 04:39:12.9705+00","launch_path":"/app/courses/e2c03f97-74e5-4fb7-b4f1-ced867d37950"},{"id":"e63e8dc4-a236-4fbf-89fb-d39011767aa7","content_key":"penntrain.course.pa-dhs-annual-new-populations","title":"New Population Needs and Service Adaptation","summary":"A conditional annual course for facilities serving a population new to that home or residence. It teaches structured needs analysis, cultural and communication access, risk and resource review, staff preparation, service adaptation, and monitoring. Applicability and local readiness require facility verification. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awardi","category":"Conditional PCH and ALF Annual Topics","duration_minutes":45,"video_count":0,"current_version_id":"3f99b5bf-089a-4d6d-8fa0-e39d40c6cb4c","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/e63e8dc4-a236-4fbf-89fb-d39011767aa7"},{"id":"724a8596-2bb0-4d59-8f7d-1704b2f29e7e","content_key":"penntrain.course.pa-hha-aide-nutrition-hydration-safe-feeding","title":"Nutrition, Hydration, and Safe Feeding for Home Health Aides","summary":"Applies diet verification, meal support, swallowing precautions, intake observation, food safety, and timely escalation to home-based care. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"292882da-b92f-4bd5-9d6d-b32484dc001f","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/724a8596-2bb0-4d59-8f7d-1704b2f29e7e"},{"id":"8d6c4c38-4c49-431d-8b85-3167a348fabb","content_key":"penntrain.course.pa-hos-aide-nutrition-hydration-swallowing","title":"Nutrition, Hydration, and Swallowing Support for Hospice Aides","summary":"Applies comfort goals, patient choice, diet and swallowing directions, safe assistance, oral comfort, intake observation, and noncoercive family support. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"2d4cd520-0243-4a32-8656-e7e140d262b6","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/8d6c4c38-4c49-431d-8b85-3167a348fabb"},{"id":"6433cedb-8a69-466c-8487-46563babbb61","content_key":"penntrain.course.pa-hos-aide-observation-reporting-documentation","title":"Observation, Reporting, and Documentation for Hospice Aides","summary":"Develops baseline-aware observation, symptom communication, closed-loop escalation, and accurate hospice-aide records without diagnosis or independent plan changes. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"c7abdd9e-af5d-4e33-8a4d-e7ad0bffed7b","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/6433cedb-8a69-466c-8487-46563babbb61"},{"id":"66bbb941-75cc-4877-8dab-f5c6cec9d9f2","content_key":"penntrain.course.pa-hha-aide-observation-vitals-escalation","title":"Observation, Vital Signs, and Escalation for Home Health Aides","summary":"Develops accurate observation, assigned measurement, comparison with baseline, and timely escalation of acute or meaningful changes in the home. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":90,"video_count":0,"current_version_id":"c647500e-73dc-4f45-a274-8909bd9c5226","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/66bbb941-75cc-4877-8dab-f5c6cec9d9f2"},{"id":"2614e855-77b7-4747-b0d0-2aa4cbf7f5cb","content_key":"penntrain.course.pa-dhs-annual-oapsa-reporting","title":"Older Adult Protective Services: Recognition and Reporting","summary":"A complete guided annual module on the Older Adults Protective Services Act topic, recognition of abuse, neglect, exploitation, abandonment, and urgent danger, preservation of safety and evidence, and required reporting handoff. Regulatory credit is verified-only and requires completion or acceptance of the current official training plus verification of current reporting contacts and certificate evidence. Course completion is learning evidence, not automatic regulatory approval; the employing fa","category":"PCH and ALF Annual Required Topics","duration_minutes":30,"video_count":0,"current_version_id":"6acb3e63-9d21-4e36-b367-2fde91c7c43d","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/2614e855-77b7-4747-b0d0-2aa4cbf7f5cb"},{"id":"88637a6a-1bc3-4ce1-9556-96de919fc9cc","content_key":"penntrain.course.pa-hha-aide-rights-communication-culture","title":"Patient Rights, Communication, and Cultural Responsiveness for Home Health Aides","summary":"Applies patient rights, privacy, communication access, cultural humility, choice, and professional boundaries to care delivered in a person's home. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"9b9d2fb8-f53e-4f61-80c3-ffa4dc102b56","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/88637a6a-1bc3-4ce1-9556-96de919fc9cc"},{"id":"b8430040-02c6-4c76-912e-3c9806d23337","content_key":"penntrain.course.pa-pch-2600-236-dementia-foundations","title":"PCH Secured Dementia Care Unit: Annual Six-Hour Curriculum","summary":"A structured six-hour annual dementia-care curriculum for direct care staff working in a PCH secured dementia care unit under 55 Pa. Code Section 2600.236, additional to the 12-hour general annual requirement. Credit is verified-only and requires qualified review; all six hours are structured instruction and application, not on-the-job training. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and","category":"PCH Secured Dementia Care Unit Annual Training","duration_minutes":360,"video_count":0,"current_version_id":"f388563c-2a05-4017-b8bc-a0ed046e2f1e","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-07-23 08:46:37.722544+00","launch_path":"/app/courses/b8430040-02c6-4c76-912e-3c9806d23337"},{"id":"30107877-1f66-4d90-98cb-1e35927c1bd7","content_key":"penntrain.course.pa-pch-annual-assessed-needs","title":"PCH: Meeting Assessed Resident Needs","summary":"A complete PCH annual course on translating the preadmission screening, assessment, medical evaluation, and support plan into resident-specific daily services. Credit is verified-only because the employing home must validate work with its current records, policies, staff roles, and escalation process. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulato","category":"PCH Annual Required Topics","duration_minutes":75,"video_count":0,"current_version_id":"0b65a4f1-fd5d-4293-8147-8981b25b62ea","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-07-23 08:46:37.722544+00","launch_path":"/app/courses/30107877-1f66-4d90-98cb-1e35927c1bd7"},{"id":"86819c44-93d5-4eab-ba10-00caf0cc9b47","content_key":"penntrain.course.pa-pch-annual-personal-care-services","title":"PCH: Personal Care Services and Safe Assistance","summary":"A complete PCH annual course on delivering personal care services from the support plan while preserving resident choice, dignity, privacy, independence, and safety. Verified-only credit requires the home to validate its equipment, procedures, records, and role-specific skills. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"PCH Annual Required Topics","duration_minutes":75,"video_count":0,"current_version_id":"c0abd9dc-24a0-4c0b-a4b5-2c83536cec3f","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-07-23 08:46:37.722544+00","launch_path":"/app/courses/86819c44-93d5-4eab-ba10-00caf0cc9b47"},{"id":"9dc21074-96e9-4ea9-810e-83ec19b78641","content_key":"penntrain.course.pa-nh-aide-performance-facility-remediation","title":"Performance Review and Facility-Needs Remediation for Nursing Home Aides","summary":"Provides a structured annual module for correcting nurse-aide performance gaps and addressing resident-population and facility-assessment priorities through employer-selected practice. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"0a88ac2e-300e-447f-8aa8-160962cdd7b0","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/9dc21074-96e9-4ea9-810e-83ec19b78641"},{"id":"d75f8389-704b-4dae-afe8-d59223df504f","content_key":"penntrain.course.pa-gh-6400-pcp-foundations","title":"Person-Centered Practice and Everyday Choice","summary":"A comprehensive Chapter 6400 annual-training course on person-centered practice, dignity, supported choice, and translating what matters to a person into daily support. After the home verifies audience, applicability, and evidence, the course may contribute two designed hours; it is not professional continuing education approval.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"e13c871b-f934-4c83-973f-f77a71c79131","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/d75f8389-704b-4dae-afe8-d59223df504f"},{"id":"94b9c6b2-feaa-42c8-9b5f-c451cf08b990","content_key":"penntrain.course.pa-nh-aide-personal-care-skin-nutrition","title":"Personal Care, Skin Observation, Nutrition, and Hydration for Nursing Home Aides","summary":"Integrates dignified personal care with skin observation, oral health, nutrition, hydration, elimination, and prompt reporting of meaningful change. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"19288c54-745e-48ca-bca6-01de466c0f44","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/94b9c6b2-feaa-42c8-9b5f-c451cf08b990"},{"id":"39614782-39e2-473b-a0f3-927cef65e90f","content_key":"penntrain.course.pa-hha-aide-hygiene-oral-continence-skin","title":"Personal Hygiene, Oral Care, Continence, and Skin Observation for Home Health Aides","summary":"Builds complete, dignified plan-directed personal care with focused skin and oral observation, continence support, infection prevention, and change reporting. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":90,"video_count":0,"current_version_id":"dcf4d876-220d-4edc-9833-87d84439aa43","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/39614782-39e2-473b-a0f3-927cef65e90f"},{"id":"a3791c69-d7bb-4269-9d4b-8bc418fdc7f3","content_key":"penntrain.course.pa-gh-6400-person-behavior-support","title":"Preparation for Facilitated Behavior Support Verification","summary":"Preparation for a facilitated, person-specific annual verification of the current behavior-support component, communication, prevention, approved techniques, crisis response, and documentation. A learner completion certificate records preparation only; the home must separately verify live training by a person knowledgeable about the current plan.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"8d9dbcc1-2bf1-4b12-8a23-ab6e9ebf4dca","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/a3791c69-d7bb-4269-9d4b-8bc418fdc7f3"},{"id":"5ac19d64-cc96-4cd6-9969-fe2b6569809e","content_key":"penntrain.course.pa-gh-6400-person-ip-implementation","title":"Preparation for Facilitated Individual Plan Verification","summary":"Preparation for facilitated person-specific annual verification using the current assessment and Individual Plan, health and safety procedures, communication, goals, choice, documentation, and handoff. A learner completion certificate records preparation only; verified credit requires the live current-plan lab.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"0e8a7c18-f19c-4d27-bafa-fabc93943a38","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/5ac19d64-cc96-4cd6-9969-fe2b6569809e"},{"id":"c889f869-d5c3-48fc-8afa-301ecc04e078","content_key":"penntrain.course.pa-gh-6400-first-aid-cpr-verified","title":"Preparation for First Aid, Heimlich, and CPR Skills Verification","summary":"Preparation for trainer-led first aid, choking-response, and CPR skills under Section 6400.46(d). A learner completion certificate records preparation only; verified credit requires an eligible certified trainer and in-person skills, and PennTrain does not issue clinical certification.","category":"Pennsylvania Chapter 6400","duration_minutes":180,"video_count":0,"current_version_id":"6b9c2794-9400-455e-b9f9-24aebc50a592","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/c889f869-d5c3-48fc-8afa-301ecc04e078"},{"id":"532cafd4-ddd7-4d23-b9b2-b2e49ed2eb61","content_key":"penntrain.course.pa-gh-6400-fire-safety-verified","title":"Preparation for Onsite Fire Safety Verification","summary":"Preparation for qualified fire-safety training and home-specific evacuation practice under Section 6400.46. A learner completion certificate records preparation only; the LMS cannot certify the expert, facilitator, current materials, or site-specific practice.","category":"Pennsylvania Chapter 6400","duration_minutes":60,"video_count":0,"current_version_id":"b09c2ecd-43c2-4faf-b768-b5c2e306d9f2","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/532cafd4-ddd7-4d23-b9b2-b2e49ed2eb61"},{"id":"5914f559-e3a5-44a0-b0c9-bce101f1a83b","content_key":"penntrain.course.pa-gh-6400-abuse-prevent-detect","title":"Preventing and Detecting Abuse, Neglect, and Exploitation","summary":"A comprehensive Chapter 6400 annual-training course on prevention, recognition, immediate protection, trauma-informed response, and professional boundaries. It does not represent Act 31, professional-license CE, or another separately approved credential.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"17169be2-b2e3-46b4-b385-c2b078198310","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/5914f559-e3a5-44a0-b0c9-bce101f1a83b"},{"id":"ac119eaa-ec8d-4f6b-a809-90b4c0773f5c","content_key":"penntrain.course.pa-nh-aide-qapi-ethics-documentation","title":"QAPI, Ethics, and Documentation for Nursing Home Aides","summary":"Connects accurate records, ethical conduct, incident reporting, privacy, teamwork, and frontline observations to nursing-home quality assurance and performance improvement. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":45,"video_count":0,"current_version_id":"00716674-5fd5-4bf6-8abe-b20bf48821f2","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/ac119eaa-ec8d-4f6b-a809-90b4c0773f5c"},{"id":"022c42fe-feae-4f67-b1b4-7e4a5ef7891a","content_key":"penntrain.course.pa-hha-aide-rom-positioning-skin-integrity","title":"Range of Motion, Positioning, and Skin Integrity for Home Health Aides","summary":"Builds plan-directed positioning, range-of-motion, pressure prevention, device awareness, and functional-change reporting skills in the home. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"4b114544-0163-4545-8ce4-39ae2eee6a14","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/022c42fe-feae-4f67-b1b4-7e4a5ef7891a"},{"id":"89472c68-7f52-4dc9-8304-647cde87141a","content_key":"penntrain.course.pa-gh-6400-incident-response","title":"Recognizing Incidents and Immediate Protective Action","summary":"Comprehensive annual training on incident recognition, emergency triage, immediate protection, notifications, evidence preservation, and continued support.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"eaa01458-9dd5-406f-9bea-8db5949e64a7","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/89472c68-7f52-4dc9-8304-647cde87141a"},{"id":"2b3eed47-3577-4b5b-86ed-702b89ae11d1","content_key":"penntrain.course.pa-gh-6400-documentation-funds","title":"Records, Confidentiality, and Safeguarding Individual Funds","summary":"Job-skills annual training on accurate records, minimum-necessary confidentiality, individual funds, property, receipts, and audit-ready corrections.","category":"Pennsylvania Chapter 6400","duration_minutes":60,"video_count":0,"current_version_id":"c153007e-fb78-4e0d-aee8-2bac32215759","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/2b3eed47-3577-4b5b-86ed-702b89ae11d1"},{"id":"32695769-06f0-45a3-ae93-84c8ce452753","content_key":"penntrain.course.pa-gh-6400-protective-reporting","title":"Reporting Under APSA, OAPSA, and CPSL","summary":"A comprehensive Chapter 6400 course on selecting the correct Pennsylvania protective-services pathway, making prompt reports, preserving facts, and coordinating immediate protection. It does not confer Act 31 or other approved continuing-education credit.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"11df6bb1-259c-4fe7-9f14-272e6b38a0cf","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/32695769-06f0-45a3-ae93-84c8ce452753"},{"id":"2b13c14f-5876-43df-9329-612f695ba952","content_key":"penntrain.course.pa-dhs-standalone-resident-rights","title":"Resident Rights and Dignity: Annual Training for PCH and ALF Staff","summary":"The required annual deep-dive on resident rights at Pennsylvania personal care homes (PCH) and assisted living facilities (ALF): autonomy and dignity in daily care, financial and communication rights, the grievance process, and balancing rights with safety. Grounded in 55 Pa. Code Sections 2600.65(g)(3) and 2800.65(j)(3).","category":"Resident Rights","duration_minutes":60,"video_count":0,"current_version_id":"7b0b429a-3225-4a03-8b3c-561f0aad9345","version_number":1,"published_at":"2026-07-24 05:16:09.770474+00","updated_at":"2026-07-24 05:16:09.770474+00","launch_path":"/app/courses/2b13c14f-5876-43df-9329-612f695ba952"},{"id":"c665f671-0bd1-4782-9fe8-6a658aa77e62","content_key":"penntrain.course.pa-nh-aide-communication-rights-culture","title":"Resident Rights, Communication, and Cultural Responsiveness for Nursing Home Aides","summary":"Strengthens daily practices that preserve resident rights, privacy, autonomy, communication access, nondiscrimination, cultural identity, and informed choice. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":75,"video_count":0,"current_version_id":"9440e001-ce78-4592-8366-e606bd40e232","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/c665f671-0bd1-4782-9fe8-6a658aa77e62"},{"id":"1fde8db2-8f17-4654-a902-cedd8342eb30","content_key":"penntrain.course.pa-dhs-annual-resident-rights","title":"Resident Rights, Dignity, and Choice","summary":"A complete annual course on resident rights, dignity, privacy, choice, consent, freedom from abuse and retaliation, complaint access, confidentiality, least-restrictive support, and staff accountability in PCH and ALF settings. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"PCH and ALF Annual Required Topics","duration_minutes":45,"video_count":0,"current_version_id":"16d8fb9b-db3a-4684-93ab-ab06df438e2a","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/1fde8db2-8f17-4654-a902-cedd8342eb30"},{"id":"534299af-268e-464e-a64d-db1686e023c8","content_key":"penntrain.course.pa-nh-aide-restorative-nursing","title":"Restorative Nursing and Maintenance of Function for Nursing Home Aides","summary":"Teaches plan-directed support for mobility, range of motion, self-care, continence, communication, and resident participation while preventing over-assistance and avoidable decline. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"9dd38442-0500-4570-a85b-d9bf03bd5a9f","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/534299af-268e-464e-a64d-db1686e023c8"},{"id":"55af6caa-1e57-40bb-8519-c9d0501c4f6d","content_key":"penntrain.course.pa-gh-6400-rights-daily-practice","title":"Rights in Daily Practice: Privacy, Risk, Funds, and Grievances","summary":"Applied Chapter 6400 annual training on shift decisions, funds safeguards, positive risk, grievance response, and objective rights documentation.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"558acafc-bcb8-4364-9073-ef405c74f376","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/55af6caa-1e57-40bb-8519-c9d0501c4f6d"},{"id":"42290ce6-091c-5a93-b567-87bebd5b7cd5","content_key":"penntrain.course.pa-dhs-standalone-safe-management","title":"Safe Management and De-escalation: Annual Training for PCH and ALF Staff","summary":"The required annual refresher on understanding behavior as communication, preventing escalation, de-escalating safely, and the hard limits on restraint and coercion, for staff at Pennsylvania personal care homes (PCH) and assisted living facilities (ALF). Grounded in 55 Pa. Code Sections 2600.65(f)(6) and 2800.65(i)(6).","category":"Safe Management and De-escalation","duration_minutes":60,"video_count":10,"current_version_id":"ca74fcad-fa3c-598d-8f0f-188396cadbb0","version_number":2,"published_at":"2026-07-25 17:06:26.798527+00","updated_at":"2026-07-25 17:06:26.798527+00","launch_path":"/app/courses/42290ce6-091c-5a93-b567-87bebd5b7cd5"},{"id":"c2266695-ac1a-4239-82cd-fb0feed65000","content_key":"penntrain.course.pa-dhs-annual-safe-management","title":"Safe Management of Challenging Situations","summary":"A complete annual course on prevention, trauma-aware de-escalation, unmet-needs analysis, immediate safety, least-restrictive response, documentation, and team review. It carries 1.25 PCH hours and 1.50 ALF hours. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"PCH and ALF Annual Required Topics","duration_minutes":90,"video_count":0,"current_version_id":"c8a97ce6-6422-451c-a780-72b2ea72ec9f","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/c2266695-ac1a-4239-82cd-fb0feed65000"},{"id":"b4413c60-334e-401d-bdd1-782ccc840eb7","content_key":"penntrain.course.pa-hos-aide-skin-positioning-pressure-comfort","title":"Skin Integrity, Positioning, and Pressure Comfort for Hospice Aides","summary":"Integrates comfort-focused positioning, pressure reduction, skin and device observation, gentle movement, and timely communication when goals or tolerance change. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"b5cd9bdf-1221-4f4c-9dbf-2c5faab1f0eb","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/b4413c60-334e-401d-bdd1-782ccc840eb7"},{"id":"7206293b-af58-42d5-87b2-1c39effd9a0e","content_key":"penntrain.course.pa-hha-aide-transfers-ambulation-falls","title":"Transfers, Ambulation, and Fall Response for Home Health Aides","summary":"Develops safe plan-directed mobility support, use of transfer devices, body mechanics, home-hazard control, and post-fall response. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":90,"video_count":0,"current_version_id":"e5527879-493e-48fb-8010-2db090964c04","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/7206293b-af58-42d5-87b2-1c39effd9a0e"},{"id":"60a3cc4a-0ff5-49c9-a2f4-57e1a273f339","content_key":"penntrain.course.pa-hos-aide-transfers-ambulation-falls","title":"Transfers, Ambulation, and Fall Response for Hospice Aides","summary":"Develops safe mobility assistance that respects changing strength, comfort goals, equipment needs, caregiver capacity, and patient choice near end of life. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"bfcfd8a0-2052-4b9f-91f3-cb2a16ab09c7","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/60a3cc4a-0ff5-49c9-a2f4-57e1a273f339"}]$catalog$::jsonb) as row_data (
    id uuid,
    content_key text,
    title text,
    summary text,
    category text,
    duration_minutes integer,
    video_count integer,
    current_version_id uuid,
    version_number integer,
    published_at timestamptz,
    updated_at timestamptz,
    launch_path text
  )
),
upserted_items as (
  insert into hub.content_items (
    id, content_key, kind, status, access_level, owner_product_id,
    owner_team, source_system, created_at, updated_at
  )
  select
    md5('penntrain-course-item:' || id::text)::uuid,
    content_key,
    'course',
    'published',
    'public',
    (select id from hub.products where slug = 'carebase'),
    'CareMetric Learning',
    'penntrain',
    coalesce(published_at, now()),
    coalesce(updated_at, now())
  from source_rows
  on conflict (id) do update set
    content_key = excluded.content_key,
    status = excluded.status,
    access_level = excluded.access_level,
    owner_product_id = excluded.owner_product_id,
    owner_team = excluded.owner_team,
    source_system = excluded.source_system,
    updated_at = excluded.updated_at
  returning id
),
upserted_revisions as (
  insert into hub.content_revisions (
    id, item_id, revision_no, locale, title, summary, body_markdown, body_text,
    variables, source_hash, source_version, review_state, approved_at, created_at
  )
  select
    md5('penntrain-course-revision:' || row_data.id::text || ':' || row_data.current_version_id::text)::uuid,
    md5('penntrain-course-item:' || row_data.id::text)::uuid,
    greatest(row_data.version_number, 1),
    'en-US',
    row_data.title,
    row_data.summary,
    format(
      'This governed course is maintained in CareMetric CareBase.%s%s',
      case when row_data.duration_minutes is not null
        then E'\n\n**Estimated duration:** ' || row_data.duration_minutes || ' minutes' else '' end,
      case when row_data.video_count > 0
        then E'\n\n**Included videos:** ' || row_data.video_count else '' end
    ),
    row_data.summary,
    jsonb_build_object(
      'category', row_data.category,
      'duration_minutes', row_data.duration_minutes,
      'video_count', row_data.video_count,
      'penntrain_course_id', row_data.id
    ),
    md5(row_data.id::text || ':' || row_data.current_version_id::text || ':' || row_data.title || ':' || row_data.summary),
    'PennTrain:' || row_data.current_version_id::text || ':v' || row_data.version_number,
    'approved',
    coalesce(row_data.published_at, now()),
    coalesce(row_data.published_at, now())
  from source_rows row_data
  on conflict (id) do nothing
  returning id
)
insert into hub.content_publications (
  item_id, revision_id, product_id, audience, route_pattern, published_at
)
select
  md5('penntrain-course-item:' || source_rows.id::text)::uuid,
  md5('penntrain-course-revision:' || source_rows.id::text || ':' || source_rows.current_version_id::text)::uuid,
  product.id,
  array['all']::text[],
  null,
  coalesce(source_rows.published_at, now())
from source_rows
cross join hub.products product
where product.status <> 'retired'
  and product.support_enabled
on conflict (item_id, product_id) do update set
  revision_id = excluded.revision_id,
  audience = excluded.audience,
  route_pattern = excluded.route_pattern,
  published_at = excluded.published_at,
  expires_at = null
where excluded.published_at >= hub.content_publications.published_at;

with source_rows as (
  select *
  from jsonb_to_recordset($catalog$[{"id":"e4e3090e-19cb-4d83-99e3-ec8aea17304a","content_key":"penntrain.course.pa-dhs-standalone-abuse-reporting","title":"Abuse, Neglect, and Exploitation Reporting: Annual Mandatory Reporter Training","summary":"The required annual deep-dive on Pennsylvania's Older Adult Protective Services Act (OAPSA) mandatory reporting duties for staff at personal care homes (PCH) and assisted living facilities (ALF): legal definitions, the reporting process, reporter protections, and recognizing financial exploitation. Grounded in 55 Pa. Code Sections 2600.65(g)(4) and 2800.65(j)(4).","category":"Abuse, Neglect, and Exploitation","duration_minutes":60,"video_count":0,"current_version_id":"29c80fca-dfb6-440e-af91-632fab380423","version_number":1,"published_at":"2026-07-24 05:16:09.770474+00","updated_at":"2026-07-24 05:16:09.770474+00","launch_path":"/app/courses/e4e3090e-19cb-4d83-99e3-ec8aea17304a"},{"id":"7de58ed3-64ec-4f21-b198-5287df705791","content_key":"penntrain.course.pa-nh-aide-abuse-prevention-reporting","title":"Abuse, Neglect, Exploitation, and Reporting for Nursing Home Aides","summary":"Develops recognition, immediate protection, reporting, evidence-preservation, and nonretaliation practices for suspected abuse, neglect, exploitation, mistreatment, and misappropriation. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":90,"video_count":0,"current_version_id":"8ea84f6a-7d4a-4a82-af41-c0b20d0cc5e9","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/7de58ed3-64ec-4f21-b198-5287df705791"},{"id":"4dae1327-5ffd-4dbf-ac36-8f44204d2a91","content_key":"penntrain.course.pa-nh-aide-accident-fall-transfer-safety","title":"Accident Prevention, Falls, and Transfer Safety for Nursing Home Aides","summary":"Builds resident-specific hazard recognition, safe transfer and mobility habits, fall response, equipment checks, and timely reporting without creating avoidable restraint. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":75,"video_count":0,"current_version_id":"e1dc2e01-1c15-4be1-b6ae-7c02a5ccf9b0","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/4dae1327-5ffd-4dbf-ac36-8f44204d2a91"},{"id":"4f1c1981-84e9-40c8-82c6-7092b88aeae7","content_key":"penntrain.course.pa-hos-aide-active-dying-symptom-escalation","title":"Active Dying, Comfort Observation, and Symptom Escalation for Hospice Aides","summary":"Prepares aides to recognize and report common end-of-life changes, provide assigned comfort measures, support families, and distinguish expected-plan guidance from urgent or unexpected concerns. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":90,"video_count":0,"current_version_id":"d572eb18-bd90-4178-996d-8f575616a07b","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/4f1c1981-84e9-40c8-82c6-7092b88aeae7"},{"id":"9f21a2e0-a945-4f43-8bb5-7f46b80c775f","content_key":"penntrain.course.pa-hha-aide-agency-policies-new-procedures","title":"Agency Policies, New Procedures, and Competency Remediation for Home Health Aides","summary":"Provides an employer-tailored annual module for policy updates, new technology, recurring quality risks, competency gaps, and safe implementation in varied home environments. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"f239c159-38a1-4334-b8f9-8ffec19e7bf2","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/9f21a2e0-a945-4f43-8bb5-7f46b80c775f"},{"id":"2e8769e5-eed6-4aa9-8884-9e208b99a948","content_key":"penntrain.course.pa-alr-2800-69-dementia-part-1","title":"ALF Dementia Annual Training Part 1: Foundations and Communication","summary":"One complete hour of the separate two-hour annual ALF dementia-specific requirement in 55 Pa. Code Section 2800.69. Part 1 covers disease foundations, personhood, communication, distress, acute change, rights, and practical application for all covered staff and volunteers. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"ALF Dementia-Specific Annual Training","duration_minutes":60,"video_count":0,"current_version_id":"171b4c1e-c1f2-41ee-887e-1d2810fb60a9","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/2e8769e5-eed6-4aa9-8884-9e208b99a948"},{"id":"76b5e141-02db-4741-a120-c24bd4b48a7f","content_key":"penntrain.course.pa-alr-2800-69-dementia-part-2","title":"ALF Dementia Annual Training Part 2: Applied Support, Safety, and Rights","summary":"The second complete hour of the separate two-hour annual ALF dementia-specific requirement in 55 Pa. Code Section 2800.69. Part 2 applies individualized support to daily living, environment, mobility, nutrition, meaningful activity, safety, team review, and resident rights. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"ALF Dementia-Specific Annual Training","duration_minutes":60,"video_count":0,"current_version_id":"b765a920-1cf1-421a-8bd5-586a401e2fad","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/76b5e141-02db-4741-a120-c24bd4b48a7f"},{"id":"cadfbe15-9bb9-4d8a-b58d-0fc4c7dfc802","content_key":"penntrain.course.pa-alr-2800-236-dementia-scu-starter","title":"ALF Dementia Special Care Unit: Annual Eight-Hour Curriculum","summary":"A structured eight-hour annual curriculum for direct care staff working in an ALF special care unit for residents with Alzheimer's disease or related disorders under 55 Pa. Code Section 2800.236. It is additional to other Chapter 2800 training. Credit is verified-only; all hours are structured instruction and application, not on-the-job training. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability an","category":"ALF Dementia Special Care Unit Annual Training","duration_minutes":480,"video_count":0,"current_version_id":"79068173-b123-4df2-93df-dbfb6986c5fe","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/cadfbe15-9bb9-4d8a-b58d-0fc4c7dfc802"},{"id":"6b64d798-91c3-4220-a7fc-694ae5bc7ff3","content_key":"penntrain.course.pa-alr-2800-236-inrbi-starter","title":"ALF INRBI Special Care Unit: Annual Eight-Hour Curriculum","summary":"A structured eight-hour annual curriculum for direct care staff working in an ALF special care unit for individuals with neurocognitive impairments from a brain injury under 55 Pa. Code Section 2800.236. It covers required dementia-unit topics plus brain-injury-specific coaching, cueing, problem solving, self-soothing, and fading of supports. Credit is verified-only and is not on-the-job training. Course completion is learning evidence, not automatic regulatory approval; the employing facility m","category":"ALF INRBI Special Care Unit Annual Training","duration_minutes":480,"video_count":0,"current_version_id":"0a0f174d-720a-4fbb-b6d6-177e616fe1fb","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/6b64d798-91c3-4220-a7fc-694ae5bc7ff3"},{"id":"f236bd74-37d3-48b2-b1a6-7d1d341ab8be","content_key":"penntrain.course.pa-alr-annual-assisted-living-services","title":"ALF: Assisted Living Services and Aging in Place","summary":"A complete ALF annual course on resident-directed assisted living services, service coordination, independence, aging in place, risk review, and transitions. Verified-only credit requires residence-specific application and skills validation. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"ALF Annual Required Topics","duration_minutes":150,"video_count":0,"current_version_id":"890e7890-7620-459e-a18d-1a4ea805b895","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/f236bd74-37d3-48b2-b1a6-7d1d341ab8be"},{"id":"112cc1ae-6c5e-4ed4-b15f-1af5b052aff6","content_key":"penntrain.course.pa-alr-annual-assessed-needs","title":"ALF: Meeting Assessed Resident Needs","summary":"A complete ALF annual course on using the assessment tool, medical evaluation, support plan, service coordination, and aging-in-place decision process. Credit is verified-only because the residence must validate use of its records, policies, service partners, and escalation workflow. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"ALF Annual Required Topics","duration_minutes":120,"video_count":0,"current_version_id":"78054c93-f6b4-4e95-82a4-1a8bafa1e7a8","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/112cc1ae-6c5e-4ed4-b15f-1af5b052aff6"},{"id":"e92bbc28-81f7-5de2-884c-c526465647d7","content_key":"penntrain.course.pa-pch-diabetes-annual","title":"Annual Diabetes Patient Education for Pennsylvania Personal Care Homes","summary":"Annual Diabetes Patient Education designed to address the training requirements of 55 Pa. Code Section 2600.190(b), for Pennsylvania personal care home (PCH) staff who administer insulin or provide diabetes-related care. Twelve modules cover diabetes and the role of PCH staff, blood glucose monitoring, hypoglycemia, hyperglycemia and diabetic emergencies, insulin types, insulin storage and handling, reading the order and the MAR, drawing up insulin, insulin pens, subcutaneous administration, med","category":"Diabetes and Insulin Safety","duration_minutes":240,"video_count":12,"current_version_id":"e4bac606-1e4d-502d-ad34-017266b664cb","version_number":2,"published_at":"2026-08-30 15:23:41.873644+00","updated_at":"2026-08-30 15:23:41.873644+00","launch_path":"/app/courses/e92bbc28-81f7-5de2-884c-c526465647d7"},{"id":"76a23b41-e3bd-4e5c-af3c-d44c01e003fc","content_key":"penntrain.course.pa-nh-aide-behavioral-health-person-centered","title":"Behavioral Health and Person-Centered Support for Nursing Home Aides","summary":"Builds respectful observation and response skills for behavioral health needs, trauma histories, substance-use concerns, distress, and crisis warning signs. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":45,"video_count":0,"current_version_id":"5404149f-d8ff-4353-ba95-99c69ca46645","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/76a23b41-e3bd-4e5c-af3c-d44c01e003fc"},{"id":"03b17550-20d4-4a4c-8804-baa191f39f20","content_key":"penntrain.course.pa-gh-6400-rights-foundations","title":"Chapter 6400 Individual Rights","summary":"Comprehensive annual training on dignity, privacy, choice, access, property, communication, food, healthcare decisions, and freedom from abuse and unnecessary restriction.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"3734654a-40a9-4ba9-9416-c1273dece254","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/03b17550-20d4-4a4c-8804-baa191f39f20"},{"id":"67d330e9-00fa-41e4-860d-691404fe8921","content_key":"penntrain.course.pa-hos-aide-comfort-hygiene-oral-continence","title":"Comfort-Focused Hygiene, Oral Care, and Continence Support for Hospice Aides","summary":"Builds gentle, goal-concordant personal care that balances cleanliness, comfort, energy, privacy, skin protection, oral moisture, continence, and patient choice. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":90,"video_count":0,"current_version_id":"53fa757a-bea5-425b-a714-18ad1e99f6ff","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/67d330e9-00fa-41e4-860d-691404fe8921"},{"id":"5538f680-ac53-4a29-92ed-b78c2e753c25","content_key":"penntrain.course.pa-hos-aide-communication-privacy-grief","title":"Communication, Privacy, and Grief Support for Hospice Aides","summary":"Builds presence, listening, accessible communication, privacy, cultural humility, anticipatory-grief awareness, and appropriate referral without counseling beyond role. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"585f03a2-a686-4ba0-b5f7-ae33908921de","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/5538f680-ac53-4a29-92ed-b78c2e753c25"},{"id":"e55424d9-71b7-4afe-9724-150d897dd80a","content_key":"penntrain.course.pa-gh-6400-community-relationships","title":"Community Integration and Supporting Relationships","summary":"A comprehensive Chapter 6400 course on belonging, ordinary community participation, relationship support, transportation planning, and removing program-created barriers. After the home verifies audience, applicability, and evidence, the course may contribute two designed annual-training hours.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"eaf11bf8-3870-414f-b764-99795db3a742","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/e55424d9-71b7-4afe-9724-150d897dd80a"},{"id":"e8f4b578-7817-4397-a3ee-9133dd406191","content_key":"penntrain.course.pa-nh-aide-dementia-cognitive-care","title":"Dementia and Cognitive-Impairment Care for Nursing Home Aides","summary":"Builds practical skills for recognizing cognitive change, communicating respectfully, preventing avoidable distress, and supporting person-centered routines for residents with dementia or other cognitive impairment. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":90,"video_count":0,"current_version_id":"7e2b6e23-49f3-4510-8229-c1e0b1e7124a","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/e8f4b578-7817-4397-a3ee-9133dd406191"},{"id":"7cc868fe-0686-4826-9dc6-5d42336b9a47","content_key":"penntrain.course.pa-dhs-annual-dementia-cognitive-neuro","title":"Dementia, Cognitive, and Neurological Support","summary":"A complete person-centered annual course for the PCH dementia and cognitive-impairment topic and the broader ALF dementia, cognitive, and neurological-impairment topic. The 90-minute curriculum supports a 1.00-hour PCH allocation and a 1.50-hour ALF allocation. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"PCH and ALF Annual Required Topics","duration_minutes":90,"video_count":0,"current_version_id":"7d674ce2-153b-4273-bc9c-860fcae6b2af","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/7cc868fe-0686-4826-9dc6-5d42336b9a47"},{"id":"0928952d-f315-4dc5-a0ff-11e3c05561dc","content_key":"penntrain.course.pa-hha-aide-documentation-care-coordination","title":"Documentation and Care Coordination for Home Health Aides","summary":"Builds timely, objective home-visit records and reliable communication with the supervising nurse and interdisciplinary team. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"9fd3824b-24f1-42b7-b093-46263af6d77e","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/0928952d-f315-4dc5-a0ff-11e3c05561dc"},{"id":"c88ff230-e280-4e8f-b844-17bc82d9d024","content_key":"penntrain.course.pa-nh-aide-emergency-fire-preparedness","title":"Emergency and Fire Preparedness for Nursing Home Aides","summary":"Prepares aides to carry out assigned emergency roles for fire, evacuation, sheltering, severe weather, utility failure, missing residents, and acute medical events. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"d263c351-9707-47a7-bc71-7260392f2d27","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/c88ff230-e280-4e8f-b844-17bc82d9d024"},{"id":"ff5cfdb7-3765-445b-8b29-46fc840f2ddb","content_key":"penntrain.course.pa-hos-aide-emergency-vs-expected-decline","title":"Emergency Events Versus Expected Decline for Hospice Aides","summary":"Provides a concise decision framework for following patient-specific hospice instructions when a change may reflect expected decline, urgent symptom need, injury, or emergency. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":30,"video_count":0,"current_version_id":"4ea4432e-ee34-4c0b-bb2d-54d3666e7388","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/ff5cfdb7-3765-445b-8b29-46fc840f2ddb"},{"id":"b1ad4cb0-e9eb-489f-9a38-b65bd752dfdb","content_key":"penntrain.course.pa-dhs-annual-emergency-prep","title":"Emergency Preparedness and Resident Protection","summary":"A complete annual emergency-preparedness course on all-hazards planning, resident needs, communication, shelter or evacuation, continuity, accountability, documentation, and recovery. Credit is verified-only because facility plans, contacts, resources, roles, and drills must be validated. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"PCH and ALF Annual Required Topics","duration_minutes":90,"video_count":0,"current_version_id":"77cad196-64a8-44c3-a950-2c5d04877f30","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/b1ad4cb0-e9eb-489f-9a38-b65bd752dfdb"},{"id":"29c5d1d2-dc44-56d4-8511-a274750db906","content_key":"penntrain.course.pa-dhs-standalone-emergency-prep","title":"Emergency Preparedness Beyond Fire: Annual Training for PCH and ALF Staff","summary":"The required annual refresher on the emergencies that do not sound an alarm, including power and utility loss, severe weather, a missing resident, medical emergencies, and security events, for staff at Pennsylvania personal care homes (PCH) and assisted living facilities (ALF). Grounded in 55 Pa. Code Sections 2600.65(g)(2) and 2800.65(j)(2).","category":"Emergency Preparedness","duration_minutes":60,"video_count":10,"current_version_id":"0515864b-7d3b-5990-b991-48a472ecd057","version_number":2,"published_at":"2026-07-25 17:44:49.084641+00","updated_at":"2026-07-25 17:44:49.084641+00","launch_path":"/app/courses/29c5d1d2-dc44-56d4-8511-a274750db906"},{"id":"ecb3a79a-b428-5d92-99ec-73f190ad60c1","content_key":"penntrain.course.pa-dhs-standalone-falls-prevention","title":"Falls and Accident Prevention: Annual Training for PCH and ALF Staff","summary":"The required annual refresher on why residents fall, the environmental and medication risks staff can remove, safe assistance and transfers within your trained scope, and what to do in the minutes after a fall, for staff at Pennsylvania personal care homes (PCH) and assisted living facilities (ALF). Grounded in 55 Pa. Code Sections 2600.65(g)(5) and 2800.65(j)(5).","category":"Falls and Accident Prevention","duration_minutes":60,"video_count":10,"current_version_id":"edc5dd31-ec5c-5879-a532-8fda7d8dedd4","version_number":2,"published_at":"2026-07-25 15:07:53.894761+00","updated_at":"2026-07-25 15:07:53.894761+00","launch_path":"/app/courses/ecb3a79a-b428-5d92-99ec-73f190ad60c1"},{"id":"395123a9-9dc4-424a-aaec-0a74ff766098","content_key":"penntrain.course.pa-dhs-annual-falls-prevention","title":"Falls Prevention and Post-Fall Response","summary":"A complete annual course on multifactorial fall risk, environment, mobility, transfers, footwear, toileting, medication and health observations, resident choice, immediate post-fall response, documentation, and team prevention. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"PCH and ALF Annual Required Topics","duration_minutes":120,"video_count":0,"current_version_id":"d8b3ccb7-3df2-4d5f-aa0f-a59d4722fcd1","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/395123a9-9dc4-424a-aaec-0a74ff766098"},{"id":"52454d2d-41bd-4077-a0ed-90445373af2e","content_key":"penntrain.course.pa-hos-aide-family-support-boundaries","title":"Family Support, Caregiver Teaching Boundaries, and Professional Conduct for Hospice Aides","summary":"Builds supportive caregiver interaction, observation of caregiver strain, approved reinforcement of teaching, conflict referral, privacy, safety, and professional boundaries. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"05b9e06f-7cfe-4648-a552-a19ba636da55","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/52454d2d-41bd-4077-a0ed-90445373af2e"},{"id":"221245ad-fcb2-431f-b929-e745014a51c2","content_key":"penntrain.course.pa-dhs-standalone-fire-safety","title":"Fire Safety and Emergency Preparedness: Annual Refresher for PCH and ALF Staff","summary":"The required annual refresher on fire prevention, initial emergency response, and evacuating residents who need help, for staff at Pennsylvania personal care homes (PCH) and assisted living facilities (ALF). Grounded in 55 Pa. Code Sections 2600.65(g)(1) and 2800.65(j)(1).","category":"Fire Safety and Emergency Preparedness","duration_minutes":60,"video_count":0,"current_version_id":"e9a093ff-3487-446a-bd88-df1c23f590c5","version_number":1,"published_at":"2026-07-24 05:16:09.770474+00","updated_at":"2026-07-24 05:16:09.770474+00","launch_path":"/app/courses/221245ad-fcb2-431f-b929-e745014a51c2"},{"id":"6e1c1e1e-ef1f-41cb-8df8-a435e9b9b6bb","content_key":"penntrain.course.pa-dhs-annual-fire-safety-prep","title":"Fire Safety Preparedness and Facility Procedures","summary":"A complete annual fire-safety course covering prevention, alarm and notification, resident protection, evacuation or relocation concepts, smoke and door control, accountability, and post-event duties. Credit is verified-only because facility-specific drills, routes, systems, assignments, and resident needs must be validated onsite. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the ev","category":"PCH and ALF Annual Required Topics","duration_minutes":45,"video_count":0,"current_version_id":"dea1b237-c0d8-4835-a238-899049a32b47","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/6e1c1e1e-ef1f-41cb-8df8-a435e9b9b6bb"},{"id":"b5486343-a186-43da-99c9-02eefe655029","content_key":"penntrain.course.pa-gh-6400-emergency-readiness","title":"General Emergency Readiness and Continuity","summary":"Job-skills annual training on hazard recognition, emergency roles, evacuation support, accountability, continuity, and after-action learning. It does not replace verified annual fire-safety or first-aid/CPR training.","category":"Pennsylvania Chapter 6400","duration_minutes":60,"video_count":0,"current_version_id":"5ff9d298-8f8c-4166-a884-5f8d3802efb2","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/b5486343-a186-43da-99c9-02eefe655029"},{"id":"a4843eda-0c5a-42f5-a895-14c87be34d64","content_key":"penntrain.course.pa-gh-6400-health-safety","title":"Health Observation, Infection Prevention, and Individual Emergencies","summary":"Job-skills annual training on recognizing health change, infection prevention, safe support, and individual emergency plans; not clinical licensure or skills certification.","category":"Pennsylvania Chapter 6400","duration_minutes":60,"video_count":0,"current_version_id":"7f4c6dd8-9ae0-4e31-8b65-632e6f9c420a","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/a4843eda-0c5a-42f5-a895-14c87be34d64"},{"id":"14241e55-ddcd-47e7-9eee-f4b938c396fc","content_key":"penntrain.course.pa-hha-aide-home-safety-emergencies","title":"Home Safety and Emergency Response for Home Health Aides","summary":"Prepares aides to recognize environmental risk, follow individualized emergency plans, respond to acute events, and manage unsafe home or visit conditions. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"eb81dbb4-e694-49c5-9359-6c5cd408595f","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/14241e55-ddcd-47e7-9eee-f4b938c396fc"},{"id":"deccf03a-6acf-4152-a326-b69c6e9b0508","content_key":"penntrain.course.pa-hos-aide-hospice-philosophy-idg-plan","title":"Hospice Philosophy, Interdisciplinary Care, and the Aide Plan","summary":"Introduces goal-concordant hospice care, the interdisciplinary group, the aide's plan-directed role, and reliable reporting that supports comfort and continuity. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"16db15ed-f580-41de-ab92-98436b9dec87","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/deccf03a-6acf-4152-a326-b69c6e9b0508"},{"id":"3160d132-fc97-41ca-9e45-0a4f2db9c632","content_key":"penntrain.course.pa-hos-aide-agency-specific-new-skill","title":"Hospice Policy Updates and New-Skill Competency","summary":"Provides an employer-tailored annual module for policy changes, new devices and procedures, performance remediation, quality priorities, and competency evidence. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":30,"video_count":0,"current_version_id":"0cfd95c3-d6a9-4893-a95f-0f636fc0fd72","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/3160d132-fc97-41ca-9e45-0a4f2db9c632"},{"id":"4d22aecb-e892-41b5-ac4f-c2f8d4a119e8","content_key":"penntrain.course.pa-gh-6400-incident-documentation","title":"Incident Documentation, Investigation, and Prevention","summary":"Applied annual training on objective records, certified-investigation boundaries, corrective action, trend analysis, and prevention.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"cb9cbb24-66d5-4999-a94a-4ce74d6c99f0","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/4d22aecb-e892-41b5-ac4f-c2f8d4a119e8"},{"id":"ed263d6a-3d9a-453b-8340-3ead4c86dc4f","content_key":"penntrain.course.pa-dhs-annual-infection-immobility","title":"Infection Control, Universal Precautions, and Immobility","summary":"A complete annual course on infection prevention, standard and transmission-based precautions, exposure response, mobility-related complications, and safe resident support. The 135-minute curriculum carries 1.75 PCH hours and 2.25 ALF hours. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"PCH and ALF Annual Required Topics","duration_minutes":135,"video_count":0,"current_version_id":"713a8be8-63a9-45fb-8b45-51196348dc7d","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/ed263d6a-3d9a-453b-8340-3ead4c86dc4f"},{"id":"971c3cc0-e53e-4d42-bfff-3300454ed242","content_key":"penntrain.course.pa-nh-aide-infection-prevention","title":"Infection Prevention and Control for Nursing Home Aides","summary":"Applies standard precautions, transmission-based directions, hand hygiene, personal protective equipment, cleaning boundaries, and early reporting to routine nursing-home care. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"f19e0cb2-93b2-4a3d-8a80-ccad3011d3b1","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/971c3cc0-e53e-4d42-bfff-3300454ed242"},{"id":"52fd1194-e9a4-54b5-9003-44f0f282000f","content_key":"penntrain.course.pa-dhs-standalone-infection-control","title":"Infection Prevention and Control: Annual Training for PCH and ALF Staff","summary":"The required annual refresher on hand hygiene, standard precautions, personal protective equipment, environmental cleaning, and the immobility risks that travel with infection, for staff at Pennsylvania personal care homes (PCH) and assisted living facilities (ALF). Grounded in 55 Pa. Code Sections 2600.65(f)(4) and 2800.65(i)(4).","category":"Infection Control","duration_minutes":60,"video_count":10,"current_version_id":"0afc5905-d644-5ab1-aad4-b3ec5bd0c52d","version_number":2,"published_at":"2026-07-25 15:35:58.03246+00","updated_at":"2026-07-25 15:35:58.03246+00","launch_path":"/app/courses/52fd1194-e9a4-54b5-9003-44f0f282000f"},{"id":"7f3fbb32-b9d9-4d5c-a67c-1adb289cf293","content_key":"penntrain.course.pa-hos-aide-infection-prevention","title":"Infection Prevention for Hospice Aides","summary":"Applies standard precautions, hand hygiene, PPE, clean-bag technique, equipment handling, exposure response, and compassionate precaution practices across hospice settings. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"4c2051cc-79c6-46a1-9d50-41ced0c54e87","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/7f3fbb32-b9d9-4d5c-a67c-1adb289cf293"},{"id":"7ad00f01-f113-484c-998a-70ca914905d9","content_key":"penntrain.course.pa-hha-aide-infection-prevention","title":"Infection Prevention in the Home for Home Health Aides","summary":"Adapts standard precautions, hand hygiene, PPE, clean-bag technique, equipment handling, exposure response, and symptom reporting to varied home environments. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"e4e58ae6-4ac2-4a16-9858-c277b1700c5b","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/7ad00f01-f113-484c-998a-70ca914905d9"},{"id":"eab610ad-9bde-4fb9-91c6-200f25b2d6f1","content_key":"penntrain.course.pa-hha-aide-medication-assistance-scope","title":"Medication Assistance and Scope Boundaries for Home Health Aides","summary":"Clarifies safe assistance with ordinarily self-administered medications, observation and reporting, refusal response, storage concerns, and firm boundaries against unauthorized administration or changes. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":30,"video_count":0,"current_version_id":"27a278dd-2e3d-498a-8cd1-453ead4564a3","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/eab610ad-9bde-4fb9-91c6-200f25b2d6f1"},{"id":"3a89ebb4-d89d-41f2-8cc0-9440e1417f57","content_key":"penntrain.course.pa-gh-6400-med-safety-awareness","title":"Medication Safety Awareness for Chapter 6400 Staff","summary":"Awareness training on medication rights, observation, errors, refusals, adverse reactions, and records. It does not authorize medication administration or replace Department-approved training, renewal, practicum, diabetes education, or epinephrine training.","category":"Pennsylvania Chapter 6400","duration_minutes":60,"video_count":0,"current_version_id":"37c713b3-8acd-4f2c-b649-960f02974df3","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/3a89ebb4-d89d-41f2-8cc0-9440e1417f57"},{"id":"f41795c1-eafe-492f-b4e5-f046b71cbf2a","content_key":"penntrain.course.pa-dhs-annual-med-self-admin","title":"Medication Self-Administration Support for PCH and ALF","summary":"A complete annual course on supporting resident medication self-administration in Pennsylvania personal care homes and assisted living facilities. The course teaches assessment-based assistance, observation, documentation, refusal response, and escalation. It does not authorize medication administration, satisfy medication-administration training or a practicum, or provide administrator continuing-education credit. Course completion is learning evidence, not automatic regulatory approval; the em","category":"PCH and ALF Annual Required Topics","duration_minutes":45,"video_count":0,"current_version_id":"7d8dd796-8c88-4228-a432-bebf33db758a","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/f41795c1-eafe-492f-b4e5-f046b71cbf2a"},{"id":"704324fe-a160-5397-9157-7c6d1e1d1e6f","content_key":"penntrain.course.pa-dhs-standalone-med-self-admin","title":"Medication Self-Administration Support: Annual Training for PCH and ALF Staff","summary":"The required annual refresher on supporting residents who self-administer their medications, the boundary between assistance and administration, safe storage and documentation, and the observations staff must report, for staff at Pennsylvania personal care homes (PCH) and assisted living facilities (ALF). Grounded in 55 Pa. Code Sections 2600.65(f)(1) and 2800.65(i)(1). This course never authorizes medication administration.","category":"Medication Self-Administration Support","duration_minutes":60,"video_count":10,"current_version_id":"3c06e92e-153b-5fee-96db-a5212f23286b","version_number":2,"published_at":"2026-07-25 18:02:11.285676+00","updated_at":"2026-07-25 18:02:11.285676+00","launch_path":"/app/courses/704324fe-a160-5397-9157-7c6d1e1d1e6f"},{"id":"65229cef-7042-4358-a93a-89176e7ff26f","content_key":"penntrain.course.pa-dhs-annual-mental-illness-id","title":"Mental Illness and Intellectual Disability Support","summary":"A conditional annual course for homes or residences serving residents with mental illness or intellectual disability. It addresses person-centered support, communication, crisis warning signs, rights, health differentials, and coordination. Applicability and credit require facility verification. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory cre","category":"Conditional PCH and ALF Annual Topics","duration_minutes":60,"video_count":0,"current_version_id":"42a3cdcc-6d47-4ae6-ba69-97d293d41a7e","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/65229cef-7042-4358-a93a-89176e7ff26f"},{"id":"e2c03f97-74e5-4fb7-b4f1-ced867d37950","content_key":"penntrain.course.pa-orient-new-employee-pch-alf","title":"New Employee Orientation for Personal Care Home and Assisted Living Facility Staff","summary":"Every new hire's first required training at a Pennsylvania personal care home (PCH) or assisted living facility (ALF): general fire safety and emergency orientation, resident rights, mandatory abuse and neglect reporting, emergency medical plans and incident reporting, safe management and role boundaries, two realistic first-shift scenarios, and a facility-specific verification checklist. Taught personally, on video, by Kevin Deyarmin, founder of CareMetric CareBase and a career senior-care admi","category":"New Employee Orientation","duration_minutes":180,"video_count":3,"current_version_id":"23ca08d4-afef-4b88-9db6-2f693d58588f","version_number":1,"published_at":"2026-07-24 04:22:43.927651+00","updated_at":"2026-07-24 04:39:12.9705+00","launch_path":"/app/courses/e2c03f97-74e5-4fb7-b4f1-ced867d37950"},{"id":"e63e8dc4-a236-4fbf-89fb-d39011767aa7","content_key":"penntrain.course.pa-dhs-annual-new-populations","title":"New Population Needs and Service Adaptation","summary":"A conditional annual course for facilities serving a population new to that home or residence. It teaches structured needs analysis, cultural and communication access, risk and resource review, staff preparation, service adaptation, and monitoring. Applicability and local readiness require facility verification. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awardi","category":"Conditional PCH and ALF Annual Topics","duration_minutes":45,"video_count":0,"current_version_id":"3f99b5bf-089a-4d6d-8fa0-e39d40c6cb4c","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/e63e8dc4-a236-4fbf-89fb-d39011767aa7"},{"id":"724a8596-2bb0-4d59-8f7d-1704b2f29e7e","content_key":"penntrain.course.pa-hha-aide-nutrition-hydration-safe-feeding","title":"Nutrition, Hydration, and Safe Feeding for Home Health Aides","summary":"Applies diet verification, meal support, swallowing precautions, intake observation, food safety, and timely escalation to home-based care. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"292882da-b92f-4bd5-9d6d-b32484dc001f","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/724a8596-2bb0-4d59-8f7d-1704b2f29e7e"},{"id":"8d6c4c38-4c49-431d-8b85-3167a348fabb","content_key":"penntrain.course.pa-hos-aide-nutrition-hydration-swallowing","title":"Nutrition, Hydration, and Swallowing Support for Hospice Aides","summary":"Applies comfort goals, patient choice, diet and swallowing directions, safe assistance, oral comfort, intake observation, and noncoercive family support. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"2d4cd520-0243-4a32-8656-e7e140d262b6","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/8d6c4c38-4c49-431d-8b85-3167a348fabb"},{"id":"6433cedb-8a69-466c-8487-46563babbb61","content_key":"penntrain.course.pa-hos-aide-observation-reporting-documentation","title":"Observation, Reporting, and Documentation for Hospice Aides","summary":"Develops baseline-aware observation, symptom communication, closed-loop escalation, and accurate hospice-aide records without diagnosis or independent plan changes. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"c7abdd9e-af5d-4e33-8a4d-e7ad0bffed7b","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/6433cedb-8a69-466c-8487-46563babbb61"},{"id":"66bbb941-75cc-4877-8dab-f5c6cec9d9f2","content_key":"penntrain.course.pa-hha-aide-observation-vitals-escalation","title":"Observation, Vital Signs, and Escalation for Home Health Aides","summary":"Develops accurate observation, assigned measurement, comparison with baseline, and timely escalation of acute or meaningful changes in the home. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":90,"video_count":0,"current_version_id":"c647500e-73dc-4f45-a274-8909bd9c5226","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/66bbb941-75cc-4877-8dab-f5c6cec9d9f2"},{"id":"2614e855-77b7-4747-b0d0-2aa4cbf7f5cb","content_key":"penntrain.course.pa-dhs-annual-oapsa-reporting","title":"Older Adult Protective Services: Recognition and Reporting","summary":"A complete guided annual module on the Older Adults Protective Services Act topic, recognition of abuse, neglect, exploitation, abandonment, and urgent danger, preservation of safety and evidence, and required reporting handoff. Regulatory credit is verified-only and requires completion or acceptance of the current official training plus verification of current reporting contacts and certificate evidence. Course completion is learning evidence, not automatic regulatory approval; the employing fa","category":"PCH and ALF Annual Required Topics","duration_minutes":30,"video_count":0,"current_version_id":"6acb3e63-9d21-4e36-b367-2fde91c7c43d","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/2614e855-77b7-4747-b0d0-2aa4cbf7f5cb"},{"id":"88637a6a-1bc3-4ce1-9556-96de919fc9cc","content_key":"penntrain.course.pa-hha-aide-rights-communication-culture","title":"Patient Rights, Communication, and Cultural Responsiveness for Home Health Aides","summary":"Applies patient rights, privacy, communication access, cultural humility, choice, and professional boundaries to care delivered in a person's home. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"9b9d2fb8-f53e-4f61-80c3-ffa4dc102b56","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/88637a6a-1bc3-4ce1-9556-96de919fc9cc"},{"id":"b8430040-02c6-4c76-912e-3c9806d23337","content_key":"penntrain.course.pa-pch-2600-236-dementia-foundations","title":"PCH Secured Dementia Care Unit: Annual Six-Hour Curriculum","summary":"A structured six-hour annual dementia-care curriculum for direct care staff working in a PCH secured dementia care unit under 55 Pa. Code Section 2600.236, additional to the 12-hour general annual requirement. Credit is verified-only and requires qualified review; all six hours are structured instruction and application, not on-the-job training. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and","category":"PCH Secured Dementia Care Unit Annual Training","duration_minutes":360,"video_count":0,"current_version_id":"f388563c-2a05-4017-b8bc-a0ed046e2f1e","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-07-23 08:46:37.722544+00","launch_path":"/app/courses/b8430040-02c6-4c76-912e-3c9806d23337"},{"id":"30107877-1f66-4d90-98cb-1e35927c1bd7","content_key":"penntrain.course.pa-pch-annual-assessed-needs","title":"PCH: Meeting Assessed Resident Needs","summary":"A complete PCH annual course on translating the preadmission screening, assessment, medical evaluation, and support plan into resident-specific daily services. Credit is verified-only because the employing home must validate work with its current records, policies, staff roles, and escalation process. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulato","category":"PCH Annual Required Topics","duration_minutes":75,"video_count":0,"current_version_id":"0b65a4f1-fd5d-4293-8147-8981b25b62ea","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-07-23 08:46:37.722544+00","launch_path":"/app/courses/30107877-1f66-4d90-98cb-1e35927c1bd7"},{"id":"86819c44-93d5-4eab-ba10-00caf0cc9b47","content_key":"penntrain.course.pa-pch-annual-personal-care-services","title":"PCH: Personal Care Services and Safe Assistance","summary":"A complete PCH annual course on delivering personal care services from the support plan while preserving resident choice, dignity, privacy, independence, and safety. Verified-only credit requires the home to validate its equipment, procedures, records, and role-specific skills. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"PCH Annual Required Topics","duration_minutes":75,"video_count":0,"current_version_id":"c0abd9dc-24a0-4c0b-a4b5-2c83536cec3f","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-07-23 08:46:37.722544+00","launch_path":"/app/courses/86819c44-93d5-4eab-ba10-00caf0cc9b47"},{"id":"9dc21074-96e9-4ea9-810e-83ec19b78641","content_key":"penntrain.course.pa-nh-aide-performance-facility-remediation","title":"Performance Review and Facility-Needs Remediation for Nursing Home Aides","summary":"Provides a structured annual module for correcting nurse-aide performance gaps and addressing resident-population and facility-assessment priorities through employer-selected practice. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"0a88ac2e-300e-447f-8aa8-160962cdd7b0","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/9dc21074-96e9-4ea9-810e-83ec19b78641"},{"id":"d75f8389-704b-4dae-afe8-d59223df504f","content_key":"penntrain.course.pa-gh-6400-pcp-foundations","title":"Person-Centered Practice and Everyday Choice","summary":"A comprehensive Chapter 6400 annual-training course on person-centered practice, dignity, supported choice, and translating what matters to a person into daily support. After the home verifies audience, applicability, and evidence, the course may contribute two designed hours; it is not professional continuing education approval.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"e13c871b-f934-4c83-973f-f77a71c79131","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/d75f8389-704b-4dae-afe8-d59223df504f"},{"id":"94b9c6b2-feaa-42c8-9b5f-c451cf08b990","content_key":"penntrain.course.pa-nh-aide-personal-care-skin-nutrition","title":"Personal Care, Skin Observation, Nutrition, and Hydration for Nursing Home Aides","summary":"Integrates dignified personal care with skin observation, oral health, nutrition, hydration, elimination, and prompt reporting of meaningful change. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"19288c54-745e-48ca-bca6-01de466c0f44","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/94b9c6b2-feaa-42c8-9b5f-c451cf08b990"},{"id":"39614782-39e2-473b-a0f3-927cef65e90f","content_key":"penntrain.course.pa-hha-aide-hygiene-oral-continence-skin","title":"Personal Hygiene, Oral Care, Continence, and Skin Observation for Home Health Aides","summary":"Builds complete, dignified plan-directed personal care with focused skin and oral observation, continence support, infection prevention, and change reporting. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":90,"video_count":0,"current_version_id":"dcf4d876-220d-4edc-9833-87d84439aa43","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/39614782-39e2-473b-a0f3-927cef65e90f"},{"id":"a3791c69-d7bb-4269-9d4b-8bc418fdc7f3","content_key":"penntrain.course.pa-gh-6400-person-behavior-support","title":"Preparation for Facilitated Behavior Support Verification","summary":"Preparation for a facilitated, person-specific annual verification of the current behavior-support component, communication, prevention, approved techniques, crisis response, and documentation. A learner completion certificate records preparation only; the home must separately verify live training by a person knowledgeable about the current plan.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"8d9dbcc1-2bf1-4b12-8a23-ab6e9ebf4dca","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/a3791c69-d7bb-4269-9d4b-8bc418fdc7f3"},{"id":"5ac19d64-cc96-4cd6-9969-fe2b6569809e","content_key":"penntrain.course.pa-gh-6400-person-ip-implementation","title":"Preparation for Facilitated Individual Plan Verification","summary":"Preparation for facilitated person-specific annual verification using the current assessment and Individual Plan, health and safety procedures, communication, goals, choice, documentation, and handoff. A learner completion certificate records preparation only; verified credit requires the live current-plan lab.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"0e8a7c18-f19c-4d27-bafa-fabc93943a38","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/5ac19d64-cc96-4cd6-9969-fe2b6569809e"},{"id":"c889f869-d5c3-48fc-8afa-301ecc04e078","content_key":"penntrain.course.pa-gh-6400-first-aid-cpr-verified","title":"Preparation for First Aid, Heimlich, and CPR Skills Verification","summary":"Preparation for trainer-led first aid, choking-response, and CPR skills under Section 6400.46(d). A learner completion certificate records preparation only; verified credit requires an eligible certified trainer and in-person skills, and PennTrain does not issue clinical certification.","category":"Pennsylvania Chapter 6400","duration_minutes":180,"video_count":0,"current_version_id":"6b9c2794-9400-455e-b9f9-24aebc50a592","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/c889f869-d5c3-48fc-8afa-301ecc04e078"},{"id":"532cafd4-ddd7-4d23-b9b2-b2e49ed2eb61","content_key":"penntrain.course.pa-gh-6400-fire-safety-verified","title":"Preparation for Onsite Fire Safety Verification","summary":"Preparation for qualified fire-safety training and home-specific evacuation practice under Section 6400.46. A learner completion certificate records preparation only; the LMS cannot certify the expert, facilitator, current materials, or site-specific practice.","category":"Pennsylvania Chapter 6400","duration_minutes":60,"video_count":0,"current_version_id":"b09c2ecd-43c2-4faf-b768-b5c2e306d9f2","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/532cafd4-ddd7-4d23-b9b2-b2e49ed2eb61"},{"id":"5914f559-e3a5-44a0-b0c9-bce101f1a83b","content_key":"penntrain.course.pa-gh-6400-abuse-prevent-detect","title":"Preventing and Detecting Abuse, Neglect, and Exploitation","summary":"A comprehensive Chapter 6400 annual-training course on prevention, recognition, immediate protection, trauma-informed response, and professional boundaries. It does not represent Act 31, professional-license CE, or another separately approved credential.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"17169be2-b2e3-46b4-b385-c2b078198310","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/5914f559-e3a5-44a0-b0c9-bce101f1a83b"},{"id":"ac119eaa-ec8d-4f6b-a809-90b4c0773f5c","content_key":"penntrain.course.pa-nh-aide-qapi-ethics-documentation","title":"QAPI, Ethics, and Documentation for Nursing Home Aides","summary":"Connects accurate records, ethical conduct, incident reporting, privacy, teamwork, and frontline observations to nursing-home quality assurance and performance improvement. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":45,"video_count":0,"current_version_id":"00716674-5fd5-4bf6-8abe-b20bf48821f2","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/ac119eaa-ec8d-4f6b-a809-90b4c0773f5c"},{"id":"022c42fe-feae-4f67-b1b4-7e4a5ef7891a","content_key":"penntrain.course.pa-hha-aide-rom-positioning-skin-integrity","title":"Range of Motion, Positioning, and Skin Integrity for Home Health Aides","summary":"Builds plan-directed positioning, range-of-motion, pressure prevention, device awareness, and functional-change reporting skills in the home. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"4b114544-0163-4545-8ce4-39ae2eee6a14","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/022c42fe-feae-4f67-b1b4-7e4a5ef7891a"},{"id":"89472c68-7f52-4dc9-8304-647cde87141a","content_key":"penntrain.course.pa-gh-6400-incident-response","title":"Recognizing Incidents and Immediate Protective Action","summary":"Comprehensive annual training on incident recognition, emergency triage, immediate protection, notifications, evidence preservation, and continued support.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"eaa01458-9dd5-406f-9bea-8db5949e64a7","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/89472c68-7f52-4dc9-8304-647cde87141a"},{"id":"2b3eed47-3577-4b5b-86ed-702b89ae11d1","content_key":"penntrain.course.pa-gh-6400-documentation-funds","title":"Records, Confidentiality, and Safeguarding Individual Funds","summary":"Job-skills annual training on accurate records, minimum-necessary confidentiality, individual funds, property, receipts, and audit-ready corrections.","category":"Pennsylvania Chapter 6400","duration_minutes":60,"video_count":0,"current_version_id":"c153007e-fb78-4e0d-aee8-2bac32215759","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/2b3eed47-3577-4b5b-86ed-702b89ae11d1"},{"id":"32695769-06f0-45a3-ae93-84c8ce452753","content_key":"penntrain.course.pa-gh-6400-protective-reporting","title":"Reporting Under APSA, OAPSA, and CPSL","summary":"A comprehensive Chapter 6400 course on selecting the correct Pennsylvania protective-services pathway, making prompt reports, preserving facts, and coordinating immediate protection. It does not confer Act 31 or other approved continuing-education credit.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"11df6bb1-259c-4fe7-9f14-272e6b38a0cf","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/32695769-06f0-45a3-ae93-84c8ce452753"},{"id":"2b13c14f-5876-43df-9329-612f695ba952","content_key":"penntrain.course.pa-dhs-standalone-resident-rights","title":"Resident Rights and Dignity: Annual Training for PCH and ALF Staff","summary":"The required annual deep-dive on resident rights at Pennsylvania personal care homes (PCH) and assisted living facilities (ALF): autonomy and dignity in daily care, financial and communication rights, the grievance process, and balancing rights with safety. Grounded in 55 Pa. Code Sections 2600.65(g)(3) and 2800.65(j)(3).","category":"Resident Rights","duration_minutes":60,"video_count":0,"current_version_id":"7b0b429a-3225-4a03-8b3c-561f0aad9345","version_number":1,"published_at":"2026-07-24 05:16:09.770474+00","updated_at":"2026-07-24 05:16:09.770474+00","launch_path":"/app/courses/2b13c14f-5876-43df-9329-612f695ba952"},{"id":"c665f671-0bd1-4782-9fe8-6a658aa77e62","content_key":"penntrain.course.pa-nh-aide-communication-rights-culture","title":"Resident Rights, Communication, and Cultural Responsiveness for Nursing Home Aides","summary":"Strengthens daily practices that preserve resident rights, privacy, autonomy, communication access, nondiscrimination, cultural identity, and informed choice. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":75,"video_count":0,"current_version_id":"9440e001-ce78-4592-8366-e606bd40e232","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/c665f671-0bd1-4782-9fe8-6a658aa77e62"},{"id":"1fde8db2-8f17-4654-a902-cedd8342eb30","content_key":"penntrain.course.pa-dhs-annual-resident-rights","title":"Resident Rights, Dignity, and Choice","summary":"A complete annual course on resident rights, dignity, privacy, choice, consent, freedom from abuse and retaliation, complaint access, confidentiality, least-restrictive support, and staff accountability in PCH and ALF settings. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"PCH and ALF Annual Required Topics","duration_minutes":45,"video_count":0,"current_version_id":"16d8fb9b-db3a-4684-93ab-ab06df438e2a","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/1fde8db2-8f17-4654-a902-cedd8342eb30"},{"id":"534299af-268e-464e-a64d-db1686e023c8","content_key":"penntrain.course.pa-nh-aide-restorative-nursing","title":"Restorative Nursing and Maintenance of Function for Nursing Home Aides","summary":"Teaches plan-directed support for mobility, range of motion, self-care, continence, communication, and resident participation while preventing over-assistance and avoidable decline. This vendor module contributes to annual nurse-aide in-service education; the employing facility owns tailoring, policy integration, acceptance, and compliance documentation.","category":"Nursing Home Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"9dd38442-0500-4570-a85b-d9bf03bd5a9f","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/534299af-268e-464e-a64d-db1686e023c8"},{"id":"55af6caa-1e57-40bb-8519-c9d0501c4f6d","content_key":"penntrain.course.pa-gh-6400-rights-daily-practice","title":"Rights in Daily Practice: Privacy, Risk, Funds, and Grievances","summary":"Applied Chapter 6400 annual training on shift decisions, funds safeguards, positive risk, grievance response, and objective rights documentation.","category":"Pennsylvania Chapter 6400","duration_minutes":120,"video_count":0,"current_version_id":"558acafc-bcb8-4364-9073-ef405c74f376","version_number":1,"published_at":"2026-07-23 08:46:40.885659+00","updated_at":"2026-07-23 08:46:40.885659+00","launch_path":"/app/courses/55af6caa-1e57-40bb-8519-c9d0501c4f6d"},{"id":"42290ce6-091c-5a93-b567-87bebd5b7cd5","content_key":"penntrain.course.pa-dhs-standalone-safe-management","title":"Safe Management and De-escalation: Annual Training for PCH and ALF Staff","summary":"The required annual refresher on understanding behavior as communication, preventing escalation, de-escalating safely, and the hard limits on restraint and coercion, for staff at Pennsylvania personal care homes (PCH) and assisted living facilities (ALF). Grounded in 55 Pa. Code Sections 2600.65(f)(6) and 2800.65(i)(6).","category":"Safe Management and De-escalation","duration_minutes":60,"video_count":10,"current_version_id":"ca74fcad-fa3c-598d-8f0f-188396cadbb0","version_number":2,"published_at":"2026-07-25 17:06:26.798527+00","updated_at":"2026-07-25 17:06:26.798527+00","launch_path":"/app/courses/42290ce6-091c-5a93-b567-87bebd5b7cd5"},{"id":"c2266695-ac1a-4239-82cd-fb0feed65000","content_key":"penntrain.course.pa-dhs-annual-safe-management","title":"Safe Management of Challenging Situations","summary":"A complete annual course on prevention, trauma-aware de-escalation, unmet-needs analysis, immediate safety, least-restrictive response, documentation, and team review. It carries 1.25 PCH hours and 1.50 ALF hours. Course completion is learning evidence, not automatic regulatory approval; the employing facility must verify role, unit or population applicability and accept the evidence before awarding regulatory credit.","category":"PCH and ALF Annual Required Topics","duration_minutes":90,"video_count":0,"current_version_id":"c8a97ce6-6422-451c-a780-72b2ea72ec9f","version_number":2,"published_at":"2026-07-23 08:46:37.722544+00","updated_at":"2026-08-11 01:37:53.213905+00","launch_path":"/app/courses/c2266695-ac1a-4239-82cd-fb0feed65000"},{"id":"b4413c60-334e-401d-bdd1-782ccc840eb7","content_key":"penntrain.course.pa-hos-aide-skin-positioning-pressure-comfort","title":"Skin Integrity, Positioning, and Pressure Comfort for Hospice Aides","summary":"Integrates comfort-focused positioning, pressure reduction, skin and device observation, gentle movement, and timely communication when goals or tolerance change. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"b5cd9bdf-1221-4f4c-9dbf-2c5faab1f0eb","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/b4413c60-334e-401d-bdd1-782ccc840eb7"},{"id":"7206293b-af58-42d5-87b2-1c39effd9a0e","content_key":"penntrain.course.pa-hha-aide-transfers-ambulation-falls","title":"Transfers, Ambulation, and Fall Response for Home Health Aides","summary":"Develops safe plan-directed mobility support, use of transfer devices, body mechanics, home-hazard control, and post-fall response. Vendor content contributes only when the employing HHA's RN approves the content and attends the in-service to supervise it, and the agency accepts and documents the hours.","category":"Home Health Aide Annual","duration_minutes":90,"video_count":0,"current_version_id":"e5527879-493e-48fb-8010-2db090964c04","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/7206293b-af58-42d5-87b2-1c39effd9a0e"},{"id":"60a3cc4a-0ff5-49c9-a2f4-57e1a273f339","content_key":"penntrain.course.pa-hos-aide-transfers-ambulation-falls","title":"Transfers, Ambulation, and Fall Response for Hospice Aides","summary":"Develops safe mobility assistance that respects changing strength, comfort goals, equipment needs, caregiver capacity, and patient choice near end of life. Vendor content contributes only under employing-hospice RN supervision and hospice acceptance and documentation.","category":"Hospice Aide Annual","duration_minutes":60,"video_count":0,"current_version_id":"bfcfd8a0-2052-4b9f-91f3-cb2a16ab09c7","version_number":1,"published_at":"2026-07-23 08:46:43.023284+00","updated_at":"2026-07-23 08:46:43.023284+00","launch_path":"/app/courses/60a3cc4a-0ff5-49c9-a2f4-57e1a273f339"}]$catalog$::jsonb) as row_data (
    id uuid,
    content_key text,
    title text,
    summary text,
    category text,
    duration_minutes integer,
    video_count integer,
    current_version_id uuid,
    version_number integer,
    published_at timestamptz,
    updated_at timestamptz,
    launch_path text
  )
)
insert into hub.course_links (
  content_item_id, penntrain_course_id, source_version, launch_path,
  duration_minutes, level, objectives, source_updated_at, updated_at
)
select
  md5('penntrain-course-item:' || id::text)::uuid,
  id::text,
  'PennTrain:' || current_version_id::text || ':v' || version_number,
  launch_path,
  duration_minutes,
  null,
  array[category]::text[],
  updated_at,
  now()
from source_rows
on conflict (content_item_id) do update set
  penntrain_course_id = excluded.penntrain_course_id,
  source_version = excluded.source_version,
  launch_path = excluded.launch_path,
  duration_minutes = excluded.duration_minutes,
  objectives = excluded.objectives,
  source_updated_at = excluded.source_updated_at,
  updated_at = excluded.updated_at;

with source_rows as (
  select *
  from jsonb_to_recordset($articles$[{"id":"2a0d3b49-3b16-48c0-be1e-f8e87f61c0f4","content_key":"penntrain.help.job-aide.2a0d3b49-3b16-48c0-be1e-f8e87f61c0f4","article_type":"job_aide","category":"Employees & Onboarding","title":"Add a New Employee","summary":"Create a single employee record with the details compliance tracking depends on.","body_markdown":"Create a single employee record with the details compliance tracking depends on.\n\n## Steps\n\n1. Go to Employees and click Add Employee.\n\n2. Enter first name, last name, email, phone, job title, and department.\n\n3. Select the employee's facility and enter their hire date.\n\n4. Set Worker Type -- regular, agency, substitute, or volunteer -- since agency/substitute/volunteer staff get the faster rapid-orientation checklist instead of the standard one.\n\n5. Check Administers Medications if this employee gives or assists with medications; this drives medication-administration and diabetes-education tracking and determines whether they appear on the Who Can Pass Meds Today roster.\n\n6. Enter Scheduled Hours Per Week if known -- it drives the 40-scheduled-hour orientation deadline for new hires.\n\n7. Set Status to Active and click Save.\n\n## Tips\n\n- You can always edit these fields later from the employee's own record if something changes.\n\n- If you're onboarding more than a handful of employees at once, use Bulk-Import an Employee Roster via CSV instead.\n\nRelated CareBase page: **Go to Employees** (/app/employees)","body_text":"Create a single employee record with the details compliance tracking depends on.\nGo to Employees and click Add Employee.\nEnter first name, last name, email, phone, job title, and department.\nSelect the employee's facility and enter their hire date.\nSet Worker Type -- regular, agency, substitute, or volunteer -- since agency/substitute/volunteer staff get the faster rapid-orientation checklist instead of the standard one.\nCheck Administers Medications if this employee gives or assists with medications; this drives medication-administration and diabetes-education tracking and determines whether they appear on the Who Can Pass Meds Today roster.\nEnter Scheduled Hours Per Week if known -- it drives the 40-scheduled-hour orientation deadline for new hires.\nSet Status to Active and click Save.\nYou can always edit these fields later from the employee's own record if something changes.\nIf you're onboarding more than a handful of employees at once, use Bulk-Import an Employee Roster via CSV instead.","source_audience":["org_admin","facility_manager"],"route_pattern":"/app/employees","sort_order":0,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"44ee9901-0901-44c9-956e-ca82502d5894","content_key":"penntrain.help.faq.44ee9901-0901-44c9-956e-ca82502d5894","article_type":"faq","category":"Getting Started & Roles","title":"What is the Help Center, and what's in it?","summary":"The Help Center is where you find answers without leaving the app: this FAQ, a library of step-by-step Job Aides for common workflows, a downloadable PDF user manual, and a support ticketing system for anything not covered here. Org admins, facility managers, trainers, and auditors reach it from /app/help; employees reach the same content from /me/help.","body_markdown":"The Help Center is where you find answers without leaving the app: this FAQ, a library of step-by-step Job Aides for common workflows, a downloadable PDF user manual, and a support ticketing system for anything not covered here. Org admins, facility managers, trainers, and auditors reach it from /app/help; employees reach the same content from /me/help.","body_text":"The Help Center is where you find answers without leaving the app: this FAQ, a library of step-by-step Job Aides for common workflows, a downloadable PDF user manual, and a support ticketing system for anything not covered here. Org admins, facility managers, trainers, and auditors reach it from /app/help; employees reach the same content from /me/help.","source_audience":[],"route_pattern":null,"sort_order":0,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"867ab641-4ecb-4a19-aadd-cdd4f80dcd46","content_key":"penntrain.help.job-aide.867ab641-4ecb-4a19-aadd-cdd4f80dcd46","article_type":"job_aide","category":"Employees & Onboarding","title":"Bulk-Import an Employee Roster via CSV","summary":"Onboard an entire facility's staff in minutes instead of entering employees one at a time.","body_markdown":"Onboard an entire facility's staff in minutes instead of entering employees one at a time.\n\n## Steps\n\n1. Go to Employees and click Upload (the bulk import button).\n\n2. Download the CSV template if you need the expected column headers.\n\n3. Fill in one row per employee and upload the completed file.\n\n4. Wait for the import to finish -- it processes under your own login, so the same organization scoping and permissions apply as if you'd entered each row by hand.\n\n5. Review the row-by-row results: each row reports success or a specific error.\n\n6. Fix and re-upload only the rows that failed; successful rows are already saved and won't be duplicated.\n\n## Tips\n\n- Double-check facility names and email addresses before uploading -- most row failures come from a typo in one of those two fields.\n\nRelated CareBase page: **Go to Employees** (/app/employees)","body_text":"Onboard an entire facility's staff in minutes instead of entering employees one at a time.\nGo to Employees and click Upload (the bulk import button).\nDownload the CSV template if you need the expected column headers.\nFill in one row per employee and upload the completed file.\nWait for the import to finish -- it processes under your own login, so the same organization scoping and permissions apply as if you'd entered each row by hand.\nReview the row-by-row results: each row reports success or a specific error.\nFix and re-upload only the rows that failed; successful rows are already saved and won't be duplicated.\nDouble-check facility names and email addresses before uploading -- most row failures come from a typo in one of those two fields.","source_audience":["org_admin","facility_manager"],"route_pattern":"/app/employees","sort_order":1,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"2569aa9e-55e0-4da8-8556-8815959dd425","content_key":"penntrain.help.faq.2569aa9e-55e0-4da8-8556-8815959dd425","article_type":"faq","category":"Getting Started & Roles","title":"What are the six roles, and what does each one actually see?","summary":"platform_admin is CareMetric Train staff -- confined to /admin, with the only ability to author courses and quizzes. org_admin and facility_manager work in /app: org_admin sees every facility in the organization, facility_manager is scoped to the facility (or facilities) they're assigned to. auditor gets the same /app compliance reporting views with zero ability to create, edit, or delete anything -- it's read-only by database policy, not just hidden buttons. trainer works across /trainer and tr","body_markdown":"platform_admin is CareMetric Train staff -- confined to /admin, with the only ability to author courses and quizzes. org_admin and facility_manager work in /app: org_admin sees every facility in the organization, facility_manager is scoped to the facility (or facilities) they're assigned to. auditor gets the same /app compliance reporting views with zero ability to create, edit, or delete anything -- it's read-only by database policy, not just hidden buttons. trainer works across /trainer and training-related /app pages: scheduling and running live classes, monitoring retraining, browsing courses, assigning courses and training plans, recording competencies/practicums, reviewing pending external certificates, and read access to facilities/employees. employee is self-service in /me: their own training records, assigned courses, certificates, credentials, schedule, and documents.","body_text":"platform_admin is CareMetric Train staff -- confined to /admin, with the only ability to author courses and quizzes. org_admin and facility_manager work in /app: org_admin sees every facility in the organization, facility_manager is scoped to the facility (or facilities) they're assigned to. auditor gets the same /app compliance reporting views with zero ability to create, edit, or delete anything -- it's read-only by database policy, not just hidden buttons. trainer works across /trainer and training-related /app pages: scheduling and running live classes, monitoring retraining, browsing courses, assigning courses and training plans, recording competencies/practicums, reviewing pending external certificates, and read access to facilities/employees. employee is self-service in /me: their own training records, assigned courses, certificates, credentials, schedule, and documents.","source_audience":[],"route_pattern":null,"sort_order":1,"updated_at":"2026-07-12 17:15:35.356395+00"},{"id":"a860ee65-88b3-4378-bb87-70477c27feeb","content_key":"penntrain.help.job-aide.a860ee65-88b3-4378-bb87-70477c27feeb","article_type":"job_aide","category":"Employees & Onboarding","title":"Invite a New User Account","summary":"Give someone sign-in access with the right role, separate from creating their employee record.","body_markdown":"Give someone sign-in access with the right role, separate from creating their employee record.\n\n## Steps\n\n1. Go to Users and click Add User.\n\n2. Enter their name and email, then choose a role -- facility_manager can only create trainer or employee accounts; org_admin can create any non-platform_admin role in the organization.\n\n3. If applicable, link the account to an existing employee record so their training data shows up under their own login.\n\n4. Save -- the new user receives access to sign in under their assigned role.\n\n## Tips\n\n- An employee record and a user login are two different things: an employee can exist without ever getting sign-in access, and every user account must belong to exactly one role.\n\n- Email address changes on an existing account require an admin action -- edit the user from Users, or contact platform support if you can't.\n\nRelated CareBase page: **Go to Users** (/app/users)","body_text":"Give someone sign-in access with the right role, separate from creating their employee record.\nGo to Users and click Add User.\nEnter their name and email, then choose a role -- facility_manager can only create trainer or employee accounts; org_admin can create any non-platform_admin role in the organization.\nIf applicable, link the account to an existing employee record so their training data shows up under their own login.\nSave -- the new user receives access to sign in under their assigned role.\nAn employee record and a user login are two different things: an employee can exist without ever getting sign-in access, and every user account must belong to exactly one role.\nEmail address changes on an existing account require an admin action -- edit the user from Users, or contact platform support if you can't.","source_audience":["org_admin","facility_manager"],"route_pattern":"/app/users","sort_order":2,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"5a760c06-b26f-4ef1-9727-106fced3554c","content_key":"penntrain.help.faq.5a760c06-b26f-4ef1-9727-106fced3554c","article_type":"faq","category":"Getting Started & Roles","title":"What's the difference between org_admin and facility_manager?","summary":"org_admin is the organization-wide administrator: every facility, plus org-only tools like Users, Settings, and deleting training plans. facility_manager has nearly the same day-to-day toolset -- employees, training, courses, scheduling, incidents, and more -- but scoped to just the facility or facilities they're assigned to. If you manage a single building, you'll likely be a facility_manager; if you oversee the whole organization, you're an org_admin.","body_markdown":"org_admin is the organization-wide administrator: every facility, plus org-only tools like Users, Settings, and deleting training plans. facility_manager has nearly the same day-to-day toolset -- employees, training, courses, scheduling, incidents, and more -- but scoped to just the facility or facilities they're assigned to. If you manage a single building, you'll likely be a facility_manager; if you oversee the whole organization, you're an org_admin.","body_text":"org_admin is the organization-wide administrator: every facility, plus org-only tools like Users, Settings, and deleting training plans. facility_manager has nearly the same day-to-day toolset -- employees, training, courses, scheduling, incidents, and more -- but scoped to just the facility or facilities they're assigned to. If you manage a single building, you'll likely be a facility_manager; if you oversee the whole organization, you're an org_admin.","source_audience":[],"route_pattern":null,"sort_order":2,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"9950730a-9115-43c1-bfca-2ff95346849a","content_key":"penntrain.help.job-aide.9950730a-9115-43c1-bfca-2ff95346849a","article_type":"job_aide","category":"Training & Courses","title":"Assign a Course to an Employee","summary":"Give one employee a specific course to complete, with an optional due date.","body_markdown":"Give one employee a specific course to complete, with an optional due date.\n\n## Steps\n\n1. Go to Course Assignments and click Assign Course.\n\n2. Select the employee and the course from the catalog.\n\n3. Optionally pick a specific course version (otherwise the course's current published version is used).\n\n4. Set a due date if this assignment needs one -- assignments without a due date still show up under the employee's My Courses, just not on dashboard deadline widgets.\n\n5. Save. The assignment starts as Assigned and moves to In Progress, Completed, or Overdue automatically as the employee works through it.\n\n## Tips\n\n- For onboarding or recurring curricula, build a Training Plan instead and apply it to employees in bulk rather than assigning course by course.\n\nRelated CareBase page: **Go to Course Assignments** (/app/course-assignments)","body_text":"Give one employee a specific course to complete, with an optional due date.\nGo to Course Assignments and click Assign Course.\nSelect the employee and the course from the catalog.\nOptionally pick a specific course version (otherwise the course's current published version is used).\nSet a due date if this assignment needs one -- assignments without a due date still show up under the employee's My Courses, just not on dashboard deadline widgets.\nSave. The assignment starts as Assigned and moves to In Progress, Completed, or Overdue automatically as the employee works through it.\nFor onboarding or recurring curricula, build a Training Plan instead and apply it to employees in bulk rather than assigning course by course.","source_audience":["org_admin","facility_manager","trainer"],"route_pattern":"/app/course-assignments","sort_order":3,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"777aa4c7-4987-48e4-905e-1d22e8a498df","content_key":"penntrain.help.faq.777aa4c7-4987-48e4-905e-1d22e8a498df","article_type":"faq","category":"Getting Started & Roles","title":"I just set up my organization -- where do I start?","summary":"Self-service signup always creates a brand-new organization with you as its org_admin. From there: add your facilities, bring in your employee roster (one at a time or by CSV import), configure the training types and credential requirements your license type needs, and set up shift patterns if you're using scheduling. Alerts, the training matrix, and the compliance binder all populate automatically once employees and their training records exist.","body_markdown":"Self-service signup always creates a brand-new organization with you as its org_admin. From there: add your facilities, bring in your employee roster (one at a time or by CSV import), configure the training types and credential requirements your license type needs, and set up shift patterns if you're using scheduling. Alerts, the training matrix, and the compliance binder all populate automatically once employees and their training records exist.","body_text":"Self-service signup always creates a brand-new organization with you as its org_admin. From there: add your facilities, bring in your employee roster (one at a time or by CSV import), configure the training types and credential requirements your license type needs, and set up shift patterns if you're using scheduling. Alerts, the training matrix, and the compliance binder all populate automatically once employees and their training records exist.","source_audience":[],"route_pattern":null,"sort_order":3,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"a9df6a09-2c93-4f9c-979f-6513763e309b","content_key":"penntrain.help.job-aide.a9df6a09-2c93-4f9c-979f-6513763e309b","article_type":"job_aide","category":"Training & Courses","title":"Build a Quiz for a Course","summary":"Author quiz questions, answers, passing score, and attempt limits for a course (platform admin only).","body_markdown":"Author quiz questions, answers, passing score, and attempt limits for a course (platform admin only).\n\n## Steps\n\n1. From the course's detail page, open its quiz (or create one for a course version that doesn't have one yet).\n\n2. Click Add Question and enter the question text and its answer options.\n\n3. Mark the correct answer -- grading is server-side and based on this flag, so it can't be spoofed by a client later.\n\n4. Set the quiz's passing score percentage and either a maximum number of attempts or unlimited attempts.\n\n5. Repeat for each question, then save.\n\n## Tips\n\n- Once the parent course version is published, its quiz is locked -- create a new course version if you need to change questions after that point.\n\n- Course and quiz authoring is platform_admin-exclusive; org_admin, facility_manager, and trainer can browse and assign courses but cannot edit their content.\n\nRelated CareBase page: **Go to Courses (Admin)** (/admin/courses)","body_text":"Author quiz questions, answers, passing score, and attempt limits for a course (platform admin only).\nFrom the course's detail page, open its quiz (or create one for a course version that doesn't have one yet).\nClick Add Question and enter the question text and its answer options.\nMark the correct answer -- grading is server-side and based on this flag, so it can't be spoofed by a client later.\nSet the quiz's passing score percentage and either a maximum number of attempts or unlimited attempts.\nRepeat for each question, then save.\nOnce the parent course version is published, its quiz is locked -- create a new course version if you need to change questions after that point.\nCourse and quiz authoring is platform_admin-exclusive; org_admin, facility_manager, and trainer can browse and assign courses but cannot edit their content.","source_audience":["platform_admin"],"route_pattern":"/admin/courses","sort_order":4,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"1e065985-a74f-48fb-988e-eabb669b121c","content_key":"penntrain.help.faq.1e065985-a74f-48fb-988e-eabb669b121c","article_type":"faq","category":"Employees & Training Records","title":"How do I add an employee, and what do I need on hand?","summary":"Go to Employees and click Add Employee. You'll need their name, contact info, job title, facility, hire date, and status. Two flags matter for compliance: whether they administer medications (drives medication-administration and diabetes-education tracking) and worker type -- regular, agency, substitute, or volunteer, since agency/substitute/volunteer staff get a faster, rapid-orientation checklist instead of the standard one.","body_markdown":"Go to Employees and click Add Employee. You'll need their name, contact info, job title, facility, hire date, and status. Two flags matter for compliance: whether they administer medications (drives medication-administration and diabetes-education tracking) and worker type -- regular, agency, substitute, or volunteer, since agency/substitute/volunteer staff get a faster, rapid-orientation checklist instead of the standard one.","body_text":"Go to Employees and click Add Employee. You'll need their name, contact info, job title, facility, hire date, and status. Two flags matter for compliance: whether they administer medications (drives medication-administration and diabetes-education tracking) and worker type -- regular, agency, substitute, or volunteer, since agency/substitute/volunteer staff get a faster, rapid-orientation checklist instead of the standard one.","source_audience":[],"route_pattern":null,"sort_order":4,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"b45dff22-fae6-4ba7-8117-85bb2afa8dd5","content_key":"penntrain.help.faq.b45dff22-fae6-4ba7-8117-85bb2afa8dd5","article_type":"faq","category":"Employees & Training Records","title":"Can I bring in my whole existing roster instead of typing employees in one at a time?","summary":"Yes. The Employees page has a bulk CSV import that runs under your own login (organization scoping and RLS still apply exactly as if you'd entered each employee by hand), and it reports back row-by-row which employees imported successfully and which rows had errors so you can fix and re-upload just those.","body_markdown":"Yes. The Employees page has a bulk CSV import that runs under your own login (organization scoping and RLS still apply exactly as if you'd entered each employee by hand), and it reports back row-by-row which employees imported successfully and which rows had errors so you can fix and re-upload just those.","body_text":"Yes. The Employees page has a bulk CSV import that runs under your own login (organization scoping and RLS still apply exactly as if you'd entered each employee by hand), and it reports back row-by-row which employees imported successfully and which rows had errors so you can fix and re-upload just those.","source_audience":[],"route_pattern":null,"sort_order":5,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"73f4912a-3970-40d6-95a9-22be8892e0e0","content_key":"penntrain.help.job-aide.73f4912a-3970-40d6-95a9-22be8892e0e0","article_type":"job_aide","category":"Training & Courses","title":"Create a Training Plan and Apply It to Employees","summary":"Bundle courses and training-type requirements into a reusable curriculum, then apply it in bulk.","body_markdown":"Bundle courses and training-type requirements into a reusable curriculum, then apply it in bulk.\n\n## Steps\n\n1. Go to Training Plans and click New Plan.\n\n2. Name the plan (for example, New Hire Onboarding) and add a description.\n\n3. Expand the plan and click Add Item for each course or legacy training type it should include, marking each as required or optional.\n\n4. Reorder items with the up/down arrows if the sequence matters.\n\n5. Click Apply to Employee(s), search and select who the plan applies to, and confirm.\n\n6. Review the summary: it reports how many course assignments were created and how many training-type requirements are now tracked as pending for each employee.\n\n## Tips\n\n- facility_manager can view and browse training plans but can't create, edit, or apply them -- that's org_admin and trainer only.\n\n- Removing an item from a plan template later doesn't undo assignments already created from a previous Apply run.\n\nRelated CareBase page: **Go to Training Plans** (/app/training-plans)","body_text":"Bundle courses and training-type requirements into a reusable curriculum, then apply it in bulk.\nGo to Training Plans and click New Plan.\nName the plan (for example, New Hire Onboarding) and add a description.\nExpand the plan and click Add Item for each course or legacy training type it should include, marking each as required or optional.\nReorder items with the up/down arrows if the sequence matters.\nClick Apply to Employee(s), search and select who the plan applies to, and confirm.\nReview the summary: it reports how many course assignments were created and how many training-type requirements are now tracked as pending for each employee.\nfacility_manager can view and browse training plans but can't create, edit, or apply them -- that's org_admin and trainer only.\nRemoving an item from a plan template later doesn't undo assignments already created from a previous Apply run.","source_audience":["org_admin","trainer"],"route_pattern":"/app/training-plans","sort_order":5,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"baa75d96-2424-4fac-a329-167d0c7c8677","content_key":"penntrain.help.job-aide.baa75d96-2424-4fac-a329-167d0c7c8677","article_type":"job_aide","category":"Training & Courses","title":"Take an Assigned Course","summary":"Work through a course assigned to you, lesson by lesson, from any browser.","body_markdown":"Work through a course assigned to you, lesson by lesson, from any browser.\n\n## Steps\n\n1. Go to My Courses and pick the course you want to start -- it lists every course assigned to you, whether or not it has a due date.\n\n2. Click into the course to open it; this takes you to the course-taking view.\n\n3. Work through each lesson in order, including any attached video or reading material.\n\n4. If the course has a quiz, it appears once you've completed the lessons.\n\n5. Your progress and completion status update automatically as you go.\n\n## Tips\n\n- No software install is required -- courses run entirely in your browser.\n\nRelated CareBase page: **Go to My Courses** (/me/courses)","body_text":"Work through a course assigned to you, lesson by lesson, from any browser.\nGo to My Courses and pick the course you want to start -- it lists every course assigned to you, whether or not it has a due date.\nClick into the course to open it; this takes you to the course-taking view.\nWork through each lesson in order, including any attached video or reading material.\nIf the course has a quiz, it appears once you've completed the lessons.\nYour progress and completion status update automatically as you go.\nNo software install is required -- courses run entirely in your browser.","source_audience":["employee"],"route_pattern":"/me/courses","sort_order":6,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"bf6a8691-eb80-4a20-ad28-5678612f288e","content_key":"penntrain.help.faq.bf6a8691-eb80-4a20-ad28-5678612f288e","article_type":"faq","category":"Employees & Training Records","title":"What do the training record statuses -- compliant, due soon, expired, missing -- actually mean?","summary":"Compliant means the record is current. Due soon means it's still valid today but will expire inside the training type's warning window, so it counts as \"currently authorized\" everywhere the app checks that (like Who Can Pass Meds Today). Expired means the deadline has passed, and missing means no record exists at all for a requirement that applies to that employee. Only expired and missing disqualify someone from being considered currently compliant.","body_markdown":"Compliant means the record is current. Due soon means it's still valid today but will expire inside the training type's warning window, so it counts as \"currently authorized\" everywhere the app checks that (like Who Can Pass Meds Today). Expired means the deadline has passed, and missing means no record exists at all for a requirement that applies to that employee. Only expired and missing disqualify someone from being considered currently compliant.","body_text":"Compliant means the record is current. Due soon means it's still valid today but will expire inside the training type's warning window, so it counts as \"currently authorized\" everywhere the app checks that (like Who Can Pass Meds Today). Expired means the deadline has passed, and missing means no record exists at all for a requirement that applies to that employee. Only expired and missing disqualify someone from being considered currently compliant.","source_audience":[],"route_pattern":null,"sort_order":6,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"dcde647c-435c-4135-ab9c-93324da089d2","content_key":"penntrain.help.job-aide.dcde647c-435c-4135-ab9c-93324da089d2","article_type":"job_aide","category":"Training & Courses","title":"Take a Quiz and Review Your Score","summary":"Complete a course's quiz and see whether you passed.","body_markdown":"Complete a course's quiz and see whether you passed.\n\n## Steps\n\n1. From the course, open its quiz -- you'll see the number of questions, the passing score, and how many attempts you're allowed (or if attempts are unlimited).\n\n2. Click to start, then answer each question.\n\n3. Submit the quiz when finished.\n\n4. Review your score and, for any missed questions, the correct answer shown in the review.\n\n5. If you didn't pass and attempts remain, retake the quiz directly from the same screen.\n\n## Tips\n\n- Grading happens on the server the moment you submit, so your score is final and can't be edited after the fact.\n\nRelated CareBase page: **Go to My Courses** (/me/courses)","body_text":"Complete a course's quiz and see whether you passed.\nFrom the course, open its quiz -- you'll see the number of questions, the passing score, and how many attempts you're allowed (or if attempts are unlimited).\nClick to start, then answer each question.\nSubmit the quiz when finished.\nReview your score and, for any missed questions, the correct answer shown in the review.\nIf you didn't pass and attempts remain, retake the quiz directly from the same screen.\nGrading happens on the server the moment you submit, so your score is final and can't be edited after the fact.","source_audience":["employee"],"route_pattern":"/me/courses","sort_order":7,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"d6d99dc9-6fbb-474e-89e3-0d01af774445","content_key":"penntrain.help.faq.d6d99dc9-6fbb-474e-89e3-0d01af774445","article_type":"faq","category":"Employees & Training Records","title":"Where do I see one employee's full compliance picture in one place?","summary":"Open their record from the Employees list. Employee Detail shows their training records, credentials, practicums, onboarding checklist, retention check-ins, and notes side by side -- it's the fastest way to answer \"is this person actually current on everything\" without hunting across separate pages.","body_markdown":"Open their record from the Employees list. Employee Detail shows their training records, credentials, practicums, onboarding checklist, retention check-ins, and notes side by side -- it's the fastest way to answer \"is this person actually current on everything\" without hunting across separate pages.","body_text":"Open their record from the Employees list. Employee Detail shows their training records, credentials, practicums, onboarding checklist, retention check-ins, and notes side by side -- it's the fastest way to answer \"is this person actually current on everything\" without hunting across separate pages.","source_audience":[],"route_pattern":null,"sort_order":7,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"a9c40419-f11e-43ea-9515-db1cbb30a250","content_key":"penntrain.help.job-aide.a9c40419-f11e-43ea-9515-db1cbb30a250","article_type":"job_aide","category":"Training & Courses","title":"View and Download Your Certificate","summary":"Get a downloadable, verifiable PDF certificate for a course you completed.","body_markdown":"Get a downloadable, verifiable PDF certificate for a course you completed.\n\n## Steps\n\n1. Go to My Certificates.\n\n2. Find the certificate for the course you completed.\n\n3. Click Download to generate the PDF -- it opens in a new tab once generated.\n\n4. Note the certificate's public verification link if you need to share proof of completion with an employer or a surveyor.\n\n## Tips\n\n- A certificate that shows as expired here means its renewal window has passed -- check My Courses for a renewal assignment.\n\nRelated CareBase page: **Go to My Certificates** (/me/certificates)","body_text":"Get a downloadable, verifiable PDF certificate for a course you completed.\nGo to My Certificates.\nFind the certificate for the course you completed.\nClick Download to generate the PDF -- it opens in a new tab once generated.\nNote the certificate's public verification link if you need to share proof of completion with an employer or a surveyor.\nA certificate that shows as expired here means its renewal window has passed -- check My Courses for a renewal assignment.","source_audience":["employee"],"route_pattern":"/me/certificates","sort_order":8,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"4ab4c48a-5e5e-4b15-8c16-d3021c2ca236","content_key":"penntrain.help.faq.4ab4c48a-5e5e-4b15-8c16-d3021c2ca236","article_type":"faq","category":"Courses & Quizzes","title":"Who can create or edit courses and quizzes?","summary":"Course and quiz authoring is platform_admin-exclusive -- creating or editing courses, course versions, content blocks, quizzes, questions, and answers. Org admins, facility managers, and trainers can browse the full course catalog and assign courses to employees, but they can't change course content itself. Once a course version is published, its content is locked and can't be edited, even by a platform admin, without creating a new version.","body_markdown":"Course and quiz authoring is platform_admin-exclusive -- creating or editing courses, course versions, content blocks, quizzes, questions, and answers. Org admins, facility managers, and trainers can browse the full course catalog and assign courses to employees, but they can't change course content itself. Once a course version is published, its content is locked and can't be edited, even by a platform admin, without creating a new version.","body_text":"Course and quiz authoring is platform_admin-exclusive -- creating or editing courses, course versions, content blocks, quizzes, questions, and answers. Org admins, facility managers, and trainers can browse the full course catalog and assign courses to employees, but they can't change course content itself. Once a course version is published, its content is locked and can't be edited, even by a platform admin, without creating a new version.","source_audience":[],"route_pattern":null,"sort_order":8,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"e43be74a-d3ec-4f76-82f1-0134bf879dd5","content_key":"penntrain.help.job-aide.e43be74a-d3ec-4f76-82f1-0134bf879dd5","article_type":"job_aide","category":"Training & Courses","title":"Approve an Externally-Uploaded Certificate","summary":"Review a certificate an employee uploaded from outside the platform and decide whether it counts toward compliance.","body_markdown":"Review a certificate an employee uploaded from outside the platform and decide whether it counts toward compliance.\n\n## Steps\n\n1. Go to Pending Approvals.\n\n2. Under New Submissions, review each externally uploaded certificate -- who submitted it, when, and which employee it's for.\n\n3. Open the document to verify it, then decide: link it to a training requirement and approve, or decline it.\n\n4. Check the Pending Review tab for records already linked to a training requirement that still need a final compliance decision.\n\n5. Confirm your decision -- approved records update the employee's training record status immediately.\n\n## Tips\n\n- Use the \"hide documents older than\" filter to focus the queue on recent submissions if it gets long.\n\nRelated CareBase page: **Go to Pending Approvals** (/app/pending-approvals)","body_text":"Review a certificate an employee uploaded from outside the platform and decide whether it counts toward compliance.\nGo to Pending Approvals.\nUnder New Submissions, review each externally uploaded certificate -- who submitted it, when, and which employee it's for.\nOpen the document to verify it, then decide: link it to a training requirement and approve, or decline it.\nCheck the Pending Review tab for records already linked to a training requirement that still need a final compliance decision.\nConfirm your decision -- approved records update the employee's training record status immediately.\nUse the \"hide documents older than\" filter to focus the queue on recent submissions if it gets long.","source_audience":["org_admin","facility_manager","trainer"],"route_pattern":"/app/pending-approvals","sort_order":9,"updated_at":"2026-07-12 17:15:35.356395+00"},{"id":"790af696-9594-47aa-9ff5-523e87c74f6c","content_key":"penntrain.help.faq.790af696-9594-47aa-9ff5-523e87c74f6c","article_type":"faq","category":"Courses & Quizzes","title":"How do I assign a course to an employee?","summary":"Go to Course Assignments, click Assign Course, and pick the employee, course, and (optionally) a due date. You can also skip individual assignment entirely by building a Training Plan and applying it to one or more employees at once -- that creates the same course assignments in bulk plus tracks any non-course training requirements bundled into the plan.","body_markdown":"Go to Course Assignments, click Assign Course, and pick the employee, course, and (optionally) a due date. You can also skip individual assignment entirely by building a Training Plan and applying it to one or more employees at once -- that creates the same course assignments in bulk plus tracks any non-course training requirements bundled into the plan.","body_text":"Go to Course Assignments, click Assign Course, and pick the employee, course, and (optionally) a due date. You can also skip individual assignment entirely by building a Training Plan and applying it to one or more employees at once -- that creates the same course assignments in bulk plus tracks any non-course training requirements bundled into the plan.","source_audience":[],"route_pattern":null,"sort_order":9,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"2418707f-ee73-40ab-af1a-d7a56524b3c8","content_key":"penntrain.help.faq.2418707f-ee73-40ab-af1a-d7a56524b3c8","article_type":"faq","category":"Courses & Quizzes","title":"How does quiz grading work -- can an employee retake a quiz if they don't pass?","summary":"Grading happens server-side, not in the browser -- an employee's score and whether each answer was correct are never client-writable, so results can't be tampered with. Each quiz has its own passing score and either a fixed number of attempts or unlimited attempts, both set when the quiz was built; if attempts remain, the employee can retake it immediately from the course.","body_markdown":"Grading happens server-side, not in the browser -- an employee's score and whether each answer was correct are never client-writable, so results can't be tampered with. Each quiz has its own passing score and either a fixed number of attempts or unlimited attempts, both set when the quiz was built; if attempts remain, the employee can retake it immediately from the course.","body_text":"Grading happens server-side, not in the browser -- an employee's score and whether each answer was correct are never client-writable, so results can't be tampered with. Each quiz has its own passing score and either a fixed number of attempts or unlimited attempts, both set when the quiz was built; if attempts remain, the employee can retake it immediately from the course.","source_audience":[],"route_pattern":null,"sort_order":10,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"7f85a5a2-6e6a-4634-b833-a074a9a4cf27","content_key":"penntrain.help.job-aide.7f85a5a2-6e6a-4634-b833-a074a9a4cf27","article_type":"job_aide","category":"Training & Courses","title":"Schedule a Live Training Class and Capture Sign-In","summary":"Run an instructor-led session and record attendance so it counts toward compliance like an online course.","body_markdown":"Run an instructor-led session and record attendance so it counts toward compliance like an online course.\n\n## Steps\n\n1. Go to Training Classes and click New Class.\n\n2. Enter the class name, training type, date, and facility, then save.\n\n3. Add attendees from the class detail page.\n\n4. For in-person check-in, open QR Check-In and let staff scan the code with their phone to check in, then scan again to check out -- it rotates automatically every 30 seconds for security.\n\n5. As a paper backup, print the Notice of Staff Meeting, which includes a long-lived QR code plus a paper sign-in table.\n\n6. Once the class is done, use Upload Roster to attach the completed paper sign-in sheet if you used one.\n\n7. Mark the class Completed once attendance is finalized.\n\n## Tips\n\n- Kiosk Mode turns a shared tablet or computer into a stationary check-in station for the whole session.\n\nRelated CareBase page: **Go to Training Classes** (/trainer/classes)","body_text":"Run an instructor-led session and record attendance so it counts toward compliance like an online course.\nGo to Training Classes and click New Class.\nEnter the class name, training type, date, and facility, then save.\nAdd attendees from the class detail page.\nFor in-person check-in, open QR Check-In and let staff scan the code with their phone to check in, then scan again to check out -- it rotates automatically every 30 seconds for security.\nAs a paper backup, print the Notice of Staff Meeting, which includes a long-lived QR code plus a paper sign-in table.\nOnce the class is done, use Upload Roster to attach the completed paper sign-in sheet if you used one.\nMark the class Completed once attendance is finalized.\nKiosk Mode turns a shared tablet or computer into a stationary check-in station for the whole session.","source_audience":["trainer","org_admin","facility_manager"],"route_pattern":"/trainer/classes","sort_order":10,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"eb0d96e4-2948-45c3-b799-e53da619dc81","content_key":"penntrain.help.job-aide.eb0d96e4-2948-45c3-b799-e53da619dc81","article_type":"job_aide","category":"Scheduling","title":"Set Up Facility Shifts, Units & Typical Patterns","summary":"Configure the building blocks scheduling needs before you can build or auto-fill a schedule.","body_markdown":"Configure the building blocks scheduling needs before you can build or auto-fill a schedule.\n\n## Steps\n\n1. Go to Schedule and click Shifts, Units & Patterns.\n\n2. Select the facility you're configuring.\n\n3. Under Units & Wings, add each unit or wing employees can be scheduled to.\n\n4. Under Shift Types, add the typical shift time templates your facility uses (for example, Day, Evening, Night).\n\n5. Under Typical Patterns, set each employee's usual recurring shift and unit by day of week.\n\n6. Save -- this setup is what Auto-Fill draws from when building a new schedule.\n\n## Tips\n\n- Do this once per facility; you won't need to repeat it unless shift times or an employee's typical pattern changes.\n\nRelated CareBase page: **Go to Shifts, Units & Patterns** (/app/schedule/setup)","body_text":"Configure the building blocks scheduling needs before you can build or auto-fill a schedule.\nGo to Schedule and click Shifts, Units & Patterns.\nSelect the facility you're configuring.\nUnder Units & Wings, add each unit or wing employees can be scheduled to.\nUnder Shift Types, add the typical shift time templates your facility uses (for example, Day, Evening, Night).\nUnder Typical Patterns, set each employee's usual recurring shift and unit by day of week.\nSave -- this setup is what Auto-Fill draws from when building a new schedule.\nDo this once per facility; you won't need to repeat it unless shift times or an employee's typical pattern changes.","source_audience":["org_admin","facility_manager"],"route_pattern":"/app/schedule/setup","sort_order":11,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"83a988f7-15a2-426d-891b-58246369c0b7","content_key":"penntrain.help.faq.83a988f7-15a2-426d-891b-58246369c0b7","article_type":"faq","category":"Courses & Quizzes","title":"What's the difference between a Training Plan and a single Course Assignment?","summary":"A Course Assignment is one course given to one employee. A Training Plan is a reusable bundle of courses and/or training-type requirements -- build it once (say, a New Hire Onboarding plan), then apply it to any employee to create every course assignment in the bundle and start tracking every non-course requirement as pending, all in one action instead of assigning each piece separately.","body_markdown":"A Course Assignment is one course given to one employee. A Training Plan is a reusable bundle of courses and/or training-type requirements -- build it once (say, a New Hire Onboarding plan), then apply it to any employee to create every course assignment in the bundle and start tracking every non-course requirement as pending, all in one action instead of assigning each piece separately.","body_text":"A Course Assignment is one course given to one employee. A Training Plan is a reusable bundle of courses and/or training-type requirements -- build it once (say, a New Hire Onboarding plan), then apply it to any employee to create every course assignment in the bundle and start tracking every non-course requirement as pending, all in one action instead of assigning each piece separately.","source_audience":[],"route_pattern":null,"sort_order":11,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"d93c8cff-6269-42a5-bf98-0bd9ac20df76","content_key":"penntrain.help.job-aide.d93c8cff-6269-42a5-bf98-0bd9ac20df76","article_type":"job_aide","category":"Scheduling","title":"Build and Publish a Weekly Schedule","summary":"Create a draft schedule, auto-fill it, make manual adjustments, then publish it so employees can see it.","body_markdown":"Create a draft schedule, auto-fill it, make manual adjustments, then publish it so employees can see it.\n\n## Steps\n\n1. Go to Schedule and click New Schedule.\n\n2. Select the facility, a start date, and a 7- or 14-day period length, then create it.\n\n3. On the schedule's detail page, click Auto-Fill from Typical Patterns to populate shifts from each employee's saved pattern.\n\n4. Make any manual edits needed -- manual entries are never overwritten by auto-fill, and Clear Auto-Fill only removes untouched auto-generated rows if you need to start over.\n\n5. Click Publish once the schedule is final.\n\n6. Use Move to Draft if you need to make further changes after publishing -- employees stop seeing it under My Schedule until it's published again.\n\n## Tips\n\n- An employee is capped at one shift per calendar date across every facility, so there's no accidental double-booking.\n\nRelated CareBase page: **Go to Schedule** (/app/schedule)","body_text":"Create a draft schedule, auto-fill it, make manual adjustments, then publish it so employees can see it.\nGo to Schedule and click New Schedule.\nSelect the facility, a start date, and a 7- or 14-day period length, then create it.\nOn the schedule's detail page, click Auto-Fill from Typical Patterns to populate shifts from each employee's saved pattern.\nMake any manual edits needed -- manual entries are never overwritten by auto-fill, and Clear Auto-Fill only removes untouched auto-generated rows if you need to start over.\nClick Publish once the schedule is final.\nUse Move to Draft if you need to make further changes after publishing -- employees stop seeing it under My Schedule until it's published again.\nAn employee is capped at one shift per calendar date across every facility, so there's no accidental double-booking.","source_audience":["org_admin","facility_manager"],"route_pattern":"/app/schedule","sort_order":12,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"ec477d73-8619-457a-b64c-038c4967a006","content_key":"penntrain.help.faq.ec477d73-8619-457a-b64c-038c4967a006","article_type":"faq","category":"Courses & Quizzes","title":"Do employees need to install anything to take courses?","summary":"No. Employees sign in at /me/courses in any browser, open an assigned course, work through its lessons and any attached video or documents, take the quiz if there is one, and download their certificate afterward -- no app install, and no separate training vendor.","body_markdown":"No. Employees sign in at /me/courses in any browser, open an assigned course, work through its lessons and any attached video or documents, take the quiz if there is one, and download their certificate afterward -- no app install, and no separate training vendor.","body_text":"No. Employees sign in at /me/courses in any browser, open an assigned course, work through its lessons and any attached video or documents, take the quiz if there is one, and download their certificate afterward -- no app install, and no separate training vendor.","source_audience":[],"route_pattern":null,"sort_order":12,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"d91e8313-c52c-4cbd-ba8c-eb256e1dbf4e","content_key":"penntrain.help.faq.d91e8313-c52c-4cbd-ba8c-eb256e1dbf4e","article_type":"faq","category":"Scheduling","title":"How does shift scheduling work in CareMetric Train?","summary":"Scheduling is basic shift scheduling, not tied to compliance qualification checks. First set up each facility's units (wings), typical shift times, and each employee's usual recurring pattern by day of week under Shifts, Units & Patterns. Then create a Schedule for a period (7 or 14 days), and either build it by hand or use Auto-Fill to populate it from everyone's typical pattern.","body_markdown":"Scheduling is basic shift scheduling, not tied to compliance qualification checks. First set up each facility's units (wings), typical shift times, and each employee's usual recurring pattern by day of week under Shifts, Units & Patterns. Then create a Schedule for a period (7 or 14 days), and either build it by hand or use Auto-Fill to populate it from everyone's typical pattern.","body_text":"Scheduling is basic shift scheduling, not tied to compliance qualification checks. First set up each facility's units (wings), typical shift times, and each employee's usual recurring pattern by day of week under Shifts, Units & Patterns. Then create a Schedule for a period (7 or 14 days), and either build it by hand or use Auto-Fill to populate it from everyone's typical pattern.","source_audience":[],"route_pattern":null,"sort_order":13,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"cf6ddb6b-b0ed-4289-bddd-db1e728ad77c","content_key":"penntrain.help.job-aide.cf6ddb6b-b0ed-4289-bddd-db1e728ad77c","article_type":"job_aide","category":"Scheduling","title":"View Your Published Shifts","summary":"Check your upcoming work schedule once it's been published.","body_markdown":"Check your upcoming work schedule once it's been published.\n\n## Steps\n\n1. Go to My Schedule.\n\n2. Review your upcoming published shifts by date and facility.\n\n3. Contact your facility manager if a shift looks wrong -- shifts are managed centrally and aren't self-editable.\n\n## Tips\n\n- Only published schedules appear here; a schedule still in draft won't show up even if it already has shifts entered.\n\nRelated CareBase page: **Go to My Schedule** (/me/schedule)","body_text":"Check your upcoming work schedule once it's been published.\nGo to My Schedule.\nReview your upcoming published shifts by date and facility.\nContact your facility manager if a shift looks wrong -- shifts are managed centrally and aren't self-editable.\nOnly published schedules appear here; a schedule still in draft won't show up even if it already has shifts entered.","source_audience":["employee"],"route_pattern":"/me/schedule","sort_order":13,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"cc6c0409-975c-4f50-8d8b-09ae5bbddb73","content_key":"penntrain.help.job-aide.cc6c0409-975c-4f50-8d8b-09ae5bbddb73","article_type":"job_aide","category":"Compliance Tracking","title":"Set Up a Competency Template","summary":"Build a reusable checklist that evaluators fill out to verify an employee's hands-on competency.","body_markdown":"Build a reusable checklist that evaluators fill out to verify an employee's hands-on competency.\n\n## Steps\n\n1. Go to Competency Templates and click New Template.\n\n2. Name the template (for example, Medication Administration Competency) and add a description of what it verifies and when to use it.\n\n3. Click Items on the new template to open its checklist.\n\n4. Add each checklist item as a short, observable statement (for example, \"Washes hands before administering medication\").\n\n5. Reorder items with the up/down arrows if sequence matters, then close.\n\n## Tips\n\n- A template can't be deleted while any completed competency record still references it -- those records stay auditable.\n\nRelated CareBase page: **Go to Competency Templates** (/app/competency-templates)","body_text":"Build a reusable checklist that evaluators fill out to verify an employee's hands-on competency.\nGo to Competency Templates and click New Template.\nName the template (for example, Medication Administration Competency) and add a description of what it verifies and when to use it.\nClick Items on the new template to open its checklist.\nAdd each checklist item as a short, observable statement (for example, \"Washes hands before administering medication\").\nReorder items with the up/down arrows if sequence matters, then close.\nA template can't be deleted while any completed competency record still references it -- those records stay auditable.","source_audience":["org_admin","trainer"],"route_pattern":"/app/competency-templates","sort_order":14,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"ade5651e-712a-498c-a3ee-c98abf0781fd","content_key":"penntrain.help.faq.ade5651e-712a-498c-a3ee-c98abf0781fd","article_type":"faq","category":"Scheduling","title":"What does \"Auto-Fill from Typical Patterns\" actually do?","summary":"It populates a draft schedule using every employee's saved recurring shift/unit pattern, skipping any date where that employee already has a shift entered manually -- manual entries always win. If it created something wrong, Clear Auto-Fill removes only the untouched auto-generated rows, leaving any manual edits you've made in place.","body_markdown":"It populates a draft schedule using every employee's saved recurring shift/unit pattern, skipping any date where that employee already has a shift entered manually -- manual entries always win. If it created something wrong, Clear Auto-Fill removes only the untouched auto-generated rows, leaving any manual edits you've made in place.","body_text":"It populates a draft schedule using every employee's saved recurring shift/unit pattern, skipping any date where that employee already has a shift entered manually -- manual entries always win. If it created something wrong, Clear Auto-Fill removes only the untouched auto-generated rows, leaving any manual edits you've made in place.","source_audience":[],"route_pattern":null,"sort_order":14,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"55a7b0bb-36ed-49b5-a4a8-89b9aeb63537","content_key":"penntrain.help.job-aide.55a7b0bb-36ed-49b5-a4a8-89b9aeb63537","article_type":"job_aide","category":"Compliance Tracking","title":"Record a Competency Evaluation","summary":"Document that an evaluator observed an employee against a competency checklist and the result.","body_markdown":"Document that an evaluator observed an employee against a competency checklist and the result.\n\n## Steps\n\n1. Go to Competency Records and click New Record.\n\n2. Select the employee, the competency template, and the evaluation date.\n\n3. Go through each checklist item and mark it met, not met, or not applicable.\n\n4. Set the overall result -- met, not met, or partial.\n\n5. Save and, if required by your facility's process, capture the evaluator's signature.\n\n## Tips\n\n- Use Who Can Pass Meds Today to see the combined effect of certification plus practicum plus competency status for medication-administering staff.\n\nRelated CareBase page: **Go to Competency Records** (/app/competency-records)","body_text":"Document that an evaluator observed an employee against a competency checklist and the result.\nGo to Competency Records and click New Record.\nSelect the employee, the competency template, and the evaluation date.\nGo through each checklist item and mark it met, not met, or not applicable.\nSet the overall result -- met, not met, or partial.\nSave and, if required by your facility's process, capture the evaluator's signature.\nUse Who Can Pass Meds Today to see the combined effect of certification plus practicum plus competency status for medication-administering staff.","source_audience":["org_admin","facility_manager","trainer"],"route_pattern":"/app/competency-records","sort_order":15,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"de06e3fd-dde3-4dd6-bd2d-c86eafddf210","content_key":"penntrain.help.faq.de06e3fd-dde3-4dd6-bd2d-c86eafddf210","article_type":"faq","category":"Scheduling","title":"Why can't my employee see their shifts under My Schedule?","summary":"Employees can only see shifts on a schedule that's been Published. A draft schedule -- even one that's fully auto-filled -- stays invisible to employees until you publish it from Schedule Detail; move it back to draft any time you need to bulk-edit or re-run Auto-Fill.","body_markdown":"Employees can only see shifts on a schedule that's been Published. A draft schedule -- even one that's fully auto-filled -- stays invisible to employees until you publish it from Schedule Detail; move it back to draft any time you need to bulk-edit or re-run Auto-Fill.","body_text":"Employees can only see shifts on a schedule that's been Published. A draft schedule -- even one that's fully auto-filled -- stays invisible to employees until you publish it from Schedule Detail; move it back to draft any time you need to bulk-edit or re-run Auto-Fill.","source_audience":[],"route_pattern":null,"sort_order":15,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"891c6bf0-5a4d-4939-bf38-38dc8005e04e","content_key":"penntrain.help.faq.891c6bf0-5a4d-4939-bf38-38dc8005e04e","article_type":"faq","category":"Scheduling","title":"Can one employee be scheduled at two facilities on the same day?","summary":"Not currently -- an employee is capped at one shift per calendar date across every facility they're assigned to, so there's no double-booking and no same-day float between two locations. An employee can still be assigned to work at more than one facility over time, just not on the same date.","body_markdown":"Not currently -- an employee is capped at one shift per calendar date across every facility they're assigned to, so there's no double-booking and no same-day float between two locations. An employee can still be assigned to work at more than one facility over time, just not on the same date.","body_text":"Not currently -- an employee is capped at one shift per calendar date across every facility they're assigned to, so there's no double-booking and no same-day float between two locations. An employee can still be assigned to work at more than one facility over time, just not on the same date.","source_audience":[],"route_pattern":null,"sort_order":16,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"de1d2ebe-1232-41b8-9d22-a6bea9e8c876","content_key":"penntrain.help.job-aide.de1d2ebe-1232-41b8-9d22-a6bea9e8c876","article_type":"job_aide","category":"Compliance Tracking","title":"Log an Annual Medication Administration Practicum","summary":"Record a medication-administering employee's annual hands-on practicum so their authorization stays current.","body_markdown":"Record a medication-administering employee's annual hands-on practicum so their authorization stays current.\n\n## Steps\n\n1. Go to Practicums.\n\n2. Click Add Practicum (or edit an existing one for the current year) and select the employee and practicum year.\n\n3. Enter the completion date and who observed it, plus the due date and reminder window for the next one.\n\n4. Record any additional observation windows or MAR-review checkpoints your facility's process requires.\n\n5. Save -- the practicum's status (compliant, due soon, expired, or missing) recalculates from the due date and reminder window automatically.\n\n## Tips\n\n- Practicum status is driven purely by the due date and reminder window you enter here -- it isn't automatically derived from the completion date.\n\nRelated CareBase page: **Go to Practicums** (/app/practicums)","body_text":"Record a medication-administering employee's annual hands-on practicum so their authorization stays current.\nGo to Practicums.\nClick Add Practicum (or edit an existing one for the current year) and select the employee and practicum year.\nEnter the completion date and who observed it, plus the due date and reminder window for the next one.\nRecord any additional observation windows or MAR-review checkpoints your facility's process requires.\nSave -- the practicum's status (compliant, due soon, expired, or missing) recalculates from the due date and reminder window automatically.\nPracticum status is driven purely by the due date and reminder window you enter here -- it isn't automatically derived from the completion date.","source_audience":["org_admin","facility_manager","trainer"],"route_pattern":"/app/practicums","sort_order":16,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"4c50e9e3-6a36-4684-97a1-e0954faabeec","content_key":"penntrain.help.job-aide.4c50e9e3-6a36-4684-97a1-e0954faabeec","article_type":"job_aide","category":"Compliance Tracking","title":"Check Who Can Pass Meds Today","summary":"See a live, combined view of medication-administration authorization across your staff.","body_markdown":"See a live, combined view of medication-administration authorization across your staff.\n\n## Steps\n\n1. Go to Who Can Pass Meds Today.\n\n2. Optionally filter to a single facility.\n\n3. Review each medication-administering employee's certification status, current-year practicum status, and insulin/diabetes-education authorization side by side.\n\n4. Check the Authorized Today column for the combined answer -- it only reads Yes if both certification and practicum are currently valid (compliant or due soon).\n\n## Tips\n\n- Only employees with Administers Medications checked on their employee record appear on this roster -- if someone's missing, check that flag first.\n\nRelated CareBase page: **Go to Who Can Pass Meds Today** (/app/med-admin-roster)","body_text":"See a live, combined view of medication-administration authorization across your staff.\nGo to Who Can Pass Meds Today.\nOptionally filter to a single facility.\nReview each medication-administering employee's certification status, current-year practicum status, and insulin/diabetes-education authorization side by side.\nCheck the Authorized Today column for the combined answer -- it only reads Yes if both certification and practicum are currently valid (compliant or due soon).\nOnly employees with Administers Medications checked on their employee record appear on this roster -- if someone's missing, check that flag first.","source_audience":["org_admin","facility_manager","trainer"],"route_pattern":"/app/med-admin-roster","sort_order":17,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"ac688afd-1625-468c-bf26-83f14ae53315","content_key":"penntrain.help.faq.ac688afd-1625-468c-bf26-83f14ae53315","article_type":"faq","category":"Compliance & Alerts","title":"What triggers a compliance alert?","summary":"Alerts fire for the events that put you at survey risk: training due soon or expired, missing documents, expiring certificates or credentials, practicums due soon or expired, a reported incident, a policy attestation due soon, and (for personal care homes/assisted living) resident compliance items coming due. Each alert carries a severity -- critical, warning, or info -- so you can triage what needs attention first.","body_markdown":"Alerts fire for the events that put you at survey risk: training due soon or expired, missing documents, expiring certificates or credentials, practicums due soon or expired, a reported incident, a policy attestation due soon, and (for personal care homes/assisted living) resident compliance items coming due. Each alert carries a severity -- critical, warning, or info -- so you can triage what needs attention first.","body_text":"Alerts fire for the events that put you at survey risk: training due soon or expired, missing documents, expiring certificates or credentials, practicums due soon or expired, a reported incident, a policy attestation due soon, and (for personal care homes/assisted living) resident compliance items coming due. Each alert carries a severity -- critical, warning, or info -- so you can triage what needs attention first.","source_audience":[],"route_pattern":null,"sort_order":17,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"c91b41a1-5075-427f-bf38-6cf30d14e0ab","content_key":"penntrain.help.job-aide.c91b41a1-5075-427f-bf38-6cf30d14e0ab","article_type":"job_aide","category":"Compliance Tracking","title":"File an Incident or Complaint","summary":"Log a reportable event, track required notifications, and manage its investigation through to a final report.","body_markdown":"Log a reportable event, track required notifications, and manage its investigation through to a final report.\n\n## Steps\n\n1. Go to Incidents & Complaints and click New Incident.\n\n2. Select the incident type (for example, medication error, significant injury, elopement, abuse allegation) and severity.\n\n3. Enter the facility, date/time, location detail, and resident identifier if applicable.\n\n4. Save, then open the incident's detail page to add the narrative, staff involved, and any required notifications (state hotline, family/guardian, law enforcement, licensing agency).\n\n5. Add corrective actions as they're identified and upload supporting documents.\n\n6. Generate the final report once the investigation is complete.\n\n## Tips\n\n- This module is intentionally restricted to org_admin and facility_manager -- trainer and self-service employee access are both excluded given the sensitivity of incident data.\n\nRelated CareBase page: **Go to Incidents & Complaints** (/app/incidents)","body_text":"Log a reportable event, track required notifications, and manage its investigation through to a final report.\nGo to Incidents & Complaints and click New Incident.\nSelect the incident type (for example, medication error, significant injury, elopement, abuse allegation) and severity.\nEnter the facility, date/time, location detail, and resident identifier if applicable.\nSave, then open the incident's detail page to add the narrative, staff involved, and any required notifications (state hotline, family/guardian, law enforcement, licensing agency).\nAdd corrective actions as they're identified and upload supporting documents.\nGenerate the final report once the investigation is complete.\nThis module is intentionally restricted to org_admin and facility_manager -- trainer and self-service employee access are both excluded given the sensitivity of incident data.","source_audience":["org_admin","facility_manager"],"route_pattern":"/app/incidents","sort_order":18,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"6d1c622e-8ecb-4474-9349-b0af9b78f2d9","content_key":"penntrain.help.faq.6d1c622e-8ecb-4474-9349-b0af9b78f2d9","article_type":"faq","category":"Compliance & Alerts","title":"What's the difference between \"due soon\" and \"expired\" everywhere in the app?","summary":"Due soon means the requirement is still valid today but falls inside its warning window before the deadline -- it still counts as currently compliant everywhere that matters, like medication-administration authorization. Expired means the deadline has already passed. The warning window's default lead time is configurable per organization in Settings.","body_markdown":"Due soon means the requirement is still valid today but falls inside its warning window before the deadline -- it still counts as currently compliant everywhere that matters, like medication-administration authorization. Expired means the deadline has already passed. The warning window's default lead time is configurable per organization in Settings.","body_text":"Due soon means the requirement is still valid today but falls inside its warning window before the deadline -- it still counts as currently compliant everywhere that matters, like medication-administration authorization. Expired means the deadline has already passed. The warning window's default lead time is configurable per organization in Settings.","source_audience":[],"route_pattern":null,"sort_order":18,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"9225aa24-8a83-4ef9-936b-e995df244338","content_key":"penntrain.help.job-aide.9225aa24-8a83-4ef9-936b-e995df244338","article_type":"job_aide","category":"Compliance Tracking","title":"Track a Cited DHS Violation Through Its Plan of Correction","summary":"Enter a citation from a DHS inspection and manage its Plan of Correction through to verification.","body_markdown":"Enter a citation from a DHS inspection and manage its Plan of Correction through to verification.\n\n## Steps\n\n1. Go to Violations & Plans of Correction and click New Violation.\n\n2. Select the facility, citation topic, and severity, and enter the citation reference and description.\n\n3. Set the Plan of Correction due date.\n\n4. Open the violation's detail page to add corrective actions with owners and due dates as they're worked.\n\n5. Upload supporting documents -- photos, corrected policies, retraining records -- supporting each corrective action.\n\n6. Move the status forward from open, to POC submitted, to corrected, to verified as the correction is confirmed.\n\n## Tips\n\n- Like Incidents, this module is org_admin/facility_manager only -- a cited violation and its POC are treated as an org-compliance matter, not a trainer- or self-service-facing one.\n\nRelated CareBase page: **Go to Violations** (/app/violations)","body_text":"Enter a citation from a DHS inspection and manage its Plan of Correction through to verification.\nGo to Violations & Plans of Correction and click New Violation.\nSelect the facility, citation topic, and severity, and enter the citation reference and description.\nSet the Plan of Correction due date.\nOpen the violation's detail page to add corrective actions with owners and due dates as they're worked.\nUpload supporting documents -- photos, corrected policies, retraining records -- supporting each corrective action.\nMove the status forward from open, to POC submitted, to corrected, to verified as the correction is confirmed.\nLike Incidents, this module is org_admin/facility_manager only -- a cited violation and its POC are treated as an org-compliance matter, not a trainer- or self-service-facing one.","source_audience":["org_admin","facility_manager"],"route_pattern":"/app/violations","sort_order":19,"updated_at":"2026-07-23 08:46:29.818663+00"},{"id":"3b3faf17-49aa-43f4-8edc-837ff0eb2830","content_key":"penntrain.help.faq.3b3faf17-49aa-43f4-8edc-837ff0eb2830","article_type":"faq","category":"Compliance & Alerts","title":"Who can dismiss or resolve an alert, and does that change the underlying record?","summary":"Alerts have their own status -- open, dismissed, or resolved -- separate from the training record, credential, or practicum that generated them. Dismissing or resolving an alert just clears it from your open queue; it doesn't retroactively mark the underlying requirement as complete. If the requirement itself is still outstanding, a fresh alert can be generated again.","body_markdown":"Alerts have their own status -- open, dismissed, or resolved -- separate from the training record, credential, or practicum that generated them. Dismissing or resolving an alert just clears it from your open queue; it doesn't retroactively mark the underlying requirement as complete. If the requirement itself is still outstanding, a fresh alert can be generated again.","body_text":"Alerts have their own status -- open, dismissed, or resolved -- separate from the training record, credential, or practicum that generated them. Dismissing or resolving an alert just clears it from your open queue; it doesn't retroactively mark the underlying requirement as complete. If the requirement itself is still outstanding, a fresh alert can be generated again.","source_audience":[],"route_pattern":null,"sort_order":19,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"a06f04fc-5660-440f-9105-35a56da31e0d","content_key":"penntrain.help.job-aide.a06f04fc-5660-440f-9105-35a56da31e0d","article_type":"job_aide","category":"Compliance Tracking","title":"Add a Resident and Track RASP/ASP Deadlines","summary":"Track a personal care home or assisted living resident's assessment and support-plan compliance deadlines.","body_markdown":"Track a personal care home or assisted living resident's assessment and support-plan compliance deadlines.\n\n## Steps\n\n1. Go to Residents and click Add Resident.\n\n2. Enter admission date, room, and basic demographics.\n\n3. Open the resident's detail page to add contacts and supports (physician, dentist, case manager, designated person).\n\n4. Complete the compliance checklist and any digital assessment forms your facility uses (RASP/ASP).\n\n5. Upload supporting documents -- completed DHS forms, DME documentation -- to the resident's Documents section.\n\n6. Use Resident Compliance to see upcoming deadlines across every resident at a glance.\n\n## Tips\n\n- This module tracks compliance deadlines only -- no charting or care-plan data is stored here.\n\nRelated CareBase page: **Go to Residents** (/app/residents)","body_text":"Track a personal care home or assisted living resident's assessment and support-plan compliance deadlines.\nGo to Residents and click Add Resident.\nEnter admission date, room, and basic demographics.\nOpen the resident's detail page to add contacts and supports (physician, dentist, case manager, designated person).\nComplete the compliance checklist and any digital assessment forms your facility uses (RASP/ASP).\nUpload supporting documents -- completed DHS forms, DME documentation -- to the resident's Documents section.\nUse Resident Compliance to see upcoming deadlines across every resident at a glance.\nThis module tracks compliance deadlines only -- no charting or care-plan data is stored here.","source_audience":["org_admin","facility_manager"],"route_pattern":"/app/residents","sort_order":20,"updated_at":"2026-07-23 08:46:29.818663+00"},{"id":"79f8727a-8e38-4fb2-8369-e3a504d7ab25","content_key":"penntrain.help.faq.79f8727a-8e38-4fb2-8369-e3a504d7ab25","article_type":"faq","category":"Compliance & Alerts","title":"How do I get a quick read on whether my facility is survey-ready right now?","summary":"Inspection Readiness gives you a citation-weighted readiness score per facility plus a mock entrance-conference checklist that pulls live from your training, credential, background-check, inspection, incident, and policy-attestation data. It's modeled on general DHS entrance-conference practice, not a verbatim reproduction of the current DHS guide, so keep your own copy on hand to compare exact wording before a real inspection.","body_markdown":"Inspection Readiness gives you a citation-weighted readiness score per facility plus a mock entrance-conference checklist that pulls live from your training, credential, background-check, inspection, incident, and policy-attestation data. It's modeled on general DHS entrance-conference practice, not a verbatim reproduction of the current DHS guide, so keep your own copy on hand to compare exact wording before a real inspection.","body_text":"Inspection Readiness gives you a citation-weighted readiness score per facility plus a mock entrance-conference checklist that pulls live from your training, credential, background-check, inspection, incident, and policy-attestation data. It's modeled on general DHS entrance-conference practice, not a verbatim reproduction of the current DHS guide, so keep your own copy on hand to compare exact wording before a real inspection.","source_audience":[],"route_pattern":null,"sort_order":20,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"585b0640-1bb6-4fce-9812-2b5d2fbc5b19","content_key":"penntrain.help.job-aide.585b0640-1bb6-4fce-9812-2b5d2fbc5b19","article_type":"job_aide","category":"Compliance Tracking","title":"Run the Inspection Readiness Score & Build an Entrance Packet","summary":"Get a live, citation-weighted readiness score per facility and a one-click entrance-conference packet.","body_markdown":"Get a live, citation-weighted readiness score per facility and a one-click entrance-conference packet.\n\n## Steps\n\n1. Go to Inspection Readiness and select a facility.\n\n2. Review the citation-weighted readiness score and the topic-by-topic breakdown, sorted worst-performing first.\n\n3. Work through the Mock Entrance Conference Checklist, which flags each area as Ready or Attention Needed based on your live data.\n\n4. Click Generate Entrance Packet to produce a one-click PDF covering facilities, staff training, credentials, incidents, and inspection items.\n\n5. Download the packet before its short-lived link expires; generate a fresh one any time.\n\n## Tips\n\n- The checklist is modeled on general DHS entrance-conference practice, not a verbatim copy of the current DHS guide -- keep your own reference copy handy to compare exact wording.\n\nRelated CareBase page: **Go to Inspection Readiness** (/app/inspection-readiness)","body_text":"Get a live, citation-weighted readiness score per facility and a one-click entrance-conference packet.\nGo to Inspection Readiness and select a facility.\nReview the citation-weighted readiness score and the topic-by-topic breakdown, sorted worst-performing first.\nWork through the Mock Entrance Conference Checklist, which flags each area as Ready or Attention Needed based on your live data.\nClick Generate Entrance Packet to produce a one-click PDF covering facilities, staff training, credentials, incidents, and inspection items.\nDownload the packet before its short-lived link expires; generate a fresh one any time.\nThe checklist is modeled on general DHS entrance-conference practice, not a verbatim copy of the current DHS guide -- keep your own reference copy handy to compare exact wording.","source_audience":["org_admin","facility_manager","auditor"],"route_pattern":"/app/inspection-readiness","sort_order":21,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"16480712-6f45-41e4-bad6-457652cc122d","content_key":"penntrain.help.faq.16480712-6f45-41e4-bad6-457652cc122d","article_type":"faq","category":"Documents & Policies","title":"What's the difference between Documents and Policy Documents?","summary":"Documents is where you upload and manage individual files -- certificates, training rosters, practicum forms, transcripts, and competency attachments -- tied to a specific employee or facility. Policy Documents is a separate module for versioned organizational policies (like a Resident Rights Policy) with formal, ESIGN/UETA-compliant attestation campaigns that track who has read and signed off on each version.","body_markdown":"Documents is where you upload and manage individual files -- certificates, training rosters, practicum forms, transcripts, and competency attachments -- tied to a specific employee or facility. Policy Documents is a separate module for versioned organizational policies (like a Resident Rights Policy) with formal, ESIGN/UETA-compliant attestation campaigns that track who has read and signed off on each version.","body_text":"Documents is where you upload and manage individual files -- certificates, training rosters, practicum forms, transcripts, and competency attachments -- tied to a specific employee or facility. Policy Documents is a separate module for versioned organizational policies (like a Resident Rights Policy) with formal, ESIGN/UETA-compliant attestation campaigns that track who has read and signed off on each version.","source_audience":[],"route_pattern":null,"sort_order":21,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"1210ad9e-211d-4290-a120-bacf94e5127f","content_key":"penntrain.help.faq.1210ad9e-211d-4290-a120-bacf94e5127f","article_type":"faq","category":"Documents & Policies","title":"How does policy attestation work?","summary":"Create the policy document, upload and publish a version, then launch an attestation campaign against it -- that assigns the requirement to the roster you target and tracks each person's signature with a due date. Anyone assigned an attestation sees it under My Attestations and signs off there; overdue attestations show up as alerts and on the Inspection Readiness checklist.","body_markdown":"Create the policy document, upload and publish a version, then launch an attestation campaign against it -- that assigns the requirement to the roster you target and tracks each person's signature with a due date. Anyone assigned an attestation sees it under My Attestations and signs off there; overdue attestations show up as alerts and on the Inspection Readiness checklist.","body_text":"Create the policy document, upload and publish a version, then launch an attestation campaign against it -- that assigns the requirement to the roster you target and tracks each person's signature with a due date. Anyone assigned an attestation sees it under My Attestations and signs off there; overdue attestations show up as alerts and on the Inspection Readiness checklist.","source_audience":[],"route_pattern":null,"sort_order":22,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"97f25725-6b44-487c-87af-17adfc59b075","content_key":"penntrain.help.job-aide.97f25725-6b44-487c-87af-17adfc59b075","article_type":"job_aide","category":"Compliance Tracking","title":"Upload a Credential Document for an Employee","summary":"Attach the supporting document for a background clearance, license, or health screening.","body_markdown":"Attach the supporting document for a background clearance, license, or health screening.\n\n## Steps\n\n1. Go to Credentials & Clearances.\n\n2. Find or add the employee's credential entry (for example, Act 34 Criminal History Clearance, RN License, TB Screening).\n\n3. Enter the issue and expiration dates.\n\n4. Upload the supporting document to the credential record.\n\n5. Save -- expiration status recalculates automatically overnight; set it manually only if you need to override the calculated value.\n\n## Tips\n\n- This page is limited to org_admin, facility_manager, and auditor -- trainer doesn't have access, since clearance data is treated as more sensitive than ordinary training records.\n\nRelated CareBase page: **Go to Credentials & Clearances** (/app/credentials)","body_text":"Attach the supporting document for a background clearance, license, or health screening.\nGo to Credentials & Clearances.\nFind or add the employee's credential entry (for example, Act 34 Criminal History Clearance, RN License, TB Screening).\nEnter the issue and expiration dates.\nUpload the supporting document to the credential record.\nSave -- expiration status recalculates automatically overnight; set it manually only if you need to override the calculated value.\nThis page is limited to org_admin, facility_manager, and auditor -- trainer doesn't have access, since clearance data is treated as more sensitive than ordinary training records.","source_audience":["org_admin","facility_manager"],"route_pattern":"/app/credentials","sort_order":22,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"6125b915-c042-48ea-b919-d19278b25711","content_key":"penntrain.help.faq.6125b915-c042-48ea-b919-d19278b25711","article_type":"faq","category":"Documents & Policies","title":"How securely are uploaded documents stored?","summary":"Every document lives in private Supabase Storage, split across separate buckets by type (external uploads, sign-in sheets, competency attachments, and more), and is only ever retrieved through a short-lived signed link -- there's no public URL for any of it. Deleting an uploaded training document is restricted to org_admin and facility_manager; even the employee who uploaded it can't delete it themselves.","body_markdown":"Every document lives in private Supabase Storage, split across separate buckets by type (external uploads, sign-in sheets, competency attachments, and more), and is only ever retrieved through a short-lived signed link -- there's no public URL for any of it. Deleting an uploaded training document is restricted to org_admin and facility_manager; even the employee who uploaded it can't delete it themselves.","body_text":"Every document lives in private Supabase Storage, split across separate buckets by type (external uploads, sign-in sheets, competency attachments, and more), and is only ever retrieved through a short-lived signed link -- there's no public URL for any of it. Deleting an uploaded training document is restricted to org_admin and facility_manager; even the employee who uploaded it can't delete it themselves.","source_audience":[],"route_pattern":null,"sort_order":23,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"6271df84-ce17-44b0-a4aa-099c58405a8f","content_key":"penntrain.help.job-aide.6271df84-ce17-44b0-a4aa-099c58405a8f","article_type":"job_aide","category":"Documents & Policies","title":"Publish a Policy Document and Run an Attestation Campaign","summary":"Roll out a versioned policy and formally track who has read and signed off on it.","body_markdown":"Roll out a versioned policy and formally track who has read and signed off on it.\n\n## Steps\n\n1. Go to Policies & Procedures and click New Policy Document.\n\n2. Enter a title, category, and description, then create it.\n\n3. Open the new policy document and upload a version, then publish it.\n\n4. Click Campaigns and start a new attestation campaign against the published version, targeting the roster it applies to and setting a due date.\n\n5. Monitor completion as employees sign off from their own My Attestations page.\n\n## Tips\n\n- Attestation campaigns are ESIGN/UETA-compliant -- each signature is tied to the specific published version the employee actually attested to.\n\nRelated CareBase page: **Go to Policies & Procedures** (/app/policy-documents)","body_text":"Roll out a versioned policy and formally track who has read and signed off on it.\nGo to Policies & Procedures and click New Policy Document.\nEnter a title, category, and description, then create it.\nOpen the new policy document and upload a version, then publish it.\nClick Campaigns and start a new attestation campaign against the published version, targeting the roster it applies to and setting a due date.\nMonitor completion as employees sign off from their own My Attestations page.\nAttestation campaigns are ESIGN/UETA-compliant -- each signature is tied to the specific published version the employee actually attested to.","source_audience":["org_admin","facility_manager"],"route_pattern":"/app/policy-documents","sort_order":23,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"0c756b58-6b6b-469f-bd01-012fea87afa4","content_key":"penntrain.help.faq.0c756b58-6b6b-469f-bd01-012fea87afa4","article_type":"faq","category":"Documents & Policies","title":"Can employees upload their own documents, like an external certificate?","summary":"Yes -- employees can upload documents such as an external certificate for training they completed outside the platform. It doesn't automatically count toward compliance, though: it lands in Pending Approvals, where an org admin, facility manager, or trainer reviews it and confirms (or declines) whether it satisfies a training requirement before it affects that employee's compliance status.","body_markdown":"Yes -- employees can upload documents such as an external certificate for training they completed outside the platform. It doesn't automatically count toward compliance, though: it lands in Pending Approvals, where an org admin, facility manager, or trainer reviews it and confirms (or declines) whether it satisfies a training requirement before it affects that employee's compliance status.","body_text":"Yes -- employees can upload documents such as an external certificate for training they completed outside the platform. It doesn't automatically count toward compliance, though: it lands in Pending Approvals, where an org admin, facility manager, or trainer reviews it and confirms (or declines) whether it satisfies a training requirement before it affects that employee's compliance status.","source_audience":[],"route_pattern":null,"sort_order":24,"updated_at":"2026-07-12 17:15:35.356395+00"},{"id":"69ccb165-1fad-4a2c-8ce2-a093e19dbce7","content_key":"penntrain.help.job-aide.69ccb165-1fad-4a2c-8ce2-a093e19dbce7","article_type":"job_aide","category":"Documents & Policies","title":"Upload a Training Document or Certificate","summary":"Attach a certificate, roster, practicum form, transcript, or other supporting file to an employee or facility.","body_markdown":"Attach a certificate, roster, practicum form, transcript, or other supporting file to an employee or facility.\n\n## Steps\n\n1. Go to Documents and click Upload.\n\n2. Select the facility and, if applicable, the specific employee this document belongs to.\n\n3. Choose the document type -- certificate, roster, practicum form, transcript, external certificate, competency attachment, or other.\n\n4. Select the file and upload it.\n\n5. Verify it appears in the list, filtered by facility, employee, or document type as needed.\n\n## Tips\n\n- Only org_admin and facility_manager can delete an uploaded document -- not even the employee who uploaded it can remove it themselves.\n\nRelated CareBase page: **Go to Documents** (/app/documents)","body_text":"Attach a certificate, roster, practicum form, transcript, or other supporting file to an employee or facility.\nGo to Documents and click Upload.\nSelect the facility and, if applicable, the specific employee this document belongs to.\nChoose the document type -- certificate, roster, practicum form, transcript, external certificate, competency attachment, or other.\nSelect the file and upload it.\nVerify it appears in the list, filtered by facility, employee, or document type as needed.\nOnly org_admin and facility_manager can delete an uploaded document -- not even the employee who uploaded it can remove it themselves.","source_audience":["org_admin","facility_manager"],"route_pattern":"/app/documents","sort_order":24,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"f24f2ff3-bdae-4096-b7f2-eab8b5095e34","content_key":"penntrain.help.job-aide.f24f2ff3-bdae-4096-b7f2-eab8b5095e34","article_type":"job_aide","category":"Reports","title":"Generate the Compliance Binder","summary":"Produce a single, survey-ready PDF covering a facility's roster, training compliance, practicums, certificates, and open alerts.","body_markdown":"Produce a single, survey-ready PDF covering a facility's roster, training compliance, practicums, certificates, and open alerts.\n\n## Steps\n\n1. Go to Compliance Binder.\n\n2. Click Generate Binder PDF.\n\n3. Wait for generation to complete, then click Download PDF.\n\n4. Download it promptly -- the link expires after a short window, so generate a new binder if it lapses before you've saved it.\n\n## Tips\n\n- The binder is built fresh from current data every time -- there's no stale cached version to worry about.\n\nRelated CareBase page: **Go to Compliance Binder** (/app/compliance-binder)","body_text":"Produce a single, survey-ready PDF covering a facility's roster, training compliance, practicums, certificates, and open alerts.\nGo to Compliance Binder.\nClick Generate Binder PDF.\nWait for generation to complete, then click Download PDF.\nDownload it promptly -- the link expires after a short window, so generate a new binder if it lapses before you've saved it.\nThe binder is built fresh from current data every time -- there's no stale cached version to worry about.","source_audience":["org_admin","facility_manager","auditor"],"route_pattern":"/app/compliance-binder","sort_order":25,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"8bdf566d-9ada-4c6d-8b74-b6580b6cdbd2","content_key":"penntrain.help.faq.8bdf566d-9ada-4c6d-8b74-b6580b6cdbd2","article_type":"faq","category":"Residents & Facility Compliance","title":"What does the Residents module actually track?","summary":"For personal care homes and assisted living facilities, Residents tracks RASP/ASP compliance deadlines by resident -- from preadmission screening through the annual reassessment cycle -- plus contacts and supports, a compliance checklist, digital assessment forms, and related documents. It's explicitly compliance-deadline tracking, not a charting or care-plan system.","body_markdown":"For personal care homes and assisted living facilities, Residents tracks RASP/ASP compliance deadlines by resident -- from preadmission screening through the annual reassessment cycle -- plus contacts and supports, a compliance checklist, digital assessment forms, and related documents. It's explicitly compliance-deadline tracking, not a charting or care-plan system.","body_text":"For personal care homes and assisted living facilities, Residents tracks RASP/ASP compliance deadlines by resident -- from preadmission screening through the annual reassessment cycle -- plus contacts and supports, a compliance checklist, digital assessment forms, and related documents. It's explicitly compliance-deadline tracking, not a charting or care-plan system.","source_audience":[],"route_pattern":null,"sort_order":25,"updated_at":"2026-07-13 06:08:50.303461+00"},{"id":"c33ab464-102a-4b4e-997b-bd3afbe0164e","content_key":"penntrain.help.faq.c33ab464-102a-4b4e-997b-bd3afbe0164e","article_type":"faq","category":"Residents & Facility Compliance","title":"Does CareMetric Train store clinical charting or care plans for residents?","summary":"No. The Residents module is scoped to compliance recordkeeping -- assessment/support-plan deadlines, contacts, and the documents that prove those deadlines were met -- not day-to-day clinical charting or care planning. That's a deliberate boundary, kept out of scope on purpose.","body_markdown":"No. The Residents module is scoped to compliance recordkeeping -- assessment/support-plan deadlines, contacts, and the documents that prove those deadlines were met -- not day-to-day clinical charting or care planning. That's a deliberate boundary, kept out of scope on purpose.","body_text":"No. The Residents module is scoped to compliance recordkeeping -- assessment/support-plan deadlines, contacts, and the documents that prove those deadlines were met -- not day-to-day clinical charting or care planning. That's a deliberate boundary, kept out of scope on purpose.","source_audience":[],"route_pattern":null,"sort_order":26,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"73e99997-f517-42e9-9e11-f4cfb38e9326","content_key":"penntrain.help.job-aide.73e99997-f517-42e9-9e11-f4cfb38e9326","article_type":"job_aide","category":"Reports","title":"Run a Compliance Report","summary":"Generate, view, print, or export a specific compliance report for your organization.","body_markdown":"Generate, view, print, or export a specific compliance report for your organization.\n\n## Steps\n\n1. Go to Reports.\n\n2. Optionally filter to a single facility.\n\n3. Use the category tabs (Compliance, Training, Practicum, Hours, Staff, Documents, Credentials, Incidents, and more) or search to find the report you want.\n\n4. Click the report to generate and view it.\n\n5. Use Export CSV to download the data, or print directly from the viewer.\n\n## Tips\n\n- Reports respect the same role-based scoping as the rest of the app -- an org_admin sees every facility, a facility_manager only their own.\n\nRelated CareBase page: **Go to Reports** (/app/reports)","body_text":"Generate, view, print, or export a specific compliance report for your organization.\nGo to Reports.\nOptionally filter to a single facility.\nUse the category tabs (Compliance, Training, Practicum, Hours, Staff, Documents, Credentials, Incidents, and more) or search to find the report you want.\nClick the report to generate and view it.\nUse Export CSV to download the data, or print directly from the viewer.\nReports respect the same role-based scoping as the rest of the app -- an org_admin sees every facility, a facility_manager only their own.","source_audience":["org_admin","facility_manager","auditor"],"route_pattern":"/app/reports","sort_order":26,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"7e8273dc-1b23-48e1-a0e1-f7d386b6147e","content_key":"penntrain.help.faq.7e8273dc-1b23-48e1-a0e1-f7d386b6147e","article_type":"faq","category":"Residents & Facility Compliance","title":"How do incidents and cited DHS violations connect to residents?","summary":"Incidents & Complaints lets you log and investigate reportable events, track required notifications (state hotline, family/guardian, law enforcement, licensing agency), and attach corrective actions -- some incidents reference a specific resident. Violations & Plans of Correction is separate: it's where you enter what a DHS inspection actually cited and manage that citation's Plan of Correction through to verification, whether or not a specific resident was involved.","body_markdown":"Incidents & Complaints lets you log and investigate reportable events, track required notifications (state hotline, family/guardian, law enforcement, licensing agency), and attach corrective actions -- some incidents reference a specific resident. Violations & Plans of Correction is separate: it's where you enter what a DHS inspection actually cited and manage that citation's Plan of Correction through to verification, whether or not a specific resident was involved.","body_text":"Incidents & Complaints lets you log and investigate reportable events, track required notifications (state hotline, family/guardian, law enforcement, licensing agency), and attach corrective actions -- some incidents reference a specific resident. Violations & Plans of Correction is separate: it's where you enter what a DHS inspection actually cited and manage that citation's Plan of Correction through to verification, whether or not a specific resident was involved.","source_audience":[],"route_pattern":null,"sort_order":27,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"ca23fe91-cf4b-4ab3-bac9-fae40997a5bd","content_key":"penntrain.help.job-aide.ca23fe91-cf4b-4ab3-bac9-fae40997a5bd","article_type":"job_aide","category":"Getting Help","title":"Submit a Support Ticket","summary":"Reach support directly from inside the app for anything the FAQ and Job Aides don't cover.","body_markdown":"Reach support directly from inside the app for anything the FAQ and Job Aides don't cover.\n\n## Steps\n\n1. Open the Help Center.\n\n2. Click the Submit a Ticket tab.\n\n3. Enter a subject and choose a category -- general question, technical issue, billing, training content, account access, or feature request.\n\n4. Choose a priority -- low, normal, high, or urgent.\n\n5. Describe the issue in the message field and submit.\n\n6. Your ticket appears under My Tickets, where you can keep replying in the same thread.\n\n## Tips\n\n- You'll get an in-app notification the moment support replies, so there's no need to keep checking back manually.\n\nRelated CareBase page: **Go to Help Center** (/app/help)","body_text":"Reach support directly from inside the app for anything the FAQ and Job Aides don't cover.\nOpen the Help Center.\nClick the Submit a Ticket tab.\nEnter a subject and choose a category -- general question, technical issue, billing, training content, account access, or feature request.\nChoose a priority -- low, normal, high, or urgent.\nDescribe the issue in the message field and submit.\nYour ticket appears under My Tickets, where you can keep replying in the same thread.\nYou'll get an in-app notification the moment support replies, so there's no need to keep checking back manually.","source_audience":["org_admin","facility_manager","trainer","auditor","employee"],"route_pattern":"/app/help","sort_order":27,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"fd8f3fd2-9cd6-4ec5-b927-8bed662b93f7","content_key":"penntrain.help.job-aide.fd8f3fd2-9cd6-4ec5-b927-8bed662b93f7","article_type":"job_aide","category":"Getting Help","title":"Check the Status of a Support Ticket","summary":"Track replies and resolution progress on a ticket you've already submitted.","body_markdown":"Track replies and resolution progress on a ticket you've already submitted.\n\n## Steps\n\n1. Open the Help Center and go to My Tickets.\n\n2. Find your ticket and check its status -- open, in progress, resolved, or closed.\n\n3. Open the ticket to read the full message thread, including any support replies.\n\n4. Reply in the thread if you need to add information.\n\n5. Once your issue is settled, close the ticket yourself -- or reopen a resolved/closed ticket if the issue comes back.\n\n## Tips\n\n- A ticket automatically moves from open to in progress the moment support sends its first reply.\n\nRelated CareBase page: **Go to My Tickets** (/app/help)","body_text":"Track replies and resolution progress on a ticket you've already submitted.\nOpen the Help Center and go to My Tickets.\nFind your ticket and check its status -- open, in progress, resolved, or closed.\nOpen the ticket to read the full message thread, including any support replies.\nReply in the thread if you need to add information.\nOnce your issue is settled, close the ticket yourself -- or reopen a resolved/closed ticket if the issue comes back.\nA ticket automatically moves from open to in progress the moment support sends its first reply.","source_audience":["org_admin","facility_manager","trainer","auditor","employee"],"route_pattern":"/app/help","sort_order":28,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"577d208c-7218-4250-8be9-df9b9aad4fc0","content_key":"penntrain.help.faq.577d208c-7218-4250-8be9-df9b9aad4fc0","article_type":"faq","category":"Residents & Facility Compliance","title":"What's the Inspection Readiness score based on, and is it a live DHS feed?","summary":"It's a weighted rollup of your own compliance data -- training, credentials, background checks, inspection items, incidents, and policy attestations -- grouped by DHS citation topic and weighted by a default per-topic planning weight. It is not a live BHSL citation-frequency feed; the weighting is a planning aid, not a prediction of what a real survey will cite.","body_markdown":"It's a weighted rollup of your own compliance data -- training, credentials, background checks, inspection items, incidents, and policy attestations -- grouped by DHS citation topic and weighted by a default per-topic planning weight. It is not a live BHSL citation-frequency feed; the weighting is a planning aid, not a prediction of what a real survey will cite.","body_text":"It's a weighted rollup of your own compliance data -- training, credentials, background checks, inspection items, incidents, and policy attestations -- grouped by DHS citation topic and weighted by a default per-topic planning weight. It is not a live BHSL citation-frequency feed; the weighting is a planning aid, not a prediction of what a real survey will cite.","source_audience":[],"route_pattern":null,"sort_order":28,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"45ba4f7f-646f-4969-952b-88e984bd22e1","content_key":"penntrain.help.faq.45ba4f7f-646f-4969-952b-88e984bd22e1","article_type":"faq","category":"Credentials & Background Checks","title":"What kinds of credentials can I track on an employee?","summary":"Credentials & Clearances covers Act 34 criminal history, Act 73 FBI fingerprint, and Act 33 child abuse clearances, RN/LPN licenses, Nurse Aide Registry status, TB screening, immunization records, I-9 employment eligibility, and a catch-all Other category -- each with its own expiration tracking and status.","body_markdown":"Credentials & Clearances covers Act 34 criminal history, Act 73 FBI fingerprint, and Act 33 child abuse clearances, RN/LPN licenses, Nurse Aide Registry status, TB screening, immunization records, I-9 employment eligibility, and a catch-all Other category -- each with its own expiration tracking and status.","body_text":"Credentials & Clearances covers Act 34 criminal history, Act 73 FBI fingerprint, and Act 33 child abuse clearances, RN/LPN licenses, Nurse Aide Registry status, TB screening, immunization records, I-9 employment eligibility, and a catch-all Other category -- each with its own expiration tracking and status.","source_audience":[],"route_pattern":null,"sort_order":29,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"7968e9a0-b2c1-453f-8ebd-16fd7c035dd4","content_key":"penntrain.help.faq.7968e9a0-b2c1-453f-8ebd-16fd7c035dd4","article_type":"faq","category":"Credentials & Background Checks","title":"How does the OAPSA provisional-employment countdown work?","summary":"Background Checks tracks whether an employee has been a PA resident for the prior two years, since that determines whether they can start work provisionally before clearances come back and how many days they get: your organization's configured provisional window (30 days for residents, 90 for non-residents, by default) counts down from the provisional start date, with a clear warning once only a few days remain.","body_markdown":"Background Checks tracks whether an employee has been a PA resident for the prior two years, since that determines whether they can start work provisionally before clearances come back and how many days they get: your organization's configured provisional window (30 days for residents, 90 for non-residents, by default) counts down from the provisional start date, with a clear warning once only a few days remain.","body_text":"Background Checks tracks whether an employee has been a PA resident for the prior two years, since that determines whether they can start work provisionally before clearances come back and how many days they get: your organization's configured provisional window (30 days for residents, 90 for non-residents, by default) counts down from the provisional start date, with a clear warning once only a few days remain.","source_audience":[],"route_pattern":null,"sort_order":30,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"bda4175f-a7ee-4436-9f79-dc9edea7ac7d","content_key":"penntrain.help.faq.bda4175f-a7ee-4436-9f79-dc9edea7ac7d","article_type":"faq","category":"Credentials & Background Checks","title":"Who can see credential and background-check data?","summary":"It's more restricted than most compliance data: org_admin, facility_manager, and auditor can see it, but trainer cannot -- clearance and license information is treated as more sensitive than ordinary training records.","body_markdown":"It's more restricted than most compliance data: org_admin, facility_manager, and auditor can see it, but trainer cannot -- clearance and license information is treated as more sensitive than ordinary training records.","body_text":"It's more restricted than most compliance data: org_admin, facility_manager, and auditor can see it, but trainer cannot -- clearance and license information is treated as more sensitive than ordinary training records.","source_audience":[],"route_pattern":null,"sort_order":32,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"e91d556e-3976-4979-89cb-b2bc86a68159","content_key":"penntrain.help.faq.e91d556e-3976-4979-89cb-b2bc86a68159","article_type":"faq","category":"Credentials & Background Checks","title":"What does the Administrator Qualification module cover?","summary":"For personal care homes and assisted living facilities, it tracks the administrator's qualification path -- the 100-hour DHS-approved administrator course or the NHA license exemption -- the written regional-office verification submission, and the rolling 24-hour annual continuing-education requirement, with the source and supporting documentation captured for each CE entry.","body_markdown":"For personal care homes and assisted living facilities, it tracks the administrator's qualification path -- the 100-hour DHS-approved administrator course or the NHA license exemption -- the written regional-office verification submission, and the rolling 24-hour annual continuing-education requirement, with the source and supporting documentation captured for each CE entry.","body_text":"For personal care homes and assisted living facilities, it tracks the administrator's qualification path -- the 100-hour DHS-approved administrator course or the NHA license exemption -- the written regional-office verification submission, and the rolling 24-hour annual continuing-education requirement, with the source and supporting documentation captured for each CE entry.","source_audience":[],"route_pattern":null,"sort_order":33,"updated_at":"2026-07-23 08:46:29.818663+00"},{"id":"b08aa5a7-7f6d-471c-9c76-f58194c9cd6c","content_key":"penntrain.help.faq.b08aa5a7-7f6d-471c-9c76-f58194c9cd6c","article_type":"faq","category":"Reports & Compliance Binder","title":"What reports can I run?","summary":"Reports covers compliance summaries and facility scores, expired/due-soon/overdue training, medication administration training, the training matrix, practicum status (including the annual practicum report), training hours (annual and detail), trainer certification status, new-employee and full transcripts, expiring certifications, missing documents and a document audit, credential and clearance status, incident logs and notification registers, and inspection/equipment compliance -- filterable by","body_markdown":"Reports covers compliance summaries and facility scores, expired/due-soon/overdue training, medication administration training, the training matrix, practicum status (including the annual practicum report), training hours (annual and detail), trainer certification status, new-employee and full transcripts, expiring certifications, missing documents and a document audit, credential and clearance status, incident logs and notification registers, and inspection/equipment compliance -- filterable by facility and exportable.","body_text":"Reports covers compliance summaries and facility scores, expired/due-soon/overdue training, medication administration training, the training matrix, practicum status (including the annual practicum report), training hours (annual and detail), trainer certification status, new-employee and full transcripts, expiring certifications, missing documents and a document audit, credential and clearance status, incident logs and notification registers, and inspection/equipment compliance -- filterable by facility and exportable.","source_audience":[],"route_pattern":null,"sort_order":34,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"42708a24-eb3d-4b8c-b064-c9afa4d430eb","content_key":"penntrain.help.faq.42708a24-eb3d-4b8c-b064-c9afa4d430eb","article_type":"faq","category":"Reports & Compliance Binder","title":"How is the Compliance Binder different from just running a report?","summary":"A report is a table you view, print, or export as CSV. The Compliance Binder is a single generated PDF that pulls a facility's roster, staff training compliance, practicums, certificates, and open alerts together into one survey-ready packet in one click -- built fresh from current data every time you generate it, not a print-to-PDF of a report screen.","body_markdown":"A report is a table you view, print, or export as CSV. The Compliance Binder is a single generated PDF that pulls a facility's roster, staff training compliance, practicums, certificates, and open alerts together into one survey-ready packet in one click -- built fresh from current data every time you generate it, not a print-to-PDF of a report screen.","body_text":"A report is a table you view, print, or export as CSV. The Compliance Binder is a single generated PDF that pulls a facility's roster, staff training compliance, practicums, certificates, and open alerts together into one survey-ready packet in one click -- built fresh from current data every time you generate it, not a print-to-PDF of a report screen.","source_audience":[],"route_pattern":null,"sort_order":35,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"dc53c1f3-feae-4969-b1c5-0eabc4263ee4","content_key":"penntrain.help.faq.dc53c1f3-feae-4969-b1c5-0eabc4263ee4","article_type":"faq","category":"Reports & Compliance Binder","title":"How long is the Compliance Binder download link good for?","summary":"The generated PDF is delivered through a short-lived signed link, not a permanent public URL, so it typically expires within a few minutes. If it expires before you've downloaded it, just generate a fresh binder -- it only takes a few seconds.","body_markdown":"The generated PDF is delivered through a short-lived signed link, not a permanent public URL, so it typically expires within a few minutes. If it expires before you've downloaded it, just generate a fresh binder -- it only takes a few seconds.","body_text":"The generated PDF is delivered through a short-lived signed link, not a permanent public URL, so it typically expires within a few minutes. If it expires before you've downloaded it, just generate a fresh binder -- it only takes a few seconds.","source_audience":[],"route_pattern":null,"sort_order":36,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"c029ac2d-630f-4c9e-9a6c-4fe3c5eb21fe","content_key":"penntrain.help.faq.c029ac2d-630f-4c9e-9a6c-4fe3c5eb21fe","article_type":"faq","category":"Reports & Compliance Binder","title":"Can an auditor run reports and generate the binder themselves, or do they have to ask an admin?","summary":"Auditors can run reports and generate the compliance binder themselves -- both are part of the read-only compliance view auditors get alongside org_admin and facility_manager. They just can't create, edit, or delete the underlying records those reports summarize.","body_markdown":"Auditors can run reports and generate the compliance binder themselves -- both are part of the read-only compliance view auditors get alongside org_admin and facility_manager. They just can't create, edit, or delete the underlying records those reports summarize.","body_text":"Auditors can run reports and generate the compliance binder themselves -- both are part of the read-only compliance view auditors get alongside org_admin and facility_manager. They just can't create, edit, or delete the underlying records those reports summarize.","source_audience":[],"route_pattern":null,"sort_order":37,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"7e3c9d30-68c2-4c2c-ad55-90ed68543040","content_key":"penntrain.help.faq.7e3c9d30-68c2-4c2c-ad55-90ed68543040","article_type":"faq","category":"Support & Account","title":"How do I contact support?","summary":"From the Help Center, open the Submit a Ticket tab, pick a category (general question, technical issue, billing, training content, account access, or feature request) and a priority, describe what's going on, and submit. Your message becomes the first entry in a ticket thread you can keep replying to.","body_markdown":"From the Help Center, open the Submit a Ticket tab, pick a category (general question, technical issue, billing, training content, account access, or feature request) and a priority, describe what's going on, and submit. Your message becomes the first entry in a ticket thread you can keep replying to.","body_text":"From the Help Center, open the Submit a Ticket tab, pick a category (general question, technical issue, billing, training content, account access, or feature request) and a priority, describe what's going on, and submit. Your message becomes the first entry in a ticket thread you can keep replying to.","source_audience":[],"route_pattern":null,"sort_order":38,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"2a45a87f-4d80-4d34-b6a2-2634fd10ed55","content_key":"penntrain.help.faq.2a45a87f-4d80-4d34-b6a2-2634fd10ed55","article_type":"faq","category":"Support & Account","title":"How do I check the status of a ticket I already submitted?","summary":"Open My Tickets in the Help Center to see every ticket you've filed and its current status -- open, in progress, resolved, or closed. You'll get an in-app notification the moment support replies or changes your ticket's status, and you can reply right in the thread or close/reopen the ticket yourself once it's settled.","body_markdown":"Open My Tickets in the Help Center to see every ticket you've filed and its current status -- open, in progress, resolved, or closed. You'll get an in-app notification the moment support replies or changes your ticket's status, and you can reply right in the thread or close/reopen the ticket yourself once it's settled.","body_text":"Open My Tickets in the Help Center to see every ticket you've filed and its current status -- open, in progress, resolved, or closed. You'll get an in-app notification the moment support replies or changes your ticket's status, and you can reply right in the thread or close/reopen the ticket yourself once it's settled.","source_audience":[],"route_pattern":null,"sort_order":39,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"9fa70641-0aa8-4718-9095-ee33dce51902","content_key":"penntrain.help.faq.9fa70641-0aa8-4718-9095-ee33dce51902","article_type":"faq","category":"Support & Account","title":"Where do I find the full PDF user manual?","summary":"The Help Center links directly to a downloadable PDF user manual alongside the FAQ and Job Aides, for anyone who wants the complete walkthrough in one document or needs an offline copy.","body_markdown":"The Help Center links directly to a downloadable PDF user manual alongside the FAQ and Job Aides, for anyone who wants the complete walkthrough in one document or needs an offline copy.","body_text":"The Help Center links directly to a downloadable PDF user manual alongside the FAQ and Job Aides, for anyone who wants the complete walkthrough in one document or needs an offline copy.","source_audience":[],"route_pattern":null,"sort_order":40,"updated_at":"2026-07-06 17:10:59.03863+00"},{"id":"4fb36715-6c43-4566-b22c-f92dbf41f966","content_key":"penntrain.help.faq.4fb36715-6c43-4566-b22c-f92dbf41f966","article_type":"faq","category":"Support & Account","title":"How do I reset my password or update my account details?","summary":"Use the Forgot Password link from the login screen to reset your password. For changes to your name, role, or organization, ask your org_admin or facility_manager -- email address changes specifically require an admin action, so contact platform support if you need yours updated.","body_markdown":"Use the Forgot Password link from the login screen to reset your password. For changes to your name, role, or organization, ask your org_admin or facility_manager -- email address changes specifically require an admin action, so contact platform support if you need yours updated.","body_text":"Use the Forgot Password link from the login screen to reset your password. For changes to your name, role, or organization, ask your org_admin or facility_manager -- email address changes specifically require an admin action, so contact platform support if you need yours updated.","source_audience":[],"route_pattern":null,"sort_order":41,"updated_at":"2026-07-06 17:10:59.03863+00"}]$articles$::jsonb) as row_data (
    id uuid,
    content_key text,
    article_type text,
    category text,
    title text,
    summary text,
    body_markdown text,
    body_text text,
    source_audience jsonb,
    route_pattern text,
    sort_order integer,
    updated_at timestamptz
  )
),
upserted_items as (
  insert into hub.content_items (
    id, content_key, kind, status, access_level, owner_product_id,
    owner_team, source_system, created_at, updated_at
  )
  select
    md5('penntrain-help-item:' || id::text)::uuid,
    content_key,
    'article',
    'published',
    'customer',
    (select id from hub.products where slug = 'carebase'),
    'CareMetric Support',
    'penntrain',
    coalesce(updated_at, now()),
    coalesce(updated_at, now())
  from source_rows
  on conflict (id) do update set
    content_key = excluded.content_key,
    status = excluded.status,
    access_level = excluded.access_level,
    owner_product_id = excluded.owner_product_id,
    owner_team = excluded.owner_team,
    source_system = excluded.source_system,
    updated_at = excluded.updated_at
  returning id
),
upserted_revisions as (
  insert into hub.content_revisions (
    id, item_id, revision_no, locale, title, summary, body_markdown, body_text,
    variables, source_hash, source_version, review_state, approved_at, created_at
  )
  select
    md5('penntrain-help-revision:' || row_data.id::text)::uuid,
    md5('penntrain-help-item:' || row_data.id::text)::uuid,
    1,
    'en-US',
    row_data.title,
    row_data.summary,
    row_data.body_markdown,
    row_data.body_text,
    jsonb_build_object(
      'category', row_data.category,
      'article_type', row_data.article_type,
      'source_audience', row_data.source_audience,
      'sort_order', row_data.sort_order
    ),
    md5(row_data.id::text || ':' || row_data.title || ':' || row_data.body_text),
    'PennTrain:help:' || coalesce(row_data.updated_at::text, 'unknown'),
    'approved',
    coalesce(row_data.updated_at, now()),
    coalesce(row_data.updated_at, now())
  from source_rows row_data
  on conflict (id) do nothing
  returning id
)
insert into hub.content_publications (
  item_id, revision_id, product_id, audience, route_pattern, published_at
)
select
  md5('penntrain-help-item:' || source_rows.id::text)::uuid,
  md5('penntrain-help-revision:' || source_rows.id::text)::uuid,
  product.id,
  case
    when jsonb_typeof(source_rows.source_audience) = 'array'
      and jsonb_array_length(source_rows.source_audience) = 0
      then array['all']::text[]
    else array['staff-review']::text[]
  end,
  source_rows.route_pattern,
  coalesce(source_rows.updated_at, now())
from source_rows
join hub.products product on product.slug = 'carebase'
on conflict (item_id, product_id) do update set
  revision_id = excluded.revision_id,
  audience = excluded.audience,
  route_pattern = excluded.route_pattern,
  published_at = excluded.published_at,
  expires_at = null
where excluded.published_at >= hub.content_publications.published_at;
